object Main extends App {

  import scala.io.StdIn._


  val n = readLine.trim.toInt
  val chars = readLine.trim.toCharArray
  val q = readLine.trim.toInt
  val index = readLine.trim.split(' ').map(_.toInt)
  val counter = Counter(chars)
  val indices = index.zipWithIndex
  val memo = Array.tabulate(index.length){ _ ⇒ 0L}
  val result = Array.tabulate(index.length){ _ ⇒ 0L}
  println(
    search(0, chars, counter, indices, memo, result).mkString("\n")
  )
  case class Counter(chars: Array[Char]){
    private val mDCount = chars.map{c ⇒ if (c == 'D') 1 else 0 : Int}.also{a ⇒ for (i ← 1 until chars.size) a(i) += a(i - 1)}
    private val mMCount = chars.map{ c ⇒ if (c == 'M') 1 else 0 : Int}.also{ a ⇒ for (i ← 1 until chars.size) a(i) += a(i - 1)}
    def dSum(from: Int, to: Int): Int = {
      val left = (from - 1) match {
        case i if mDCount.indices.contains(i) ⇒ mDCount(i)
        case _ ⇒ 0
      }
      val right = to match {
        case i if mDCount.indices.contains(i) ⇒ mDCount(i)
        case i if i < 0 ⇒ 0
        case _ ⇒ mDCount.last
      }
      right - left
    }
    def mSum(from: Int, to: Int): Int = {
      val left = (from - 1) match {
        case i if mMCount.indices.contains(i) ⇒ mMCount(i)
        case _ ⇒ 0
      }
      val right = to match {
        case i if mMCount.indices.contains(i) ⇒ mMCount(i)
        case i if i < 0 ⇒ 0
        case _ ⇒ mMCount.last
      }
      right - left
    }
  }
  def search(currentPosition: Int, chars: Array[Char], counter: Counter, indices: Array[(Int, Int)], memo: Array[Long], result: Array[Long]): Array[Long] = {

    if (currentPosition == chars.length){
      result
    }else {
      for ((k, i) ← indices.filter{case (k, i) ⇒ chars.indices.contains(currentPosition - k) && chars(currentPosition - k) == 'D'}) {
        memo(i) -= counter.mSum(currentPosition - k + 1, currentPosition - 1)
      }
      chars(currentPosition) match {
        case 'M' ⇒
          for ((k, i) ← indices) {
            memo(i) += counter.dSum(currentPosition - k + 1, currentPosition - 1)
          }
        case 'C' ⇒
          for ((_, i) ← indices){
            result(i) += memo(i)
          }
        case _ ⇒
      }
      search(currentPosition + 1, chars, counter, indices, memo, result)
    }
  }
  implicit class Extenion[T](val value :T){
    def also(func: T ⇒ Unit): T = {
      func(value)
      value
    }
    def let[R](func: T ⇒ R): R = func(value)
  }
}

