      ll r = lower_bound(Cf.begin(),Cf.end(),Df[i]+k) - Cf.begin() - 1;
      ll res = bit.sum(l,r+1);
      res -= Ds[i] * (r - l + 1);
      ans += res;
    }
    cout << ans << endl;
  }
  return 0;
}

