template < class T > inline void fastScan(T &x) {
    register char c = getchar();
    int neg = 0; x = 0;
    for(   ; (c < 48 || c > 57) && (c != '-'); c = getchar());
    if(c == '-') { neg = 1; c = getchar(); }
    for(   ; c > 47 && c < 58; c = getchar()){
        x = (x << 1) + (x << 3) + c - 48;
    }
    if(neg) x = -x;
}

char s[N];

ll seg[2][N * 4];

void build(int id, int x, int b, int e){
  if(b == e){
    seg[id][x] = 0;
    return ;
  }
  int m = (b + e) >> 1;
  build(id, x + x, b, m);
  build(id, x + x + 1, m + 1, e);
  seg[id][x] = 0;
}

void modify(int id, int x, int b, int e, int l, int r, int v){
  if(b > r || e < l) return ;
  if(b >= l && e <= r){
    seg[id][x] += v;
    return ;
  }
  int m = (b + e) >> 1;
  modify(id, x + x, b, m, l, r, v);
  modify(id, x + x + 1, m + 1, e, l, r, v);
}

ll get(int id, int x, int b, int e, int l, int r, ll hand = 0){
  if(b > r || e < l) return 0;
  if(b >= l && e <= r){
    return seg[id][x] + hand;
  }
  int m = (b + e) >> 1;
  return get(id, x + x, b, m, l, r, hand + seg[id][x]) +
         get(id, x + x + 1, m + 1, e, l, r, hand + seg[id][x]);
}

int main(){
  int n; fastScan(n);
  scanf("%s", s);
  int len = strlen(s) - 1;
  int q; fastScan(q);
  while(q--){
    int k; fastScan(k);
    build(0, 1, 0, len);
    build(1, 1, 0, len);
    ll prv = 0;
    for(int i = 0; i <= len; i++){
      if(s[i] == 'M'){
        modify(0, 1, 0, len, 0, i, +1);
      }
      if(s[i] == 'C'){
        ll tmp = get(0, 1, 0, len, 0, 0);
        modify(1, 1, 0, len, max(0, i - k + 1), i, tmp);
        prv = tmp;
      }
    }
    ll answer = 0;
    for(int i = 0; i <= len; i++){
      if(s[i] == 'D'){
        answer += get(1, 1, 0, len, i, i);
      }
    }
    printf("%lld\n", answer);
  }
}

