	ll ret = 0;
	ll tmp = 0;
	for(int i = 0;i < k;i++) {
		if(s[i] == 'M') cntM++;
		else if(s[i] == 'C') {
			cntC++;
			tmp += cntM;
		}
	}
	if(s[0] == 'D') ret += tmp;

	for(int i = 1;i < n;i++) {
		if(i+k-1 < n) {
			if(s[i+k-1] == 'M') cntM++;
			else if(s[i+k-1] == 'C') {
				cntC++;
				tmp += cntM;
			}
		}

		if(s[i] == 'D') ret += tmp;
		else if(s[i] == 'M') {
			tmp -= cntC;
			cntM--;
		}
		else if(s[i] == 'C') {
			cntC--;
		}
	}
	return ret;
}

