void solve() {
    i64 N = RD();
    auto S = RD<string>();
    i64 Q = RD();

    REP(_, Q) {
        i64 k = RD();

        i64 ans  = 0;
        i64 n_d  = 0;
        i64 n_m  = 0;
        i64 n_dm = 0;
        REP(i, N) {
            char c = S[i];
            if(c == 'D') {
                ++n_d;
            }
            else if(c == 'M') {
                ++n_m;
                n_dm += n_d;
            }
            else if(c == 'C') {
                ans += n_dm;
            }

            if(i >= k-1) {
                char cc = S[i-k+1];
                if(cc == 'D') {
                    --n_d;
                    n_dm -= n_m;
                }
                else if(cc == 'M') {
                    --n_m;
                }
            }
            DBG(k,i,n_d,n_m,n_dm,ans);
        }

        PRINTLN(ans);
    }
}

signed main() {


    solve();

    return 0;
}

