	  dmnum -= mnum;
	}else if (S.at(j-k.at(i)) == 'M'){
	  mnum -= 1;
	}
      }

      if (S.at(j) == 'D'){
	dnum += 1;
      }else if (S.at(j) == 'M'){
	mnum += 1;
	dmnum += dnum;
      }else if (S.at(j) == 'C'){
	ans += dmnum;
      }

    }

    cout << ans << endl;

  }

  return 0;
}

