    for (ll k: ks){
        ll ans = 0; ll sz = ds.size();
        for (ll l: ds){
            ll lb = lower_bound(all(cs), l) - cs.begin();
            ll ub = upper_bound(all(cs), l + k - 1) - cs.begin();
            For(j, lb, ub){
                ll r = cs[j];
                ans += bit.query(l, r);
            }
        }
        prl(ans);
    }

    // ### DEBUG PART ###
