    cin >> K;
    CumulativeSum<ll> cs_m(N);
    REP(i, S.length()) {
        if(S[i] == 'M') { cs_m.Add(i, 1); }
    }
    cs_m.Build();
    ll ans = 0;
    ll l = 0, r = 2;
    bool isFindD = true;
    while(l < S.length() && r < S.length()) {
        printf("l: %lld r: %lld\n", l, r);
        if(S[l] == 'D' && S[r] == 'C') {
            ans += cs_m.Query(l, r);
            if(isFindD) { l++; }
            else { r++; }
        }
        if(isFindD) {
            while(l < S.length()) {
                if(S[l] == 'D') { break; }
                l++;
            }
            if(l >= S.length()) { break; }
            if(l >= r) { r = l + 2; }
            isFindD = false;
        }
        else {
            while(r < S.length() && r - l < K) {
                if(S[r] == 'C') { break; }
                r++;
            }
            if(r >= S.length()) { break; }
            //if(l >= r) { r = l + 2; }
            isFindD = true;
        }
    }
    printf("%lld\n", ans);
}

