// Mを全探索して、左x以内
// 距離k未満のDCのペアを全て見て間に挟まってるMの個数を足す → なかなかしんどそう
// クエリをソートしても良いことはあんまりなさそう
// 各Dから距離k未満のMの個数はO(1)にできる
// 逆にMの(左のD)*(右のC)をまず計算して、k以上離れたDMCを計算した方が楽？
// 各Dから必要なのは
// 「k以上離れたCについて、DとそのCの間のMの個数」
// Cを見る度にいままでのMの個数を足していったものを保持しとけばいい？

int n, Q, k, d[1001001], c[1001001], cnt[1001001], ml[1001001];
string s;

signed main() {
	cin >> n >> s >> Q;
	rep(i,n) {
		if (s[i]=='D') d[i]++;
		d[i+1] += d[i];
	}
	repr(i,n-1) {
		if (s[i]=='C') c[i]++;
		c[i] += c[i+1];
	}
	int m = 0;
	rep(i,n) {
		if (s[i]=='M') m++;
		if (s[i]=='C') cnt[i] += m;
		cnt[i+1] += cnt[i];
		ml[i] = m;
	}
	int tres = 0;
	rep(i,n) if (s[i]=='M') tres += d[i] * c[i];
	while (Q--) {
		cin >> k;
		int res = tres;
		rep(i,n) if (s[i]=='D') res -= cnt[n-1] - cnt[min(n-1,i+k-1)] - ml[i]*c[min(n,i+k)];
		cout << res << endl;
	}
}

