#include<bits/stdc++.h>
#define ll long long
using namespace std;
#define maxn 1000010
#define mod 1000000007
ll tr[maxn*4],p[maxn*4];
int a1[maxn],a2[maxn],a3[maxn],cnt1=0,cnt2=0,cnt3=0;
char s[maxn];
void bu(int x,int l,int r){
    tr[x]=p[x]=0;
    if(l!=r){
        bu(x*2,l,(l+r)/2);
        bu(x*2+1,(l+r)/2+1,r);
    }
}
void up(int x,int l,int r){
    if(p[x]){
        if(l!=r){
            int mid=(l+r)/2;
            p[x*2]+=p[x];
            p[x*2+1]+=p[x];
            tr[x*2]+=(mid-l+1)*p[x];
            tr[x*2+1]+=(r-mid)*p[x];
        }
        p[x]=0;
    }
}
void cg(int x,int l,int r,int s,int e,ll y){
    if(l>=s&&r<=e){
        tr[x]+=(r-l+1)*y;
        p[x]+=y;
        return ;
    }
    up(x,l,r);
    int mid=(l+r)/2;
    if(mid>=e) cg(x*2,l,mid,s,e,y);
    else if(mid<s) cg(x*2+1,mid+1,r,s,e,y);
    else{
        cg(x*2,l,mid,s,e,y);
        cg(x*2+1,mid+1,r,s,e,y);
    }
    tr[x]=tr[x*2]+tr[x*2+1];
}
ll sol(int x,int l,int r,int s,int e){
    if(l>=s&&r<=e) return tr[x];
    up(x,l,r);
    int mid=(l+r)/2;
    if(mid>=e) return sol(x*2,l,mid,s,e);
    else if(mid<s) return sol(x*2+1,mid+1,r,s,e);
    else{
        return sol(x*2,l,mid,s,e)+sol(x*2+1,mid+1,r,s,e);
    }
}
