    int n;
    scanf("%d",&n);
    scanf("%s",s);
    for(int i=0;i<n;i++){
        if(s[i]=='D') a1[cnt1++]=i;
        if(s[i]=='M') a2[cnt2++]=i;
        if(s[i]=='C') a3[cnt3++]=i;
    }
    int q,k;
    scanf("%d",&q);
    while(q--){
        scanf("%d",&k);
        bu(1,0,cnt2-1);
        ll ans=0;
        int l=0,r=0,rr=0;
        int f=1;
        for(int i=0;i<cnt1;i++){
            while(a1[i]>a2[l]&&l<cnt2){
                l++;
                //printf("%d---\n",l);
            }
            if(l==cnt2) break;
            r=max(r,l);
            if(a2[r]-a1[i]>k) continue;
            while(a2[r]>a3[rr]&&rr<cnt3){
                rr++;
                //printf("%d^^^\n",rr);
            }
            if(rr==cnt3) break;
            while(a3[rr]-a1[i]<k&&rr<cnt3&&f==1){
                while(r<cnt2-1){
                    if(a2[r+1]<a3[rr]) r++;
                    else break;
                }
                cg(1,0,cnt2-1,l,r,1);
                if(rr==cnt3-1){
                    f=0;
                    break;
                }
                rr++;
            }
            ans+=sol(1,0,cnt2-1,l,r);
            //printf("%lld  %d\n",ans,i);
        }
        printf("%lld\n",ans);
    }
    return 0;
}

