LL solve(int n, string s, int k) {
	LL ret = 0;
	LL D = 0, M = 0, DM = 0;
	rep(i, n) {

		switch (s[i]) {
		case 'D':
			D++;
			break;
		case 'M':
			M++;
			DM += D;
			break;
		case 'C':
			ret += DM;
			break;
		}

		if (i - k + 1 < 0)continue;

		switch (s[i - k + 1]) {
		case 'D':
			D--;
			DM -= M;
			break;
		case 'M':
			M--;
			break;
		}
	}

	return ret;
}

