unsigned long long solve(unsigned long long x) {
  unsigned long long now = 0, ans = 0;
  for(unsigned long long i = 0; i < n; ++i) {
    if(i >= x && s[i - x] == 'D') {
      if(i != 0) now -= cnt[i - 1][1];
      now += cnt[i - x][1];
    }
    if(s[i] == 'M') {
      if(i != 0) now += cnt[i - 1][0];
      if(i >= x) now -= cnt[i - x][0];
    }
    else if(s[i] == 'C') {
      ans += now;
    }
  }
  return ans;
}

