                sum -= cmcnt[pj];
                ++pj;
                --c;
            }
            while (j < ci.size() && ci[j] - di[i] < k) {
                sum += cmcnt[j];
                ++j;
                ++c;
            }
            ans += max(0LL, sum - dmcnt[i] * (long long)c);
