class SlideMinDeque {
public:
    SlideMinDeque(int size) : _size(size) {
        deq.clear();
    }

    void add(int index) {
        deq.push_back(index);
    }

    int get(int index) { //何かを排出した
      int ret = -1;
      while(deq.size()) {
          if(deq.front() <= index-_size) {
              ret = deq.front();
              deq.pop_front();
          } else {
              return ret;
          }
      }
      return ret;
    }

    int getSize()
    {
      return deq.size();
    }

private:
    int _size;
    deque<int> deq; 
};

