int ruin(int a, int n, int p) {
	if (n == 0) {
		return (1%p);
	}
	else {
	int x = ruin(a, (n - (n % 2)) / 2, p);
		if (n % 2 == 0) {
			return (x*x) % p;
		}
		else {
			return (((x*x) % p)*a) % p;

		}

