class Solution {
 public:
  void solve(std::istream& in, std::ostream& out) {
    int n;
    string s;
    in >> n >> s;
    int q;
    in >> q;
    while (q--) {
      int k;
      in >> k;
      ll rez = 0;
      ll dp[2] = {0}, occ_b = 0;
      for (int ctr1 = 0; ctr1 < n; ++ctr1) {
        if (ctr1 >= k) {
          if (s[ctr1 - k] == 'D')
            --dp[0], dp[1] -= occ_b;
          if (s[ctr1 - k] == 'M')
            --occ_b;
        }
        if (s[ctr1] == 'D')
          ++dp[0];
        if (s[ctr1] == 'M')
          dp[1] += dp[0], ++occ_b;
        if (s[ctr1] == 'C')
          rez += dp[1];
      }
      out << rez << "\n";
    }
  }
};

void solve(std::istream& in, std::ostream& out)
{
  out << std::setprecision(12);
  Solution solution;
  solution.solve(in, out);
}
