using namespace std;
using ll = int64_t;

ll solve(int N, const string& S, int k) {
  ll answer = 0;
  ll currentSum = 0;

  deque<int> dPositions;
  deque<int> mPositions;

  for (int i = 0; i < N; i++) {
    char c = S[i];

    if (!dPositions.empty() && dPositions.front() + k == i) {
      dPositions.pop_front();
      currentSum -= mPositions.size();
    }
    if (!mPositions.empty() && mPositions.front() + k == i) {
      mPositions.pop_front();
    }
    assert(currentSum >= 0);

    if (c == 'D') {
      dPositions.push_back(i);
    } else if (c == 'M') {
      mPositions.push_back(i);
      currentSum += dPositions.size();
    } else if (c == 'C') {
      answer += currentSum;
    }
  }

  return answer;
}

