  ios_base::sync_with_stdio(false);
  cin.tie(nullptr);

  int N;
  cin >> N;
  string S;
  cin >> S;
  int Q;
  cin >> Q;
  for (int q = 0; q < Q; q++) {
    int k;
    cin >> k;
    cout << solve(N, S, k) << "\n";
  }

  return 0;
}

