int _main()
{
    ll n; llin(n);
    string s; CIN(s);
    ll qcount; llin(qcount);
    V<ll> klist; llina(klist, qcount);

    V<ll> dlist;
    rep (i, s.size()) if (s[i] == 'D') dlist.pb(i);

