class SlideMinDeque {
public:
    using LI = pair<long long, int>;
    SlideMinDeque(int size) : _size(size) {
        deq.clear();
    }

    void add(long long value, int index) {
        deq.push_back(LI(value, index));
    }

    bool get(int index) { //何かを排出した
      bool ret = false;
      while(deq.size()) {
          if(deq.front().second <= index-_size) {
              deq.pop_front();
              ret = true;
          } else {
              return ret;
          }
      }
      return ret;
    }

private:
    int _size;
    deque<LI> deq; 
};

