void add(int pos) {
	if (pos == 0) num_M++;
	else { sum += num_M; num_C++; }
}
void lose(int pos) {
	if (pos == 0) { sum -= num_C; num_M--; }
	else num_C--;
}

long long query(long long pos) {
	num_M = 0; num_C = 0; sum = 0;
	for (int i = 0; i < pos; i++) {
		if (S[i] == 'M') add(0);
		if (S[i] == 'C') add(1);
	}
	long long ans = 0;
	for (int i = pos; i < N + pos; i++) {
		if (S[i - pos] == 'D') ans += sum;
		if (S[i - pos] == 'M') lose(0);
		if (S[i - pos] == 'C') lose(1);
		if (i < N) {
			if (S[i] == 'M') add(0);
			if (S[i] == 'C') add(1);
		}
	}
	return ans;
}

