constexpr int MAX_SIZE = 1e6;
char str[MAX_SIZE + 10];
std::vector<int> D;
std::vector<int> A;

int solve(int n, int k){
    // A[i] := [i, i+k)で作れるMCの数
    A[0] = 0;
    int res = 0;
    int i, j;
    int m = 0, c = 0;
    for(j = 0; j < k; ++j){
        if(str[j] == 'M')  m++;
        else if(str[j] == 'C'){ c++; A[0] += m; }
    }
    for(i = 1; i < n; ++i){
        A[i] = A[i-1];
        // 失われるのは str[i-1]
        if(str[i-1] == 'M'){
            m--; A[i] -= c;
        }
        else if(str[i-1] == 'C') c--;

        if(j < n){
            // 増えるのはstr[j]
            if(str[j] == 'M')  m++;
            else if(str[j] == 'C'){ c++; A[i] += m; }
            j++;
        }
    }

    // 全てのDについて加算
    for(int v : D) res += A[v];

    return res;
}



