    REP(i, n) if(str[i] == 'D') D.push_back(i);

    A.resize(n+1);

    int q; scanf("%d", &q);
    // クエリに答える
    while(q--){
        int query; scanf("%d", &query);
        printf("%d\n", solve(n, query));
    }

    return 0;
}

