int solve(string &S, int K) {
    int N = S.size();
    string T = S.substr(0, K);

    vector<int> accD(K + 1), accM(K + 1), accC(K + 1);
    for (int i = 0; i < K; i++) {
        accD[i + 1] = accD[i] + (T[i] == 'D');
        accM[i + 1] = accM[i] + (T[i] == 'M');
        accC[i + 1] = accC[i] + (T[i] == 'C');
    }

    ll dmc = 0, d = 0, m = 0, nd = 0;
    for (int i = 0; i < K; i++) {
        if (T[i] == 'M') {
            dmc += accD[i] * (accC[K] - accC[i + 1]);
            d += accD[i];
            m++;
        }
        if (T[i] == 'D') {
            nd++;
        }
    }

    for(int i = K; i < N; i++) {
        int out = i - K;
        int in = i;

        if (S[out] == 'D') {
            d -= m;
            nd--;
        } else if (S[out] == 'M') {
            m--;
        }
        if (S[in] == 'D') {
            nd++;
        } else if (S[in] == 'M') {
            m++;
            d += nd;
        } else if (S[in] == 'C') {
            dmc += d;
        }
    }

    return dmc;
}

