  cout << fixed << setprecision(12);

  Int n;
  cin>>n;
  string s;
  cin>>s;

  CumulativeSum <Int> M(n);
  CumulativeSum <Int> C(n);
  CumulativeSum <Int> MC(n);
  Int sum = 0;
  for(Int i=0;i<n;i++){
    if(s[i] == 'M') sum++, M.add(i, i+1, 1);
    if(s[i] == 'C') MC.add(i, i+1, sum), C.add(i, i+1, 1);
  }

  Int Q;
  cin>>Q;

  for(Int i=0;i<Q;i++){
    Int k;
    cin>>k;
    Int ans = 0;
    for(Int j=0;j<n;j++){
      if(s[j] != 'D') continue;
      Int a = MC.get(j, min(n, j+k));
      Int b = M.get(0, j) * C.get(j, min(n, j+k));
      ans += a - b;
    }
    cout<<ans<<endl;
  }

  return 0;
}

