ll solve(int k) {
    ll ans = 0;
    ll cnt_d = 0, cnt_m = 0, cnt_dm = 0;
    for (int i = 0; i < N; i++) {
        if (i - k >= 0) {
            if (S[i - k] == 'M') {
                cnt_m--;
            } else if (S[i - k] == 'D') {
                cnt_d--;
                cnt_dm -= cnt_m;
            }
        }
        if (S[i] == 'C') {
            ans += cnt_dm;
        } else if (S[i] == 'M') {
            cnt_m++;
            cnt_dm += cnt_d;
        } else if (S[i] == 'D') {
            cnt_d++;
        }
    }

    return ans;
}

