int Q;
ll k[100];
ll ans;
ll tmp;

ll srcha(ll s)
{
    ll a=s;
    for(ll j=s;j<S.length();j++)
    {
        if(S[j]=='M' && tmp!=0){tmp--;}
        else if(S[j]=='D'){break;}
        a++;
    }
    if(a==S.length())
        return -1;
    else
        return a;
}
ll srchc(ll s)
{
    ll c=s;
    for(ll j=s;j<S.length();j++)
    {
        if(S[j]=='C'){break;}
        else c++;
    }
    if(c==S.length())
        return -1;
    else
        return c;
}

void solve()
{
    REP(i,Q)
    {
        ll a, c;
        ll pa=0;
        bool flag=false;
        bool flag2=false;
        ans=0;
        tmp=0;
        while(true)
        {
            a=srcha(pa);
            c=srchc(a+1);
            if(a==-1 || c== -1){flag=true;break;}
            if(c-a>=k[i]) pa=a+1;
            else break;
        }
        while(!flag && c-a<k[i])
        {
            //cout << a << " " << c << endl;
            //ans+=tmp;
            while(c-a<k[i] && !flag2)
            {
                ll b=0;
                for(ll p=a+1;p<c;p++)
                {
                    if(S[p]=='M')b++;
                }
                ans+=b;
                //cout << ans << endl;
                if(srchc(c+1)!=-1)c=srchc(c+1);
                else {break;}
                //cout << a << " " << c << endl;
            }
            a=srcha(a+1);
            c=srchc(a+1);
            if(a >= c || a == -1)break;
        }
        cout << ans << endl;
    }
}

int main(){
