class imos1d{
  public:
  vector<ll>t, v;
  ll num;
  ll flg;
  imos1d(ll NUM = 0){
      flg = 0;
      num = NUM + 10;
      v = vector<ll>(num, 0);
      t = vector<ll>(num, 0);
  }
  void add(ll idx, ll x){
      flg = 0;
      t[idx] += x;
  }
  void make(){
      flg = 1;
      for(ll i = 1; i < num; i++)v[i] = v[i - 1] + t[i];
  }
  ll sum(ll l, ll r){
      if(!flg)make();
      return v[r] - v[l - 1];
  }
};

