template< typename T >
class CumulativeSum
{
public:
    CumulativeSum() {}
    CumulativeSum(int sz) : m_Data(sz, T(0)) {};
    CumulativeSum(int sz, int mod) : m_Data(sz, T(0)) {};

    // k に x を加える O(1)
    void Add(int k, T x) {
        assert(static_cast<int>(m_Data.size()) >= k);
        if(static_cast<int>(m_Data.size()) <= k) { m_Data.push_back(x); }
        else { m_Data[k] = (m_Data[k] + x); }
    }

    // 累積和の構築 O(m_Data.size())
    void Build() {
        for(int i = 1; i < static_cast<int>(m_Data.size()); i++) {
            m_Data[i] = (m_Data[i] + m_Data[i - 1]);
        }
    }

    // 区間 [0, k] の和を返す O(1)
    // 閉区間なので k が含まれることに注意
    T Query(int k) {
        if(k < 0) { return T(0); }
        return (m_Data[min(k, static_cast<int>(m_Data.size()) - 1)]);
    }

    // 区間 [l, h] の和を返す O(1)
    // 閉区間なので k が含まれることに注意
    T Query(int l, int h) {
        return (this->Query(h) - this->Query(l-1));
    }
private:
    vector< T > m_Data;
};

// 文字列 s の中から a -> b -> c の順番で現れるものの数を数える。
// また制限 k を与える。a ... b ... c となる文字列の長さを k 以内に抑える。
// (制限なしの場合は k = s.length() とする)
// あらかじめ a と b が s 中に含まれる数を累積和で求めておき、
// CumulativeSum::Build() 済みで渡すこと。
// 計算量 O(s.length())
ll GetCharPattern(string s, char a, char b, char c,
        ll k, CumulativeSum<ll>& cs_a, CumulativeSum<ll>& cs_b) {
    assert(s.length() >= 3 && k >= 3);
    ll ret = 0;
    ll l = 0, r = 1;
    ll prev_cnt = 0;
    if(s[l] == a && s[r] == b) { prev_cnt++; }
    // 最後が c であることに注目して、しゃくとり法で文字をカウント
    while(r < s.length() - 1) {
        // r の直後が c なら、 a ... b ... c の完成
        if(s[r + 1] == c) { ret += prev_cnt; }
        // r を右にずらす
        r++;
        if(s[r] == b) {
            // 新たな M が来たら、それより前の a の分だけ
            // a → M のパターンが増える
            prev_cnt += cs_a.Query(l, r-1);
        }
        // 範囲が k - 1 より大きいなら、 l も右にずらす
        if(r - l >= k - 1) {
            if(s[l] == a) {
                // a が削られるなら、それより後の b の分だけ
                // a → b のパターンが減る
                prev_cnt -= cs_b.Query(l+1, r);
            }
            l++;
        }
    }
    return ret;
}


