    i64 solve(int k)
    {
        int d=0;
        int m=0;
        i64 dm=0;
        i64 ans=0;
        for(int i=0; i<n; ++i)
        {
            d+=s[i]=='D';
            m+=s[i]=='M';
            if(s[i]=='M')
            {
                dm+=d;
            }
            if(i>=k)
            {
                if(s[i-k]=='D')
                {
                    dm-=m;
                    --d;
                }
                else if(s[i-k]=='M')
                {
                    --m;
                }
            }
            if(s[i]=='C')
            {
                ans+=dm;
            }
        }
        return ans;
    }
}; // struct solver


