                ret += (CMcount.at(j + A) - CMcount.at(j)) - Mcount.at(j) * (Ccount.at(j + A) - Ccount.at(j));
            }
            else if(S.at(j) == 'D') {
                ret += (CMcount.at(N) - CMcount.at(j)) - Mcount.at(j) * (Ccount.at(N) - Ccount.at(j));
            }
        }
