ll solve(long long N, string S, long long K){
	ll t = 0, m = 0, c = 0, res = 0;
	rep(i, N+K-1) {
		if (i-K >= 0) {
			if (S[i-K] == 'M') {
				m--;
				t -= c;
			}
			if (S[i-K] == 'C') {
				c--;
			}
		}
		if (i<N && S[i] == 'M') {
			m++;
		}
		if (i<N && S[i] == 'C') {
			c++;
			t += m;
		}
		if (i-K+1 >= 0) {
			if (S[i-K+1] == 'D') {
				res += t;
			}
		}
	}
	return res;
}

