vector<vector<int>> calcNext(const string &S) {
    int n = (int)S.size();
    vector<vector<int> > res(n+1, vector<int>(26, n));
    for (int i = n-1; i >= 0; --i) {
        for (int j = 0; j < 26; ++j) res[i][j] = res[i+1][j];
        res[i][S[i]-'A'] = i;
    }
    return res;
}

int main() {
    int n;
    cin >> n;
    string s;
    cin >> s;
    auto cn = calcNext(s);
    vector<ll> m1(n+1,0);
