        ll temp = 0;
        int pre = 0;
        //ll pc = 0;
        Rep(j,n){
            if(s[j]=='D'){
                if(pre>j){
                    temp-=(m1[j]-m1[pre-k[i]])*(c1[min(pre,n)]-c1[pre-k[i]]);
                }else{
