    const int d_size = d.size();
    const int c_size = c.size();

    vector<int> d_m, c_m;
    d_m = vector<int>(d_size);
    c_m = vector<int>(c_size);

    int before = 0;
    for (int i = 0; i < d_size; i++){
        int m_i = upper_bound(m.begin() + before, m.end(), d[i]) - m.begin();
        before = m_i;
        d_m[i] = m_i;
    }

    before = 0;
    for (int i = 0; i < c_size; i++){
        int m_i = lower_bound(m.begin() + before, m.end(), c[i]) - m.begin() - 1;
        before = m_i;
        c_m[i] = m_i;
    }

    for (int k_n : k){
        int cnt = 0;

        for (int d_i = 0; d_i < d_size; d_i++){
            for (int c_i = 0; c_i < c_size; c_i++){
