struct CumulativeSum{
    vector<int> data;
    CumulativeSum(int sz) : data(sz, 0) {};
    void add(int k, int x){
        data[k] += x;
    }
    void build(){
        for(int i = 1; i < data.size(); i++){
            data[i] += data[i - 1];
        }
    }
    //区間[0,k]の和
    int query(int k){
        if(k < 0) return 0;
        return (data[min(k, (int)data.size() - 1)]);
    }
    //区間[l.r)の和
    int query(int l, int r){
        return query(r - 1) - query(l - 1);
    }
};

signed main(){
    ios::sync_with_stdio(false);
    cin.tie(0);
    int n, q;
    string s;
    cin >> n >> s >> q;
    CumulativeSum cs1(n), cs2(n);
    rep(i, 0, n){
        if(s[i] == 'D') cs1.add(i, 1);
        if(s[i] == 'C') cs2.add(i, 1);
    }
    cs1.build(); cs2.build();
    rep(it, 0, q){
        int k, ans = 0;
        cin >> k;
        vector<int> a(n);
        rep(i, 0, n){
            a[i] += (i == 0 ? 0 : a[i - 1]);
            if(s[i] == 'D'){
                int tmp = cs2.query(i, min(i + k, n));
                a[i] += tmp;
            }else if(s[i] == 'M'){
                ans += a[i];
            }else if(s[i] == 'C'){
                int tmp = cs1.query(max(0LL, i - k + 1), i);
                a[i] -= tmp;
            }
        }
        cout << ans << endl;
    }
}

