int main() {
    int n, q;
    string s;
    cin >> n;
    scanf("%s", s);
    cin >> q;
    vector<int> di, ci;
    vector<int> dmcnt, cmcnt;
    int mc = 0;
    for (int i = 0; i < n; ++i) {
        if (s[i] == 'D') {
            di.push_back(i);
            dmcnt.push_back(mc);
        }
        if (s[i] == 'M') {
            ++mc;
        }
        if (s[i] == 'C') {
            ci.push_back(i);
            cmcnt.push_back(mc);
        }
    }
    for (int _ = 0; _ < q; ++_) {
        int k;
        cin >> k;
        int j = 0, pj = 0, c = 0;
        long long ans = 0, sum = 0;
        for (int i = 0; i < di.size(); ++i) {
            while (pj < ci.size() && ci[pj] < di[i]) {
                sum -= cmcnt[pj];
                ++pj;
                --c;
            }
            while (j < ci.size() && ci[j] - di[i] < k) {
                sum += cmcnt[j];
                ++j;
                ++c;
            }
            ans += max(0LL, sum - dmcnt[i] * (long long)c);
        }
        cout << ans << "\n";
    }
    return 0;
}

