string S;
ll N,Q;

ll solve(ll k){
    ll ret = 0;
    ll d = 0;
    ll m = 0;
    ll dm = 0;
    REP(i,k){
        if (S[i] == 'D') d++;
        if (S[i] == 'M') {
            m++;
            dm += d;
        }
        if (S[i] == 'C'){
            ret += dm;
        }
    }

    for (size_t i = k; i < N; i++) {
        char prev = S[i-k];
        char next = S[i];
        if (prev == 'D'){
            d--;
            dm -= m;
        }

        if (prev == 'M'){
            m--;
        }

        if (next == 'D') d++;
        if (next == 'M'){
            m++;
            dm += d;
        }
        if (next == 'C'){
            ret += dm;
        }
    }

    return ret;
}

int main() {
    cin >> N >> S >> Q;
    while(Q--){
        ll k; cin >> k;
        cout << solve(k) << "\n";
    }
}

