long long solve(int k){

  int tail = n;
  int cnum = 0;
  long long ans = 0;
  int mnum = 0;
  long long tmp = 0;
  for(int i = n-1;i >= 0;i--){
    switch(s[i]){
      case 'C':
        cnum++;
        break;
      case 'M':
        mnum++;
        tmp += cnum;
        break;
      case 'D':
        ans += tmp;
        break;
    }
    if(tail-i == k){
      tail--;
      switch(s[tail]){
        case 'C':
          tmp -= mnum;
          cnum--;
          break;
        case 'M':
          mnum--;
          break;
      }
    }
  }

  return ans;
}

