// segment tree, range add, sum
class SegmentTreeRAS
{
private:
	const int N;
	vector<int> data_overall, data_partial;

public:
	SegmentTreeRAS( const vector<int> &src ) : N( src.size() ), data_overall( N * 4, 0 ), data_partial( N * 4, 0 )
	{
		REP( i, 0, N )
		{
			add( i, i + 1, src[i] );
		}

		return;
	}

	void add( const int a, const int b, const int x )
	{
		return add( a, b, x, 0, 0, N );
	}

	LL sum( const int a, const int b )
	{
		return sum( a, b, 0, 0, N );
	}

private:
	void add( const int a, const int b, const int x, const int k, const int l, const int r )
	{
		if ( b <= l || r <= a )
		{
			return;
		}
		else if ( a <= l && r <= b )
		{
			data_overall[k] += x;
		}
		else
		{
			data_partial[k] += (LL)( min( r, b ) - max( l, a ) ) * x;
			add( a, b, x, chl( k ), l, mid( l, r ) );
			add( a, b, x, chr( k ), mid( l, r ), r );
		}
	}

	LL sum( const int a, const int b, const int k, const int l, const int r )
	{
		if ( b <= l || r <= a )
		{
			return 0;
		}
		else if ( a <= l && r <= b )
		{
			return data_partial[k] + (LL)( r - l ) * data_overall[k];
		}
		else
		{
			LL res = (LL)( min( r, b ) - max( l, a ) ) * data_overall[k];
			res += sum( a, b, chl( k ), l, mid( l, r ) );
			res += sum( a, b, chr( k ), mid( l, r ), r );
			return res;
		}
	}
};
// SegmentTreeRAS( VI src )
// add( [ a, b ), x )
// sum( [ a, b ) )

int main()
{
	cin.tie( 0 );
	ios::sync_with_stdio( false );
	cout << setprecision( 12 ) << fixed;

	IN( int, N );
	IN( string, S );

	VI psum_M( 1 );
	{
		VI a;
		transform( ALL( S ), BI( a ), bind( equal_to< char >(), _1, 'M' ) );
		partial_sum( ALL( a ), BI( psum_M ) );
	}
	const auto ms_in_range = [&]( const int l, const int r )
	{
		return psum_M[r] - psum_M[l];
	};

	IN( int, Q );
	REP( Q )
	{
		IN( int, K );

		deque< int > ids_of_c;
		int max_id_of_c = 0;

		SegmentTreeRAS num_of_m( VI( N + 1 ) );

		REP( i, K - 1 )
		{
			if ( S[i] == 'C' )
			{
				ids_of_c.PB( max_id_of_c++ );
				num_of_m.add( ids_of_c.back(), ids_of_c.back() + 1, ms_in_range( 0, i + 1 ) );
			}
		}

		LL res = 0;
		REP( i, N )
		{
			if ( i + K <= N && S[ i + K - 1 ] == 'C' )
			{
				ids_of_c.PB( max_id_of_c++ );
				num_of_m.add( ids_of_c.back(), ids_of_c.back() + 1, ms_in_range( i, i + K ) );
			}

			if ( ids_of_c.empty() )
			{
				continue;
			}

			switch ( S[i] )
			{
				case 'D':
				{
					res += num_of_m.sum( ids_of_c[0], ids_of_c.back() + 1 );
					break;
				}
				case 'M':
				{
					num_of_m.add( ids_of_c[0], ids_of_c.back() + 1, -1 );
					break;
				}
				case 'C':
				{
					ids_of_c.pop_front();
					break;
				}
			}
		}
		cout << res << '\n';
	}

	cout << flush;

	return 0;
}

