void findTriplets(vector<int>* pos, vector<int>& qs) {
  vector<ll> prefixSum (1, 0);
  vector<ll> dp (pos[2][pos[2].size()-1], -1);
  int idxB = 0;
  int lenB = pos[1].size();
  ll sum = 0;
  for(int i=0; i<pos[2].size(); i++) {
    while(pos[2][i] > pos[1][idxB] && idxB < lenB) {
      idxB++;
    }
    sum += idxB;
    prefixSum.push_back(sum);
  }
  for(auto q : qs) {
    ll ans = 0;
    for(auto k : pos[0]) {

      int low;
      if(dp[k] != -1) {
        low = dp[k];
      } else {
        low = dp[k] = lower_bound(pos[2].begin(), pos[2].end(), k) - pos[2].begin();
      }

      int high;
      if(k+q >= dp.size()) {
        high = pos[2].size();
      }
      else if(dp[k] != -1) {
        high = dp[k];
      } else {
        high = dp[k] = lower_bound(pos[2].begin(), pos[2].end(), k+q) - pos[2].begin();
      }

      int offset = lower_bound(pos[1].begin(), pos[1].end(), k) - pos[1].begin();
      ans += prefixSum[high] - prefixSum[low] - (offset * (high-low));
    }
    cout << ans << endl;
  }
  return;
}

