/*
右端を全探索です。
右端が 2 になるたびに、今見ている区間の 0 と 1 のペアの個数だけスコアに加算です。
左を pop では、0 を pop したら入っている 1 の数の分だけペアが減少します。
右に push では、1 を push したら入っている 0 の数の分だけペアが増加します。
*/

#include <bits/stdc++.h>
using namespace std;
typedef long long ll;
const int maxn = 2e6 + 5;
char s[maxn];
int sum[maxn];
int k[maxn];
vector<int> D;
vector<int> C;
int n;
ll slove(int k) {
    if (C.empty() || D.empty())
        return 0;
    ll ans=0;
    int j = 0;
    queue<int> q;
    int a, b;
    ll temp=0;
    for (int i = 0; i < D.size(); i++) {
        //将所有C的贡献调整
        if(i>0)
            temp-=(ll)q.size()*(sum[D[i]]-sum[D[i-1]]);
        //将跳过的C贡献调整
        if(!q.empty()) {
            int ft=q.front();
            while(ft<=D[i]) {
                temp+=sum[D[i]]-sum[D[i-1]];
                temp-=sum[ft]-sum[D[i-1]];
                q.pop();
                if(q.empty())
                    break;
                ft=q.front();
            }
        }
        //将无用的C排除
        while(j < C.size() &&C[j]<D[i]){
            j++;
        }
        //增加新的C
        while (j < C.size() && C[j] - D[i] < k) {
            q.push(C[j]);
            temp+=sum[C[j]]-sum[D[i]];
            j++;
        }
        ans+=temp;
    }
    return ans;
}
int main() {
