    for (int i = 1; i <= n; i++) {
        if (s[i] == 'D')
            D.push_back(i);
        if (s[i] == 'C')
            C.push_back(i);
        if (s[i] == 'M')
            sum[i] = sum[i - 1] + 1;
        else
            sum[i] = sum[i - 1];
    }
