          if(S[i-K] == 'M') M--;
        }
      }else if(S[i] == 'C'){
        dp[i+1][0] = dp[i][0];
        dp[i+1][1] = dp[i][1];
        dp[i+1][2] = dp[i][2] + dp[i][1];
        if(i - K >= 0){
          if(S[i-K] == 'D'){
            D--;
            dp[i+1][0]--;
            dp[i+1][1] -= M;
            dp[i+1][2] -= M;
          }
          if(S[i-K] == 'M') M--;
        }
      }else{
        dp[i+1][0] = dp[i][0];
        dp[i+1][1] = dp[i][1];
        dp[i+1][2] = dp[i][2];
        if(i - K >= 0){
          if(S[i-K] == 'D'){
            D--;
            dp[i+1][0]--;
            dp[i+1][1] -= M;
          }
          if(S[i-K] == 'M') M--;
        }
      }
    }
    ans[j] = dp[N][2];
  }
  rep(i,Q) cout << ans[i] << endl;
}

