// Binary Indexed Tree 0-indexed
struct BIT0 {
  ll n;
  vector<ll> bit;
  BIT0(ll n) : n(n), bit(n, 0) {}
  void add(ll a, ll w) {
    for (; a < n; a |= a + 1) {
      bit[a] += w;
    }
  }
  // v: 0-indexed, size = n
  void build(const vector<ll> &v) {
    n = v.size();
    bit = v;
    ll unit = 1;
    while (unit * 2 < n) {
      for (int i = unit * 2 - 1; i < n; i += unit * 2) {
        bit[i] += bit[i - unit];
      }
      unit <<= 1;
    }
  }
  ll sum(ll a) {
    ll ret = 0;
    for (; a >= 0; a = (a & (a + 1)) - 1) {
      ret += bit[a];
    }
    return ret;
  }
  // [a, b]
  ll sum(ll a, ll b) {
    return sum(b) - sum(a - 1);
  }
};


