ll count_range(const vector<ll>& cs, ll left, ll right){
    if(right == 0 || left >= right){ return 0; }
    ll ret = cs.at(min(right - 1, (ll)cs.size() - 1));
    if(left > 0){ ret -= cs.at(left - 1); }
    return ret;
}

int main(){
    ll n;
    cin >> n;
    string s;
    cin >> s;
