    cin >> q;

    // csc[i] = num of C in [0, i]
    // csm[i] = num of M in [0, i]
    vector<ll> csc(n, 0), csm(n, 0);
    REP(i, n){
        if(i > 0){
            csc.at(i) = csc.at(i - 1);
            csm.at(i) = csm.at(i - 1);
        }
        csc.at(i) += s.at(i) == 'C';
        csm.at(i) += s.at(i) == 'M';
    }

    // num of MC in [i, n)
    vector<ll> num_mc(n, 0);
    RREP(i, n){
        if(i + 1 < n){ num_mc.at(i) = num_mc.at(i + 1); }
        if(s.at(i) == 'M'){
            num_mc.at(i) += count_range(csc, i + 1, n);
        }
