                tmp -= num_mc.at(j + ki);
            }
            tmp -= count_range(csm, j + 1, j + ki) * count_range(csc, j + ki, n);
            assert(tmp >= 0);
            ans += tmp;
        }
        cout << ans << endl;
    }
    return 0;
}

