	for (int i = 0; i < N; i++) {
		if (S[i] == 'D') D.emplace_back(i);
		if (S[i] == 'M') M.emplace_back(i);
		if (S[i] == 'C') C_cnt[i] = 1;
	}

	for (int i = N - 1; i >= 0; i--) C_cnt[i] += C_cnt[i + 1];
