			}

			while (!M_q.empty() && D[i] > M_q.front().first) {
				MC -= MC_cnt[M_q.front().second];
				M_q.pop();
			}

			res += max(MC - (lint)M_q.size() * (lint)C_cnt[min(D[i] + k, N)], 0LL);

		}

		return res;

	};

