		if(s[i] == 'M')
			a[i] = 1;
	for(Int i=1; i<n; ++i)
		a[i] += a[i-1];

	vector<Int> di, ci;
	for(Int i=0; i<n; ++i){
		if(s[i] == 'D') di.push_back(i);
		if(s[i] == 'C') ci.push_back(i);
