ll solve(int k) {

    bit1<ll> bit;
    bit.init(n+10);
    ll res = 0;

    auto inc = [&](int i) {
	bit.upd(1,1);
	bit.upd(i+1,-1);
    };

    auto get = [&](int i) {
	return bit.qry(i);
    };


    deque<int> D;
    ll sum = 0;

    for (int i=1; i<=n; i++) {
	while (!D.empty() && i-D.front() >= k) {
	    sum -= get(D.front());
	    D.pop_front();
	}
	if (s[i]=='D') {
	    D.push_back(i);
	}
	if (s[i]=='M') {
	    inc(i);
	    sum += D.size();
	}
	if (s[i]=='C') {
	    res += sum;
	}
    }

    return res;
}

