#define N 1000003
#define Q 80

int n, q, ks[Q], m;
string s;

ll data0[N];
ll data1[N];

void _add(ll data[N], ll k, ll x) {
  while(k <= m) {
    data[k] += x;
    k += k & -k;
  }
}

void add(ll l, ll r, ll x) {
  _add(data0, l, -x*(l-1));
  _add(data0, r, x*(r-1));
  _add(data1, l, x);
  _add(data1, r, -x);
}

ll _get(ll data[N], ll k) {
  ll s = 0;
  while(k > 0) {
    s += data[k];
    k -= k & -k;
  }
  return s;
}

ll query(ll l, ll r) {
  return _get(data1, r-1) * (r-1) + _get(data0, r-1) - _get(data1, l-1) * (l-1) - _get(data0, l-1);
}

ll solve(int k) {
  rep(i, m+1) data0[i] = data1[i] = 0;
  queue<int> que;
  ll res = 0;
  int l = 1, r = 1;
  rep(i, n) {
    char c = s[i];
    while(!que.empty() && i-que.front() >= k) {
      que.pop();
      l += 1;
    }
    if(c == 'D') {
      r += 1;
      que.push(i);
    } else if(c == 'M') {
      add(l, r, 1);
    } else if(c == 'C') {
      res += query(l, r);
    }
  }
  return res;
}

