struct Queue {
    queue< ll > que;
    queue< int > pos;
    ll all = 0;
    int mx = 0;
    int sz = 0;
    ll sum = 0;
    int cur_pos = -1;

    Queue() = default;

    Queue(int _mx):
        all(0), mx(_mx), sz(0), sum(0), cur_pos(-1)
    { }

    void add() {
        pos.push(++cur_pos);
        que.push(-all);
        sum -= all;
        sz++;
        while(cur_pos - pos.front() + 1 > mx) {
            sum -= que.front();
            que.pop();
            pos.pop();
            sz--;
        }

        if(!sz) {
            sum = all = 0;
        }
    }

    void inc_pos() {
        cur_pos++;
        while(!pos.empty() && cur_pos - pos.front() + 1 > mx) {
            sum -= que.front();
            que.pop();
            pos.pop();
            sz--;
        }

        if(!sz) {
            sum = all = 0;
        }
    }

    void inc(ll val) {
        all += val;
    }

    ll get() const {
        return sum + all * sz;
    }

    void show() {
        for(int i = 0;i < sz;i++) {
            cout << pos.front() << " ";
            pos.push(pos.front());
