    fprintf(stderr, "k: %d\n", k);
    ll ans = 0;
    map<string, ll> counter;

    for (int i = 0; i < N; ++i) {
      char ch = S[i];

      switch(ch) {
        case 'D':
          counter["D"]++;
          break;
        case 'M':
          counter["M"]++;
          counter["DM"] += counter["D"];
          break;
        case 'C':
          ans += counter["DM"];
          break;
        default:
