      }

      if (i >= k - 1) {
        char c = S[i - k + 1];

        switch(c) {
          case 'D':
            counter["D"]--;
            counter["DM"] -= counter["M"];
            break;
          case 'M':
            counter["M"]--;
            break;
          default:
            // NOOP
            break;
        }
      }
    }

    cout << ans << endl;
