		scanf("%d", &k[i]);
	FT cnt(2*n+10), alpha(2*n+10);
	for (int i = 0; i < n; i++) {
		if (str[i] == 'C') {
			alpha.update(i, 1);
			cnt.update(i, numOfm);
		} else if (str[i] == 'M') {
			numOfm++;
		}
	}
