const int mod = 1000000007;
struct mint {
  ll x; // typedef long long ll;
  mint(ll x=0):x(x%mod){}
  mint& operator+=(const mint a) {
    if ((x += a.x) >= mod) x -= mod;
    return *this;
  }
  mint& operator-=(const mint a) {
    if ((x += mod-a.x) >= mod) x -= mod;
    return *this;
  }
  mint& operator*=(const mint a) {
    (x *= a.x) %= mod;
    return *this;
  }
  mint operator+(const mint a) const {
    mint res(*this);
    return res+=a;
  }
  mint operator-(const mint a) const {
    mint res(*this);
    return res-=a;
  }
  mint operator*(const mint a) const {
    mint res(*this);
    return res*=a;
  }
  mint pow(ll t) const {
    if (!t) return 1;
    mint a = pow(t>>1);
    a *= a;
    if (t&1) a *= *this;
    return a;
  }

  // for prime mod
  mint inv() const {
    return pow(mod-2);
  }
  mint& operator/=(const mint a) {
    return (*this) *= a.inv();
  }
  mint operator/(const mint a) const {
    mint res(*this);
    return res/=a;
  }
};

const int MOD = 1000000007;
const int inf=1e9+7;
const ll longinf=1LL<<60 ;

void addM(ll &a, ll b) {
    a += b;
    if (a >= MOD) a -= MOD;
}

void mulM(ll &a, ll b) {
    a = ((a%MOD)*(b%MOD))%MOD ;
}

ll powM(ll a,ll b) {
    ll ret = 1;
    ll tmp = a;
    while(b>0) {
        if((b&1)==1) ret = (ret * tmp) % MOD;
        tmp = (tmp * tmp) % MOD;
        b = b >> 1;
    }
    return ret;
}

// k個の範囲でのDMCの部分列をカウントする問題
// 必要な操作は以下の通り

// STEP1: i - k番目の要素を除外していく (i - k >= 0 のとき)
// (1) s[i] = D のとき → Dの個数を１減算した上で、Mの個数をDMの個数に減算
// (2) s[i] = M のとき → Mの個数を１減算する

// STEP2: i番目の要素をカウントしていく
// (1) s[i] = D のとき → Dの個数を１増加する
// (2) s[i] = M のとき → Mの個数を１増加した上で、Dの個数をDMの個数に加算
// (3) s[i] = C のとき → DMの個数をDMCの個数に加算

// kの範囲で〜という問題は、範囲をずらしていく(右端を加入させて、左端を除外する)によりO(N)で計算できることが多い
// 数え上げに必要な条件を順序立てて整理していけばよい。

int main(void) {
  cin.tie(0);
  ios::sync_with_stdio(false);  

  int N;
  cin >> N;

  char s[(int)(1e6)];
  scanf("%s", s);

  int Q;
  cin >> Q;
  while(Q--){
    int k;
    cin >> k;

    ll nd = 0, nm = 0, ndm = 0; 
    ll ndmc = 0;
    REP(i, N){
      if(i - k >= 0){
        if(s[i - k] == 'D'){
          nd--;
          ndm -= nm;
        } else if(s[i - k] == 'M'){
          nm--;
        }
      }

      if(s[i] == 'D'){
        nd++;
      } else if(s[i] == 'M'){
        nm++;
        ndm += nd;
      } else if(s[i] == 'C'){
        ndmc += ndm;
      }
    }
    cout << ndmc << endl;
  }

  return 0;
}

