					dm[i] = dm[i-1] - M[i-1] + M[i-k[x]+1];
				}else if(S[i] == 'M'){
					dm[i] = dm[i-1] + D[i-1] - D[i-k[x]+1];
				}else{
					dm[i] = dm[i-1];
				}
			}
			if(S[i] == 'C'){
				dmc[i] = dmc[i-1] + dm[i-1];
			}else{
				dmc[i] = dmc[i-1];
			}
		}
		cout << dmc[N-1] << endl;
	}
	return 0;
}

