ll f(string s) {
    int N = s.length();
    ll d = 0, dm = 0, dmc = 0;
    for (char c: s) {
        if (c == 'D') d++;
        if (c == 'M') dm += d;
        if (c == 'C') dmc += dm;
    }
    return dmc;
}

int main() {
	int N; cin >> N;
    string s; cin >> s;
    ll dmc = f(s);
    vector<int> m(N + 1);
    rep(i, N) m[i + 1] = m[i] + (s[i] == 'M');
    int Q; cin >> Q;
    while (Q--) {
        int k; cin >> k;
        k++;
        int d_num = 0;
        ll m_sum = 0;
        ll ans = 0;
        rep(r, N) {
            int l = r - k + 1;
            if (l >= 0 && s[l] == 'D') {
                d_num++;
                m_sum += m[r] - m[l + 1];
            }
            if (s[r] == 'M') m_sum += d_num;
            if (s[r] == 'C') ans += m_sum;
        }
        cout << dmc - ans << endl;
    }
}

