      rep(x, D){
        rep(y, D){
          int v = max(D + x - x0, D + y - y0) % D + (ceilf(sqrt(id[y * D + x])) - 1) * D;
          mx = max(mx, v);
        }
      }
      ans = min(ans, mx);
    }
  }
  cout << ans << endl;
  return 0;
}

