    ll work = 0;
    int l = 0, r = k - 1;
    for (int i = 0; i < k; i++)
    {
        if (s[i] == 'D')
        {
            numD++;
        }
        if (s[i] == 'M')
        {
            work += numD;
            numM++;
        }
        if (s[i] == 'C')
        {
            res += work;
            numC++;
        }
    }
    while (r < n - 1)
    {
        if (s[l] == 'D')
        {
            numD--;
            work -= numM;
        }
        if (s[l] == 'M')
        {
            numM--;
        }
        if (s[l] == 'C')
        {
            numC--;
        }
        l++;
        r++;
        if (s[r] == 'D')
        {
            numD++;
