        LL ans=0;
        LazySegmentTree a(vector<LL>(n+1,0));
        LazySegmentTree b(vector<LL>(n+1,0));
        LazySegmentTree c(vector<LL>(n+1,0));
        LazySegmentTree d(vector<LL>(n+1,0));
        queue<int> q;
        for (int j = 0; j < n; j++) {
            if(s[j]=='M') c.add(j,j+1,1);
            if(s[j]=='C') d.add(j,j+1,1);
        }
        for (int j = 0; j < s.size(); j++) {
            if(s[j]=='D'){
                a.add(j,j+1,1);
                q.push(j);
            }
            else if(s[j]=='M'){
                b.add(j,j+1,a.getsum(0,j));
            }
            else if(s[j]=='C'){
                ans+=b.getsum(0,j);
                while(!q.empty()){
