ll pref[3][MAX_N];

ll ask(int t, int l, int r)
{
    if (l >= n)
    {
        return 0;
    }
    l = max(l, 0);
    r = min(r, n - 1);
    if (l == 0)
    {
        return pref[t][r];
    }
    else
    {
        return pref[t][r] - pref[t][l - 1];
    }
}

ll query(ll k)
{
    ll res = 0;
    ll cnt = 0;
    ll curAns = 0;
    for (int i = 0; i < n; ++i)
    {
        int last = i - k;
        if (last >= 0)
        {
            if (s[last] == 'D')
            {
                curAns -= ask(1, last + 1, i - 1);
                cnt--;
            }
        }
        if (s[i] == 'D')
        {
            cnt++;
        }
        if (s[i] == 'M')
        {
            curAns += cnt;
        }
        if (s[i] == 'C')
        {
            res += curAns;
        }
    }
    return res;
}

