ll get(ll k) {
  ll s = 0;
  while(k > 0) {
    s += data[k];
    k -= k & -k;
  }
  return s;
}

ll solve(int k) {
  rep(i, m+1) data[i] = 0;
  queue<int> que;
  ll res = 0, cur = 0;
  int l = 1, r = 1;
  rep(i, n) {
