struct RSQRAQ {
  int n;
  vector<ll> dat, lazy;

  RSQRAQ(){}
  RSQRAQ(int n_) {
    n = 1; while(n < n_) n *= 2;
    dat.assign(n*2, 0);
    lazy.assign(n*2, 0);
  }

  void eval(int len, int k) {
    if(lazy[k] == 0) return;
    if(k*2+1 < n*2-1) {
      lazy[2*k+1] += lazy[k];
      lazy[2*k+2] += lazy[k];
    }
    dat[k] += lazy[k]*len;
    lazy[k] = 0;
  }

  // [a, b)
  ll update(int a, int b, ll x, int k, int l, int r) {
    eval(r-l, k);
    if(b <= l || r <= a) return dat[k];
    if(a <= l && r <= b) {
      lazy[k] += x;
      return dat[k] + lazy[k]*(r-l);
    }
    return dat[k] = update(a, b, x, 2*k+1, l, (l+r)/2) + update(a, b, x, 2*k+2, (l+r)/2, r);
  }
  ll update(int a, int b, ll x) { return update(a, b, x, 0, 0, n); }

  // [a, b)
  ll query(int a, int b, int k, int l, int r) {
    eval(r-l, k);
    if(b <= l || r <= a) return 0;
    if(a <= l && r <= b) return dat[k];
    ll vl = query(a, b, 2*k+1, l, (l+r)/2);
    ll vr = query(a, b, 2*k+2, (l+r)/2, r);
    return vl + vr;
  }
  ll query(int a, int b) { return query(a, b, 0, 0, n); }
};

class Solver {
  public:

    bool solve() {
        int N; cin >> N;
        string S; cin >> S;
        {
            string ss;
            ss.reserve(S.size());
            for(char c : S) if(c == 'D' or c == 'M' or c == 'C') ss.push_back(c);
            S = ss;
        }
        int Q; cin >> Q;
        vector<int> K(Q); cin >> K;
        vector<ll> ans(Q);

        vector<int> pos_m, pos_c;
        rep(i, S.size()) {
            if(S[i] == 'M') pos_m.push_back(i);
            if(S[i] == 'C') pos_c.push_back(i);
        }

        RSQRAQ seg(pos_c.size() + 1);

        for(int i : pos_m) {
            int j = upper_bound(all(pos_c), i) - begin(pos_c);
            if(j < pos_c.size() + 1)
                seg.update(j, pos_c.size() + 1, 1);
        }

        rep(i, S.size()) {
            if(S[i] == 'M') {
                int k = i + 1;
                while(k < S.size() and S[k] == 'M') k++;
                int j = upper_bound(all(pos_c), k - 1) - begin(pos_c);
                if(j < pos_c.size() + 1)
                    seg.update(j, pos_c.size() + 1, -1 * (k - i));
                i = k - 1;
            }
            if(S[i] == 'D') {
                int j = upper_bound(all(pos_c), i) - begin(pos_c);
                rep(l, Q) {
                    int k = upper_bound(all(pos_c), i + K[l] - 1) - begin(pos_c);
                    if(j < pos_c.size() + 1 and j < k) ans[l] += seg.query(j, k);
                }
            }
        }
        rep(i, Q) cout << ans[i] << endl;

        return 0;
    }
};

int main() {
    cin.tie(0);
    ios::sync_with_stdio(false);
    Solver s;
    s.solve();
    return 0;
}

