using namespace std;
string s;
int n;

struct N {
  int pos;
  int size;
};

bool operator<(const N &l, const N &r) { return l.pos < r.pos; }

long long solve(int k) {
  long long ans = 0;
  multiset<N> dq, mq;
  int esize = 0;
  long long msum = 0;
  for (int i = 0; i < n; i++) {
    if (dq.size() > 0) {
      if (dq.begin()->pos == i - k) {
        dq.erase(dq.begin());
        esize++;
      }
    }
    if (mq.size() > 0) {
      if (mq.begin()->pos == i - k) {
        msum -= mq.begin()->size;
        mq.erase(mq.begin());
      }
    }
    if (s[i] == 'D') {
      dq.insert(N{i, 0});
    } else if (s[i] == 'M') {
      mq.insert(N{i, esize + (int)dq.size()});
      msum += esize + (int)dq.size();
    } else if (s[i] == 'C') {
      ans += msum - esize * mq.size();
    }
  }
  return ans;
}

int main() {
  cin >> n;
  cin >> s;
  int q;
  cin >> q;
  for (int i = 0; i < q; i++) {
    int k;
    cin >> k;
    cout << solve(k) << endl;
  }
  return 0;
}

