void solve() {
	int N; cin >> N;
	string S; cin >> S;
	int Q; cin >> Q;
	vector<int> K(Q); for (auto &a : K) { cin >> a; --a; }
	vector<int> Mcnt(N), Ccnt(N), MCcnt(N);

	Mcnt[0] = (S[0] == 'M');
	Ccnt[0] = (S[0] == 'C');
	FOR(i, 1, N) {
		Mcnt[i] = Mcnt[i - 1];
		Ccnt[i] = Ccnt[i - 1];
		MCcnt[i] = MCcnt[i - 1];
		if (S[i] == 'M') {
			Mcnt[i] += 1;
		}
		if (S[i] == 'C') {
			Ccnt[i]++;
			MCcnt[i] += Mcnt[i];
		}
	}

	vector<int> ans;
	for (auto &k: K) {
		int res = 0;
		REP(i, N) {
			char c = S[i];
			if (c == 'D') {
				int right = min(i + k, N - 1);
				int mc_cnt = MCcnt[right] - MCcnt[i];
				int c_cnt = Ccnt[right] - Ccnt[i];
				int md_cnt = Mcnt[i];
				int cnt = mc_cnt - c_cnt * md_cnt;
				res += cnt;
			}
		}
		ans.push_back(res);
	}
	REP(i, ans.size()) {
		cout << ans[i] << endl;
	}
}

