int main() {

	cin.tie(nullptr);
	ios::sync_with_stdio(false);

	int N;
	cin >> N;

	string S;
	cin >> S;
	vector<int> D, M;
	vector<lint> C_cnt(N + 1); // indexがi以降のCの数
	for (int i = 0; i < N; i++) {
		if (S[i] == 'D') D.emplace_back(i);
		if (S[i] == 'M') M.emplace_back(i);
		if (S[i] == 'C') C_cnt[i] = 1;
	}

	for (int i = N - 1; i >= 0; i--) C_cnt[i] += C_cnt[i + 1];
	DMP(C_cnt);
	vector<int> MC_cnt(M.size()); // あるM以降のCの数
	for (int i = 0; i < M.size(); i++) MC_cnt[i] = C_cnt[M[i]];
	DMP(MC_cnt);

	DMP(D, M);

	auto query = [&](int k) {

		lint res = 0;
		queue<pair<int,int>> M_q;
		int M_i = 0;
		lint MC = 0;
		for (int i = 0; i < D.size(); i++) {

			while (M_i < M.size() && D[i] < M[M_i] && M[M_i] < D[i] + k - 1) {
				M_q.emplace(M[M_i], M_i);
				MC += MC_cnt[M_i];
				M_i++;
			}

			while (!M_q.empty() && D[i] > M_q.front().first) {
				MC -= MC_cnt[M_q.front().second];
				M_q.pop();
			}

			res += MC - (lint)M_q.size() * C_cnt[min(D[i] + k, N)];

		}

		return res;

	};

	int Q;
	cin >> Q;
	for (int i = 0; i < Q; i++) {
		int k;
		cin >> k;
		cout << query(k) << "\n";
	}

	return 0;
}

