	for (int i = 0; i < N; i++) {
		if ('D' == S[i]) {
			left = i;
			break;
		}
	}

	if (-1 == left) {
		printf("0\n");
		return;
	}

	lli sum = 0;
	for (right = left; right < min(N, left + k); right++) {
		if ('C' != S[right]) continue;
		sum += num[1][right + 1] - num[1][left + 1];
	}
	ret += sum;

	for (left = left + 1; left < N; left++, right = min(N, right + 1)) {
		if ('M' == S[left]) {
			sum -= num[2][right] - num[2][left + 1];
		}
		if ('C' == S[right]) {
			sum += num[1][right] - num[1][left + 1];
		}
		if ('D' == S[left]) {
			ret += sum;
		}
	}

	printf("%lld\n", ret);
}

