  while(idx_vec_d != vec_d.size()){
    //std::cout << "a" << vec_c[idx_vec_c] <<  " " << vec_d[idx_vec_d] << std::endl;

    if(vec_c[idx_vec_c] - vec_d[idx_vec_d] < ki && vec_c[idx_vec_c] - vec_d[idx_vec_d] > 0){
      std::vector<int>::iterator lower = std::lower_bound(vec_m.begin(), vec_m.end(), vec_d[idx_vec_d]);
      int temp = idx_vec_c;
      while(temp != vec_c.size() && vec_c[temp] - vec_d[idx_vec_d] < ki){
        std::vector<int>::iterator upper = std::upper_bound(vec_m.begin(), vec_m.end(), vec_c[temp]);
        //std::cout << "b" << vec_d[idx_vec_d] << " " << vec_c[idx_vec_c] << " " << upper - lower << std::endl;
        ret += (upper - lower);
        temp++;
      }
      //std::cout << idx_vec_d << " " << idx_vec_c << "hoge" << std::endl;
    }else if(vec_c[idx_vec_c] < vec_d[idx_vec_d]){
      idx_vec_c++;
      continue;
    }

    idx_vec_d++;
  }
  //std::cout << std::endl;

  return ret;
}

