long long solve(int K){
	long long m = 0, c = 0, mc = 0;
	long long ans = 0;
	for(int i = 1; i <= K - 1; ++i){
		if(isM[i]){
			m++;
		}
		if(isC[i]){
			mc += m;
			c++;
		}
	}
	for(int i = 0; i < N; ++i){
		if(isD[i]){
			ans += mc;
		}
		if(i + 1 < N && isM[i + 1]){
			mc -= c;
			m--;
		}
		if(i + 1 < N && isC[i + 1]){
			c--;
		}
		if(i + K < N && isM[i + K]){
			m++;
		}
		if(i + K < N && isC[i + K]){
			mc += m;
			c++;
		}
	}
	return ans;
}

