		for (int i = 0; i < D.size(); i++) {

			while (M_i < M.size() && D[i] < M[M_i] && M[M_i] < D[i] + k - 2) {
				M_q.emplace(M[M_i], M_i);
				MC += MC_cnt[M_i];
				M_i++;
			}

			while (!M_q.empty() && D[i] > M_q.front().first) {
				MC -= MC_cnt[M_q.front().second];
				M_q.pop();
			}

			res += MC - (lint)M_q.size() * C_cnt[min(D[i] + k - 1, N)];

		}

		return res;

	};

	int Q;
	cin >> Q;

	for (int i = 0; i < Q; i++) {
		int k;
		cin >> k;
		cout << query(k) << "\n";
	}

	return 0;
}

