	// sumcb[i] : cntcb[0] + ... + cntcb[i - 1]
	for(int i = 1; i <= n; i++){
		cntc[i] = cntc[i - 1];
		if(s[i - 1] == 'C'){
			cntcb[i] = cntb[i - 1];
			cntc[i]++;
		}
		sumcb[i] = sumcb[i - 1] + cntcb[i];
		// cout << i << " " << sumcb[i] << endl;
	}

	for(int i = 0; i < q; i++){
