		cc[i + 1] = cc[i];
	}

	sort(ALL(k));

	int ans = 0, cur = 0;

	REP(i, q) {
		cmc = 0;
		REP(j, n) {//D
			cmc += s[j] == 'M';
			if (s[j] == 'D') {
				ans += (mc[j + k[i].first] - mc[j + cur]) - cmc * (cc[j + k[i].first] - cc[j + cur]);
			}
		}

		out[k[i].second] = ans;
		cur = k[i].first;
	}

	REP(i, q) {
		printf("%d\n", out[i]);
	}

	return 0;
}

