int D[1000001];
int M[1000001];
int C[1000001];

PP init(int K) {
	LL sum = 0;
	LL dm = 0;
	REP(i, 0, K) {
		if (S[i] == 'M') {
			sum += LL(D[i] - D[0]) * (C[K] - C[i]);
			dm += D[i] - D[0];
		}
	}
	return PP(sum, dm);
}


LL sub(int K) {
	PP p = init(K);
	LL curr = p.first;
	LL dm = p.second;
	LL m = M[K] - M[0];
	LL sum = curr;
	REP(i, 0, N - K) {
		char front = S[i];
		char back = S[i + K];
		if (front == 'D') dm -= m;
		if (front == 'M') --m;
		if (back == 'M') {
			dm += D[i + K] - D[i + 1];
			++m;
		}
		if (back == 'C') {
			sum += dm;
		}
	}
	return sum;
}

