          tmp -= DM[i - k];
        }
        //cout << tmp << '\n';
        tmp -= (D[i] - ((i - k) >= 0 ? D[i - k] : 0)) * (M[i] - M[n]);
        answer += tmp;
      }
    }
    printf("%lld\n", answer);
  }
  return 0;
}

