template<typename T, typename F> vector<T> erase_if2(const vector<T> &v, F f) {
    vector<T> nv;
    rep(i, sz(v)) { if (!f(v[i])) { nv.push_back(v[i]); }}
    return nv;
}
template<typename T, typename F> vector<vector<T>> erase_if2(const vector<vector<T>> &v, F f) {
    vector<vector<T>> res;
    rep(i, sz(v)) { res[i] = erase_if2(v[i], f); }
    return res;
}

