void f(long long N, string S, long long Q, long long k) {
	long long res, a, d, m;
	res = a = d = m = 0;
	for(int i = 0; i < N; ++i) {
		if (i - k >= 0) {
			if (S[i - k] == 'D') {
				a -= m;
				--d;
			} else if (S[i - k] == 'M') {
				--m;
			}
		}
		if (S[i] == 'D') {
			++d;
		} else if(S[i] == 'M') {
			a += d;
			++m;
		} else if (S[i] == 'C'){
			res += a;
		}
	}
	cout << res << endl;
}

