class SlideMinDeque {
public:
    SlideMinDeque(int size) : _size(size) {
        deq.clear();
    }

    void add(int index) {
        deq.push_back(index);
    }

    bool get(int index) { //何かを排出した
      bool ret = false;
      while(deq.size()) {
          if(deq.front() <= index-_size) {
              deq.pop_front();
              ret = true;
          } else {
              return ret;
          }
      }
      return ret;
    }

private:
    int _size;
    deque<int> deq; 
};

