struct BIT {
	static constexpr ll MAX_N = 1e7;

	BIT(ll n_):n(n_)
	{
		for(auto& num:bit)num=0;
	}

	ll sum(int i) {
		i++;
		ll res = 0;
		while(i > 0){
			res += bit[i];
			i -= i & -i;
		}
		return res;
	}

	void add(ll i, ll x) {
		i++;
		while(i <= n) {
			bit[i] += x;
			i += i & -i;
		}
	}

	ll at(ll i) {
		return sum(i) - (i == 1 ? 0 : sum(i - 1));
	}

private:
	ll n;
	array<ll, MAX_N> bit;
};


vector<ll> reverse_number(vector<ll> v) {

	ll ans = 0;
	int n = v.size();
	BIT bit(n);
	vector<ll> imos(n, 0);

	REP(i, n) {
		if(v[i]!=0)	ans += i - bit.sum(v[i]);
		imos[i] = ans;
		//if(v[i]!=0)
		bit.add(v[i], 1);
	}
	return imos;
}

