vector<vector<ll>>  find_dmc_imos()
{
	vector<vector<ll>> dmc(3,vector<ll>(N));
	REP(i, N)dmc[0][i] = (S[i] == 'D' ? 1 : 0);
	REP(i, N)dmc[1][i] = (S[i] == 'M' ? 1 : 0);
	REP(i, N)dmc[2][i] = (S[i] == 'C' ? 1 : 0);
	return dmc;
}

vector<ll> bitBase(vector<vector<ll>> dmc)
{
	vector<int> cnt(3,1);
	int len=0;
	for(char c:S)if(c=='M')len++;

	vector<ll> base(N, 0);
	FOR(i, 1, 3)REP(j, N)if(dmc[i][j])
	{
		base[j] = (i - 1)*len + cnt[i];
		cnt[i]++;
	}

	return base;
}

//計算
void calc()
{
	// 0-1化
	auto dmc = find_dmc_imos();

	// 反転数列化
	auto bitbase = bitBase(dmc);

	vector<ll> rev = reverse_number(bitbase);

	// imos化
	REP(i, 3)REP(j, N - 1)dmc[i][j + 1] += dmc[i][j];

	for(auto k : ks)
	{
		ll res = 0;
		REP(l, N)if(S[l]=='D')
		{
			ll r = min(l + k, N) - 1;
			ll plus = (dmc[1][r] - dmc[1][l])*(dmc[2][r] - dmc[2][l]);//最大量
			ll minus = rev[r] - rev[l];//反転量
			cerr<<plus<<" "<<minus<<endl;
			res +=(plus-minus);
		}
		cout<<res<<endl;
		cerr<<endl<<endl;
	}
}


