			nd--;
			sum -= nm;
		} else if (drop == 'M') {
			nm--;
		}
		if (a[i] == 'D') {
			nd++;
		} else if (a[i] == 'M') {
			nm++;
			sum += nd;
		} else if (a[i] == 'C') {
			ret += sum;
		}
	}
	return ret;
}

