using namespace std;
char S[2020200];
int n,A[2020200],C[2020200],D[2020200];
void Work(){
	memset(C,0,sizeof(C));
	memset(D,0,sizeof(D));
	int k; scanf("%d",&k);
	int nC=0,nD=0;
	for (int i=n;i>=1;i--) if (A[i]==3)
		C[++nC]=i;
	LL Cur=0,ans=0;
	int ptc=nC+1,ptd=1;

	for (int i=1;i<=n;i++){
		if (!A[i]) continue;
		if (A[i]==1){
			D[++nD]=i; 
			while (ptc>1&&C[ptc-1]-i<k) ptc--;
			Cur+=(LL)(nC-ptc+1);
			continue;
		}
		if (A[i]==3){
			nC--;
			while (ptc>nC+1) ptc--;
			while (C[nC+1]-D[ptd]>=k&&ptd<=nD)
				ptd++; 
			Cur-=(LL)(nD-ptd+1);
			continue;
		} 
		ans+=(LL)Cur;
	}
	cout<<ans<<endl;
}
int main(){
	scanf("%d",&n);
	scanf("%s",S+1); getchar();
	for (int i=1;i<=n;i++){
		if (S[i]=='D') A[i]=1;
		if (S[i]=='M') A[i]=2;
		if (S[i]=='C') A[i]=3;
	}
	int T_num; cin>>T_num;
	while (T_num--) Work();
}

