int main() {
	ios::sync_with_stdio(false);
	cin.tie(0);

	cin >> N;
	string s;
	cin >> s;
	cin >> K;
	vector<long long int>d(N);
	vector<long long int>m(N);
	vector<long long int>c(N);
	for (int i = 0; i < N; i++) {
		m[i] = s[i] == 'M';
		d[i] = s[i] == 'D';
		c[i] = s[i] == 'C';
		if (i) {
			m[i] += m[i - 1];
			d[i] += d[i - 1];
			c[i] += c[i - 1];
		}
	}
	for (int i = 0; i < K; i++) {
		cin >> M;
		long long int ans = 0;
		queue<int>Q;
		queue<int>add;
		int bef = 0;
		long long int plus = 0;
		for (int j = 0; j < N; j++) {
			if (s[j] == 'D') {
				add.push(j);
			}
			if (s[j] == 'C') {
			//	cout << "j " << j << endl;
				while (!Q.empty()) {
					if (j - Q.front() >= M) {
						plus -= m[bef] - m[Q.front()];
						Q.pop();
					}
					else break;
				}
				plus += (m[j] - m[bef]) * Q.size();
				ans += plus;
				while (!add.empty()) {
					int cn = add.front();
					add.pop();
					if (j - cn >= M)continue;
					ans += m[j] - m[cn];
					plus += m[j] - m[cn];
					Q.push(cn);
				}
				bef = j;
				//cout << plus << endl;
				//cout << ans << endl;
			}
		}
		cout << ans << endl;
	}
}

