void solve() {
	int i,j,k,l,r,x,y; string s;

	cin>>N;
	cin>>S;
	FOR(i,N) {
		SM[i+1]=SM[i]+(S[i]=='M');
		BTC[i+1]=BTC[i];
		BTC2[i+1]=BTC2[i];
