void solve(long long N, std::string S, long long Q, std::vector<long long> k) {
  rep(q, Q) {
    ll kNum = k[q];
    ll dNum = 0;
    ll mNum = 0;
    ll cNum = 0;
    ll mcNum = 0;
    ll dmNum = 0;
    ll dmcNum = 0;

    rep(r, N) {
      ll l = r - kNum;
      if (l >= 0) {
        if (S[l] == 'D') {
          dNum--;
          dmNum -= mNum;
        } else if (S[l] == 'M') {
          mNum--;
          mcNum -= cNum;
        } else if (S[l] == 'C') {
          cNum--;
        }
      }

      if (S[r] == 'D') {
        dNum++;
      } else if (S[r] == 'M') {
        mNum++;
        dmNum += dNum;
      } else if (S[r] == 'C') {
        cNum++;
        mcNum += mNum;
        dmcNum += dmNum;
      }
    }
    print(dmcNum);
  }
}

