typedef unsigned long long		u64;

u64 Solve(const string & s, int n, int k)
{
	n = std::min((int)s.length(), n);

	map<int,int> que;
	const char* pS = &s[0];
	u64 ans = 0;

	for (int index = 0; index < n; ++index)
	{
		char ch = pS[index];

		while (que.size() > 0 && index - que.begin()->first >= k)
		{
			que.erase(que.begin());
		}

		if (ch == 'D')
		{
			que.insert(pair<int, int>(index, 0));
		}
		else if (ch == 'M')
		{
			for (auto & v : que)
			{
				++v.second;
			}
		}
		else if (ch == 'C')
		{
			for (auto v : que)
			{
				ans += v.second;
			}
		}
	}

	return ans;
}

