using i64 = int64_t;

int const N = 1e6 + 5;

i64 f[N], g[N];
int sum_C[N];
char s[N];
int n;

int main() {
	std::ios::sync_with_stdio(0);
	std::cin >> n;
	std::cin >> s + 1;
	for(int i = 1; i <= n; ++i)
		g[i] = g[i - 1] + (s[i] == 'M');
	for(int i = 1; i <= n; ++i)
		f[i] = f[i - 1] + (s[i] == 'C' ? g[i] : 0);
	for(int i = 1; i <= n; ++i)
		sum_C[i] = sum_C[i - 1] + (s[i] == 'C' ? 1 : 0);

	int Qcnt;
	std::cin >> Qcnt;
	while(Qcnt--) {
		int k;
		std::cin >> k;
		i64 ans = 0;
		for(int i = 1; i <= n; ++i)
			if(s[i] == 'D') {
				int mx = std::min(n, i + k - 1);
				int cnt_C = sum_C[mx] - sum_C[i - 1];
				ans += f[mx] - f[i] - cnt_C * g[i];
			}
		std::cout << ans << '\n';
	}
	return 0;
}

