const int INF = 1e9;
const int MOD = INF + 7;
const LL LLINF = 1e18;

int N;
string S;

LL calc(int K) {
    VL m_sum(N + 1);// Mの累積和
    VL c_sum(N + 1);//Cより前のMの数の累積和
    VL d_sum(N + 1);//Dより前のMの数の累積和
    VL c_cnt(N + 1);//Cの数の累積和
    {
        REP(i, N) {
            m_sum[i + 1] = m_sum[i] + (S[i] == 'M');
        }
        REP(i, N) {
            if (S[i] == 'C') {
                c_sum[i + 1] = m_sum[i + 1];
                c_cnt[i + 1] = 1;
            }
            c_sum[i + 1] += c_sum[i];
            c_cnt[i + 1] += c_cnt[i];
            if (S[i] == 'D') {
                d_sum[i + 1] = m_sum[i + 1];
            }
            d_sum[i + 1] += d_sum[i];
        }
    }
    // cerr << "d_sum: ";REP(i, N + 1) cerr << d_sum[i] << " ";cerr<<endl;
    // cerr << "m_sum: ";REP(i, N + 1) cerr << m_sum[i] << " ";cerr<<endl;
    // cerr << "c_sum: ";REP(i, N + 1) cerr << c_sum[i] << " ";cerr<<endl;
    // cerr << "c_cnt: ";REP(i, N + 1) cerr << c_cnt[i] << " ";cerr<<endl;
    LL ans = 0;
    REP(i, N) {
        if (S[i] == 'D') {
            LL add = c_sum[min(i + K, (int)c_sum.size() - 1)] - c_sum[i + 1] - m_sum[i + 1] * (c_cnt[min(i + K, (int)c_cnt.size() - 1)] - c_cnt[i + 1]);
            ans += add;
            //DEBUG(ans)
        }
    }
    return ans;
}

int main(void) {
    cin >> N;
    cin >> S;
    int Q;
    cin >> Q;
    REP(i, Q) {
        int K;
        cin >> K;
        cout << calc(K) << endl;
    }
}

