void solve(const string &s, ll n, ll k)
{
    ll ptr_d = 0;
    ll ptr_mc = -1;
    ll cnt_m = 0;
    ll cnt_c = 0;
    S ll anslist[1000006];
    memset(anslist, 0, sizeof(anslist));
    ll prev = 0;

    for ( ; ; ) {
        ll ans = prev;

        debug_printf("ptr_d = %lld\n", ptr_d);

        while (ptr_d < n) {
            if (s[ptr_d] == 'D') break;
            if (s[ptr_d] == 'M' && ptr_d <= ptr_mc) {
                ans -= cnt_c;
                cnt_m--;
            }
            if (s[ptr_d] == 'C' && ptr_d <= ptr_mc) {
                cnt_c--;
            }
            ptr_d++;
        }
        if (ptr_d == n) break;

        ptr_mc = max(ptr_mc, ptr_d);

        while (ptr_mc < min(n, ptr_d + k)) {
            if (s[ptr_mc] == 'M') {
                cnt_m++;
            }
            if (s[ptr_mc] == 'C') {
                ans += cnt_m;
                cnt_c++;
            }
            ptr_mc++;
        }

        anslist[ptr_d] = ans;
        prev = ans;
        ptr_d++;
    }

    debug_printf("---- anslist\n");
    debug_print(anslist, n);

    ll ans = 0;
    rep (i, 1000006) ans += anslist[i];

    debug_printf("---- ans\n");
    cout << ans << endl;
}

void _main()
{
    ll n; llin(n);
    string s; CIN(s);
    ll qcnt; llin(qcnt);
    V<ll> klist; llina(klist, qcnt);

    for (auto k : klist) solve(s, n, k);
}

