template<typename T>
class SparseTable {
public:
  vector<T> tbl[20];
  vector<T> tbr[20];
  int n;
  T (*op)(const T&, const T&);
  SparseTable(const vector<T> &v, T (*_op)(const T&, const T&)) : op(_op){
    // build table O(NlogN)
    n = v.size();
    tbl[0].resize(n+1);
    tbr[0].resize(n+1);
    rep(i,n) tbl[0][i] = tbr[0][i] = v[i];
    for(int k=1; (1<<k)<=n; k++){
      tbl[k].resize(n+1); tbr[k].resize(n+1);
      int mask = (1<<k)-1;
      rep(i,n){
        if((i&mask) == 0) tbr[k][i] = v[i];
        else tbr[k][i] = op(tbr[k][i-1], v[i]);
      }
      for(int i=n-1; i>=0; i--){
        if(((i+1)&mask) == 0) tbl[k][i] = v[i];
        else tbl[k][i] = op(tbl[k][i+1], v[i]);
      }
    }
  }
  T query(int l, int r) const { // [l,r)
    if(l==r) return 0;
    if(l+1 == r) return tbl[0][l];
    r--; // [l,r]
    int k = 31 - __builtin_clz(l^r); // 2^k <= l^r < 2^{k+1}
    return op(tbl[k][l], tbr[k][r]);
  }
};

int main(){
  int n,q;
  string s;
  cin>>n>>s>>q;

  vector<int> nm(n, n);
  for(int i=n-2; i>=0; i--){
    if(s[i+1] == 'M') nm[i] = i+1;
    else nm[i] = nm[i+1];
  }
  vector<int> cnt(n+1, 0);
  rep(i,n){
    if(s[i] == 'C') cnt[i+1] = cnt[i] + 1;
    else cnt[i+1] = cnt[i];
  }

  vector<long> sv(n, 0);
  {
    int cur = 0;
    rep(i,n){
      if(s[i]=='M') cur++;
      if(s[i]=='C') sv[i] = cur;
    }
  }
  SparseTable<long> st(sv, [](const long &l, const long &r){return l+r;});

  rep(i,1,n) if(sv[i]==0) sv[i] = sv[i-1];

  rep(_,q){
    int k;
    cin>>k;
    long ans = 0;
    rep(i,n){
      if(s[i] == 'D' && nm[i] < i+k-1){
        int lb = min(n,nm[i]+1), ub = min(n, i+k);
        long cs = cnt[ub] - cnt[lb];
        ans += st.query(lb, ub) - sv[i]*cs;
        dbg(i,cs,lb,ub,sv[i]*cs,st.query(lb, ub) - sv[i]*cs);
      }
    }
    cout << ans << endl;
  }

  return 0;
}

