			for(int i=s;(s-now<k)&&(i<it[2].size());i++){
				int l=-1,r=p,mid;
				while(r-l>1){
					mid=(l+r)/2;
					if(it[2][i]-it[0][mid]<k)r=mid;
					else l=mid;
				}
				if(r==it[0].size())continue;
				if(it[2][i]-it[0][r]>=k)continue;
