int N, Q;
string S;

ll solve(int k) {
    ll d = 0, c = 0, dc = 0;
    ll ans = 0;

    REP (i, N) {
        if (S[i] == 'D') {
            d++;
        } else if (S[i] == 'M') {
            c++;
            dc += d;
        } else if (S[i] == 'C') {
            ans += dc;
        }

        int j = i - k + 1;
        if (j < 0) continue;
        if (S[j] == 'D') {
            d--;
            dc -= c;
        } else if (S[j] == 'M') {
            c--;
        }
    }

    return ans;
}

int main() {
    cin >> N >> S >> Q;
    int k;
    REP (q, Q) {
        cin >> k;
        cout << solve(k) << "\n";
    }
}

