        int k;
        cin >> k;

        ll cntD = 0;
        ll cntM = 0;
        ll cntDM = 0;
        ll res = 0;
        deque<P> que;
        for(int j = 0; j < N; j++){
            //余分なものをpop
            while(true){
                if(que.size() == 0) break;
                else if(que.back().sc == 'D' && que.back().fs > j - k) break;
                else if(que.back().sc == 'M'){
                    //cout << "popM" << endl;
