                    que.pop_back();
                }
                else if(que.back().sc == 'D' && que.back().fs <= j - k){
                    //cout << "popD" << endl;
                    cntD--;
                    cntDM -= cntM;
                    que.pop_back();
                }
            }

            if(s[j] == 'D'){
                //cout << "pushD" << endl;
                que.push_front(P(j, 'D'));
                cntD++;
            }

            else if(s[j] == 'M'){
                //cout << "pushM" << endl;
                que.push_front(P(j, 'M'));
                cntM++;
                cntDM += cntD;
            }

            else if(s[j] == 'C'){
                //cout << "pushC" << endl;
                res += cntDM;
            }

            //printf("j = %2d  cntD = %2d  cntM = %2d  cntDM = %2d\n", j, cntD, cntM, cntDM);
        }

