const int N = 1000005;
ll dpD[N], dpM[N], dpC[N], dpDM[N];

inline ll calc(int i, int j) {
	ll ans = dpDM[j + 1] - dpDM[i];
	ans -= dpD[i] * (dpM[j + 1] - dpM[i]);
	return ans;
}

int main(int argc, char *argv[]) {
	ios_base::sync_with_stdio(false);

	int n, q;
	string s;

	cin >> n >> s >> q;

	dpD[0] = dpM[0] = dpC[0] = dpDM[0] = 1;
	REPU(i, 0, n) {
		dpD[i + 1] = dpD[i] + (s[i] == 'D' ? 1 : 0);
		dpM[i + 1] = dpM[i] + (s[i] == 'M' ? 1 : 0);
		dpC[i + 1] = dpC[i] + (s[i] == 'C' ? 1 : 0);
		dpDM[i + 1] = dpDM[i];

		if (s[i] == 'M') {
			dpDM[i + 1] += dpD[i];
		}
	}

	REPU(_, 0, q) {
		int k; cin >> k;
		ll ans = 0;
		REPU(i, 2, n) if (s[i] == 'C') {
			int from = max(0, i - k + 1);
			int to = i - 1;

			ans += calc(from, to);
		}
		printf("%lld\n", ans);
	}

	return 0;
}

