#define MAX_N (1000000)
#define MAX_Q (75)
#define SIZE_BUF (30)

using namespace std;

int main(int argc, char *argv[]) {
  // read inputs
  char S[MAX_N + 2], buf[SIZE_BUF];
  int N, Q;
  int ks[MAX_Q];
  scanf("%d", &N);
  fgets(buf, SIZE_BUF, stdin);
  fgets(S, MAX_N + 2, stdin);
  scanf("%d", &Q);
  for (int i = 0; i < Q; i++)
    scanf("%d", &ks[i]);

  // count number of ms up to each index
  int acc_num_ms[MAX_N + 1];
  acc_num_ms[0] = 0;
  for (int i = 1; i <= N; i++)
    acc_num_ms[i] = acc_num_ms[i - 1] + (S[i - 1] == 'M' ? 1 : 0);

  // solve for each k
  for (int q = 0; q < Q; q++) {
    const int k = ks[q];
    int num_ds = 0, num_dm_pairs = 0, ans = 0;
    // look through each character
    for (int i_S = 0; i_S < N; i_S++) {
      // check for out of range ds and remove if them
      // only one element becomes invalid at a time
      if (i_S >= k && S[i_S - k] == 'D') {
        const int rangel = i_S - k + 1, ranger = i_S - 1;
        // printf("i_S = %d, ds[%d] = %d exited (remaining = %d)\n",
        //        i_S, i_ds_b, ds[i_ds_b], ds.size() - i_ds_b - 1);
        // printf("num_dm_pairs = %d  -->  %d\n", num_dm_pairs,
        //        num_dm_pairs - (acc_num_ms[ranger] - acc_num_ms[rangel - 1]));
        num_dm_pairs -= acc_num_ms[ranger + 1] - acc_num_ms[rangel];
        num_ds--;
      }

      // check the current character and act accordingly
      if (S[i_S] == 'D') {
        // add to list of 'D's
        num_ds++;
      } else if (S[i_S] == 'M') {
        // update num_dm_pairs
        num_dm_pairs += num_ds;
      } else if (S[i_S] == 'C') {
        // increment number of triplets
        ans += num_dm_pairs;
      }
    }
    printf("%d\n", ans);
  }

  return 0;
}

