const int N = 1E6 + 100;
int n; char s[N];

LL solve(int K) {
    int l = 0, r = 1, mp = 0, cp = 0;
    LL pcount = 0, ans = 0;
    while (l < n) {
        while (r < n && r - l < K) {
            // add r
            if (s[r] == 'M')
                mp++;
            else if (s[r] == 'C') {
                cp++;
                pcount += 1 * mp;
            }
            r++;
        }

        if (s[l] == 'D') ans += pcount;

        l++;
        if (s[l] == 'M') { mp--; pcount -= 1 * cp; }
        else if (s[l] == 'C') cp--;
    }
    return ans;
}

