void solve(long long N, std::string S, long long Q, std::vector<long long> k) {
    auto solve = [&](long long K) {
        long long sum = 0;
        long long ans = 0;
        deque<pair<char, int>> Q;

        int dC = 0;
        int mC = 0;
        for (int i = 0; i < S.size(); i++) {
            while (Q.size() && i - K >= Q.front().second) {
                if (Q.front().first == 'D') {
                    sum -= mC;
                    dC--;
                } else {
                    mC--;
                }
                Q.pop_front();
            }
            if (S[i] == 'D') {
                Q.push_back({'D', i});
                dC++;
            } else if (S[i] == 'M') {
                Q.push_back({'M', i});
                mC++;
                sum += dC;
            } else if (S[i] == 'C') {
                ans += sum;
            }
        }
        return ans;
    };
    for (auto kv : k) {
        cout << solve(kv) << endl;
    }

}

