    } else if(S[i] == 'C') {
      dp[i + 1] = sum;
    }
  }
  for(int i = 1; i <= N; i++) {
    dp[i] += dp[i - 1];
  }
  int64 sums[3][1000001] = {{}};
  string v = "DMC";
  for(int i = 1; i <= N; i++) {
    auto pos = v.find(S[i - 1]);
