      if (0 < l && s.at(l - 1) == 'D')
        { d--; pairs -= m; }
      if (0 < l && s.at(l - 1) == 'M')
        { m--; }
      if (s.at(r - 1) == 'C')
        { ret += pairs; }
      // debug(d, m, pairs);
