    {
        prefC[i]= 0;
        if (s[i] == 'C')
            ++prefC[i];
        if (i - 1 >= 0)
            prefC[i] += prefC[i - 1];
    }
    for (int i = 0; i < q; ++i)
    {
        int k;
        cin >> k;
        --k;
        ll odp = 0;
        vector<ll> ilMC(n);
        ilMC[0] = 0;
        for (int j = 0; j < k - 1; ++j)
            if (s[j] == 'M')
                ilMC[0] += prefC[k - 1] - prefC[j];
        for (int j = 1; j + k - 1 < n; ++j)
        {
            if (s[j] == '*')
                break;
            ilMC[j] = ilMC[j - 1];
            if (s[j - 1] == 'M')
                ilMC[j] -= prefC[j + k - 2] - prefC[j - 1];
            if (s[j + k - 1] == 'C')
                ilMC[j] += prefM[j + k - 2] - prefM[j - 1];
        }
        ++k;
        for (int j = 0; j + k - 1 < n; ++j)
        {
            if (s[j] =='*')
                break;
            if (s[j] == 'D')
                odp += ilMC[j + 1];
        }
        cout << odp << endl;
    }
    return 0;
}

