        // Do nothing
      }
    }

    // Next, add contribution from i
    if (s[i] == 'D') {
      ++d_cnt;
    } else if (s[i] == 'M') {
      ++m_cnt;
      now += d_cnt; // increase contribution by this M
      // cout << "d_cnt:" << d_cnt << endl;
    } else if (s[i] == 'C') {
      // cout << "now:" << now << endl;
      ans += now;
    }
  }
  return ans;
}

