      dp[i+1][1] += dp[i][1] + dp[i][0];
      dp[i+1][2] += dp[i][2];
    }else if(S[i]=='C'){
      dp[i+1][0] += dp[i][0];
      dp[i+1][1] += dp[i][1];
      dp[i+1][2] += dp[i][2] + dp[i][1];
    }else{
      dp[i+1][0] += dp[i][0];
      dp[i+1][1] += dp[i][1];
      dp[i+1][2] += dp[i][2];
    }
  }

  //mat_print(dp);

  return dp[N][2];
}

