using namespace std;

int cumM[2000000];
int cumC[2000000];
int N, Q;
string S;

int solve(int k) {
    int ans = 0;
    int left = -1, right = -1;
    REPS(i, N) {
        if (S[i] == 'D') {
            left = i;
            break;
        }
    }
    //Dがない
    if (left == -1) {
        return 0;
    }
    //しゃくとり
    int calcSum = 0;
    right = left + 1;
    while (left <= N) {
        while (right <= N && right - left < k) {
            //Cが見つかったらleft のD, right のCでつくれるDMCを加算
            if (S[right] == 'C') {
                calcSum += cumM[right] - cumM[left - 1];
            }
            right++;
        }

        ans += calcSum;

        //left を動かす
        int oldLeft = left;
        left++;
        while (left <= N && S[left] != 'D') {
            //Mが見つかったらoldLeftのD、rightまでにあるC でつくれるDMCを減算(rightは条件を満たすright + 1になっていることに注意)
            if (S[left] == 'M') {
                calcSum -= cumC[right-1] - cumC[left - 1];
            }
            left++;
        }
    }
    return ans;

}

