	cin.tie(nullptr);
	ios::sync_with_stdio(false);

	int N;
	cin >> N;

	string S;
	cin >> S;
	vector<int> D, M, C;
	vector<int> C_cnt(N);
	for (int i = 0; i < N; i++) {
		if (S[i] == 'D') D.emplace_back(i);
		if (S[i] == 'M') M.emplace_back(i);
		if (S[i] == 'C') {
			C.emplace_back(i);
			C_cnt[i] = 1;
		}
	}
	for (int i = 0; i < N - 1; i++) C_cnt[i + 1] += C_cnt[i];
