	for (int i = 0; i < M.size(); i++) MC_cnt[i] = C_cnt[M[i]];

	DMP(D, M, C);

	auto query = [&](int k) {

		lint res = 0;
		queue<pair<int,int>> M_q;
		int M_i = 0;
		lint MC = 0;
		for (int i = 0; i < D.size(); i++) {

			while (M_i < M.size() && D[i] < M[M_i] && D[i] + k > M[M_i]) {
				M_q.emplace(M[M_i], M_i);
				MC += MC_cnt[M_i];
				M_i++;
			}

			while (!M_q.empty() && D[i] > M_q.front().first) {
				MC -= MC_cnt[M_q.front().second];
				M_q.pop();
			}

			res += max((lint)M_q.size() * C_cnt[min(D[i] + k - 1, N - 1)] - MC, 0LL);

		}

		return res;

	};

