int N, Q;
string S;

vi acc_m;

void prepare() {
    acc_m.assign(N+1, 0);

    rep(i,N) {
        acc_m[i+1] = acc_m[i] + (S[i] == 'M' ? 1 : 0);
    }
}

ll query(int k){
    ll ans = 0;

    deque<int> resv;
    ll dp[2][2];
    dp[0][0] = dp[0][1] = 0;

    rep(i,N) {
        int i0 = i%2, i1 = 1-i0;
        while (!resv.empty() && resv.front() <= i-(k-0)) {
            int expired_d = resv.front();
            dp[i0][0]--;
            int cnt_m = acc_m[i] - acc_m[expired_d];
            dp[i0][1] -= cnt_m;
            resv.pop_front();
        }

        dp[i1][0] = dp[i0][0];
        dp[i1][1] = dp[i0][1];

        switch (S[i]) {
            case 'D':
                dp[i1][0]++;
                resv.push_back(i);
                break;
            case 'M':
                dp[i1][1] += dp[i0][0];
                break;
            case 'C':
                ans += dp[i0][1];
                break;
            default:
                break;
        }
    }

    return ans;
}


