  for(int i = 0; i < n; i++){
    if(s[i] == 'D'){
      D[i] = 1;
    }
    if(s[i] == 'M'){
      M[i] = 1;
      DM[0]++;
      DM[i]--;
    }
  }
  for(int i = 1; i < n; i++){
    D[i] += D[i - 1];
  }
  for(int i = n; i >= 0; i--){
    M[i] += M[i + 1];
  }
  for(int i = 1; i < n; i++){
    DM[i] += DM[i - 1];
  }
  for(int i = 0; i < n; i++){
    if(s[i] != 'D'){
      DM[i] = 0;
    }
  }
  for(int i = 1; i < n; i++){
    DM[i] += DM[i - 1];
  }
  int q;
  fastScan(q);
  while(q--){
    int k;
    fastScan(k);
    ll answer = 0;
    for(int i = 2; i < n; i++){
      if(s[i] == 'C'){
        ll tmp = DM[i];
        if(i - k >= 0){
          tmp -= DM[i - k];
        }
        //cout << tmp << '\n';
        tmp -= (D[i] - ((i - k) >= 0 ? D[i - k] : 0)) * (M[n - 1] - M[i]);
        answer += tmp;
      }
    }
    printf("%lld\n", answer);
  }
  return 0;
}

