using ll = long long;

int N;
char S[1000010];

ll solve(int K) {
    ll ans = 0;
    ll d = 0, m = 0, dm = 0;
    for (int i = 1; i <= N; ++i) {
        if (S[i] == 'D') {
            ++d;
        } else if (S[i] == 'M') {
            ++m;
            dm += d;
        } else if (S[i] == 'C') {
            ans += dm;
        }

        if (i-K+1 >= 1) {
            if (S[i-K+1] == 'D') {
                --d;
                dm -= m;
            } else if (S[i-K+1] == 'M') {
                --m;
            }
        }
    }
    return ans;
}

int main() {
    cin.tie(0); ios::sync_with_stdio(false);
    int Q;
    scanf("%d %s %d", &N, S+1, &Q);
    for (int i = 0; i < Q; ++i) {
        int K; scanf("%d", &K);
        printf("%lld\n", solve(K));
    }
    return 0;
}

