            auto ma = lower_bound(c.begin(), c.end(), pos + k);
            ma--;
            int miidx = *mi, maidx = *ma;
            res -= msum[pos] * (cnum[maidx] - cnum[pos]);
            if (mi == c.begin())
            {
                res += csum[maidx];
            }
            else
            {
                res += csum[maidx];
                res -= csum[miidx-1];
            }
        }
        cout << res << endl;
    }
}

