using namespace std;

int64_t solve(string s, int k) {
    int n = s.size();
    int64_t ans = 0;
    int64_t M_sum = 0, M_count = 0, D_count = 0, D_missing = 0;

    int it = 0;

    for(int i = 0; i < n; i += 1) {
        if(s[i] == 'C') {
            while(i - it >= k) {
                if(s[it] == 'D') {
                    D_missing += 1;
                } else if(s[it] == 'M') {
                    M_sum -= D_missing;
                    M_count -= 1;
                }
                it += 1;
            }
            ans += M_sum - M_count * (D_missing);
        } else if(s[i] == 'D') {
            D_count += 1;
        } else if(s[i] == 'M') {
            M_sum += D_count;
            M_count += 1;
        }
    }

    return ans; 
}

