	int i,j,k;
	scanf("%d",&n);
	for(i=0;i<n;++i){
		a[i]=readch();
	}
	init(1);
	scanf("%d",&q);
	while(q--){
		scanf("%d",&k);
		printf("%lld\n",solve(k));
	}
	return 0;
}

