struct BIT{
	int size=1;
	vector<int> node;
	BIT(int n){
		while(size<n){
			size<<=1;
		}
		node.resize(size+1,0);
	}
	//k番目の値にa加算
	void add(int k,int a){
		k++;
		while(k<=size){
			node[k]+=a;
			k+=k&-k;
		}
	}
	//[0,k]の範囲内の区間和を求める
	int query(int k){
		k++;
		int res=0;
		while(k){
			res+=node[k];
			k-=k&-k;
		}
		return res;
	}
};
int main(){
