  for(int i=0; i<pos[2].size(); i++) {
    while(pos[2][i] > pos[1][idxB] && idxB < lenB) {
      idxB++;
    }
    sum += idxB;
    prefixSum.push_back(sum);
  }

  vector<int> low;
  int idxC = 0;
  int lenC = pos[2].size();
  for(auto k : pos[0]) {
    while(k > pos[2][idxC] && idxC < lenC) {
      idxC ++;
    }
    low.push_back(idxC);
  }

  vector<int> high[maxQ];
  for(int q=0; q<qs.size(); q++) {
    idxC = 0;
    for(auto k : pos[0]) {
      while(k+qs[q] > pos[2][idxC] && idxC < lenC) {
        idxC ++;
      }
      high[q].push_back(idxC);
    }
  }

  vector<int> offset;
  idxB = 0;
  for(auto k : pos[0]) {
    while(k > pos[1][idxB] && idxB < lenB) {
      idxB ++;
    }
    offset.push_back(idxB);
  }


  for(int q=0; q<qs.size(); q++) {
    ll ans = 0;
    for(int i=0; i<pos[0].size(); i++) {
      ans += prefixSum[high[q][i]] - prefixSum[low[i]] - (offset[i] * (high[q][i]-low[i]));
    }
    cout << ans << endl;
  }
  return;
}

