    if(i >= x && s[i - x] == 'D') {
      now -= cnt[i - 1][1];
      now += cnt[i - x][1];
    }
    if(s[i] == 'M') {
      now += cnt[i - 1][0];
      if(i >= x) now -= cnt[i - x][0];
    }
    else if(s[i] == 'C') {
      ans += now;
    }
  }

  return ans;
}

