template< typename T >
class CumulativeSum
{
public:
    CumulativeSum() {}
    CumulativeSum(int sz) : m_Data(sz, T(0)) {};
    CumulativeSum(int sz, int mod) : m_Data(sz, T(0)) {};

    // k に x を加える O(1)
    void Add(int k, T x) {
        assert(static_cast<int>(m_Data.size()) >= k);
        if(static_cast<int>(m_Data.size()) <= k) { m_Data.push_back(x); }
        else { m_Data[k] = (m_Data[k] + x); }
    }

    // 累積和の構築 O(m_Data.size())
    void Build() {
        for(int i = 1; i < static_cast<int>(m_Data.size()); i++) {
            m_Data[i] = (m_Data[i] + m_Data[i - 1]);
        }
    }

    // 区間 [0, k] の和を返す O(1)
    // 閉区間なので k が含まれることに注意
    T Query(int k) {
        if(k < 0) { return T(0); }
        return (m_Data[min(k, static_cast<int>(m_Data.size()) - 1)]);
    }

    // 区間 [l, h] の和を返す O(1)
    // 閉区間なので k が含まれることに注意
    T Query(int l, int h) {
        return (this->Query(h) - this->Query(l-1));
    }
private:
    vector< T > m_Data;
};

ll N, Q;
string S;

void solve(ll K, CumulativeSum<ll>& cs_d, CumulativeSum<ll>& cs_m) {
    // 最後が C であることに注目する
    ll ans = 0;
    ll l = 0, r = 1;
    ll prev_cnt = 0;
    if(S[l] == 'D' && S[r] == 'M') {
        prev_cnt++;
    }
    while(r < N - 1) {
        // r の直後が C なら、 DMC 完成
        if(S[r + 1] == 'C') { ans += prev_cnt; }
        // r を右にずらす
        r++;
        if(S[r] == 'M') {
            // 新たな M が来たら、それより前の D の分だけ
            // D → M のパターンが増える
            prev_cnt += cs_d.Query(l, r-1);
        }
        // 範囲が k - 1 より大きいなら、 l も右にずらす
        if(r - l >= K - 1) {
            if(S[l] == 'D') {
                // D が削られるなら、それより後の M の分だけ
                // D → M のパターンが減る
                prev_cnt -= cs_m.Query(l+1, r);
            }
            l++;
        }
    }
    printf("%lld\n", ans);
}

signed main()
{
    cin >> N >> S >> Q;

    // 累積和の作成
    CumulativeSum<ll> cs_d(N);
    CumulativeSum<ll> cs_m(N);

    REP(i, N) {
        if(S[i] == 'D') { cs_d.Add(i, 1); }
        if(S[i] == 'M') { cs_m.Add(i, 1); }
    }
    cs_d.Build();
    cs_m.Build();

    REP(i, Q) {
        ll k;
        cin >> k;
        solve(k, cs_d, cs_m);
    }
    return 0;
}

