long long solve(const string &s, int k) {
  int n = s.size();
  long long res = 0;
  long long sum = 0;
  int d_count = 0;
  int m_count = 0;
  for (int i = 0; i < n; ++i) {
    if (i >= k) {
      switch (s[i - k]) {
        case 'D':
          sum -= m_count;
          --d_count;
          break;
        case 'M':
          --m_count;
          break;
      }
    }

    switch (s[i]) {
      case 'D':
        ++d_count;
        break;
      case 'M':
        ++m_count;
        sum += d_count;
        break;
      case 'C':
        res += sum;
        break;
    }
  }

  return res;
}

