ll modcomb(ll n, ll k){ll b=1;k=min(n-k,k);DOWN(i,n,n-k+1)b=b*i%MOD;return b*modpow(modfact(k),MOD-2)%MOD;}

int N, Q, k;
char S[100000];
vector<int> A, B, C;
vector<int> D, E;

void init(void) {
    D.resize(B.size());    
    E.resize(B.size() + 1);
    int s = 0;
    REP(i, B.size()) {
        D[i] = C.end() - upper_bound(ALL(C), B[i]);
        s += D[i];
    }
    REP(i, B.size()) {
        E[i] = s;
        s -= D[i];
    }
}

int solve(void) {
    int res = 0;
    size_t bl, br, cr;
    REP(i, A.size()) {
        bl = upper_bound(ALL(B), A[i]) - B.begin();
        br = lower_bound(ALL(B), A[i] + k) - B.begin();
        cr = C.end() - lower_bound(ALL(C), A[i] + k);
        res += (E[bl] - E[br]) - (br - bl) * cr;
    }
    return res;
}

int main() {
    scanf("%d\n", &N);
    scanf("%s\n", S);
    scanf("%d\n", &Q);
    REP(i, N) {
        if(S[i] == 'D') A.push_back(i);
        if(S[i] == 'M') B.push_back(i);
        if(S[i] == 'C') C.push_back(i);
    }
    init();
    REP(i, Q) {
        scanf("%d", &k);
        printf("%d\n", solve());
    }
	return 0;
}

