void solve(int idx) {
  ll ans = 0;
  int l = 0, r = 0;
  int sm = 0, sc = 0;
  ll cost = 0;
  while (l < N) {
    // cout << "Phase0 : " << l << " " << r << " " << cost << endl;
    while (l < N && S[l] != 'D') r = max(r, ++l);
    // cout << "Phase1 : " << l << " " << r << endl;
    while (r < N && r - l < K[idx]) {
      if (S[r] == 'M') sm++;
      if (S[r] == 'C') {
        cost += sm;
        sc++;
      }
      r++;
    }
    ans += cost;
    // ans += (ll)sm*sc;
    // cout << "Phase2 : " << l << " " << r << " " << cost << endl;
    l++;
    while (l < r) {
      if (S[l] == 'D') break;
      if (S[l] == 'M') {
        cost -= sc;
        sm--;
      }
      if (S[l] == 'C') sc--;
      l++;
    }
    // cout << "Phase3 : " << l << " " << r << endl << endl;
  }
  cout << ans << endl;
}

