void run (void) {
  i32 n;
  scanf ("%" SCNi32, &n);
  char *s = (char *) calloc (n + 1, sizeof (char));
  scanf ("%s", s);
  i32 q;
  scanf ("%" SCNi32, &q);
  while (q--) {
    i32 k;
    scanf ("%" SCNi32, &k);
    i64 ans = 0;
    i32 cntD = 0;
    i32 cntM = 0;
    i64 cntDM = 0;
    for (i32 i = 0; i < k; ++i) {
      if (s[i] == 'D') {
	cntD++;
      } else if (s[i] == 'M') {
	cntM++;
	cntDM += cntD;
      } else if (s[i] == 'C') {
	ans += cntDM;
      }
    }
    for (i32 i = k; i < n; ++i) {
      if (s[i - k] == 'D') {
	cntDM -= cntM;
	cntD--;
      } else if (s[i - k] == 'M') {
	cntM--;
      }
      if (s[i] == 'D') {
	cntD++;
      } else if (s[i] == 'M') {
	cntM++;
	cntDM += cntD;
      } else if (s[i] == 'C') {
	ans += cntDM;
      }
    }
    printf("%" PRIi64 "\n", ans);
  }
}

