{
    ll d = 0, m = 0, c = 0;
    for(ll i = 0; i < k; i++)
    {
        if(s[i] == 'D')
            d++;
        else if(s[i] == 'M')
            m += d;
        else if(s[i] == 'C')
            c += m;
