void inc(int &d, int &m, int &dm, int &dmc, char c){
    switch(c){
        case 'D':
            d++;
            break;
        case 'M':
            m++;
            dm += d;
            break;
        case 'C':
            dmc += dm;
            break;
    }
}
void dec(int &d, int &m, int &dm, int &dmc, char c){
    switch(c){
        case 'D':
            d--;
            dm -= m;
            break;
        case 'M':
            m--;
            break;
    }
}

