struct C_DMC{
  long D,M,C,DM,MC,DMC;
  C_DMC():D(0),M(0),C(0),DM(0),MC(0),DMC(0){}
  C_DMC(char c):D(c=='D'),M(c=='M'),C(c=='C'),DM(0),MC(0),DMC(0){}
};
C_DMC add(C_DMC x,C_DMC y){
  C_DMC c;
  c.D=x.D+y.D;c.M=x.M+y.M;c.C=x.C+y.C;
  c.DM=x.DM+y.DM+x.D*y.M;c.MC=x.MC+y.MC+x.M*y.C;
  c.DMC=x.DMC+y.DMC+x.DM*y.C+x.D*y.MC;
  return c;
}
template <typename T>
class SegTree{ 
  vector<T> dat;
  long n;

  public:
  SegTree(vector<T> d){
    long n_=d.size();
    n=1;while(n<n_)n*=2; //nを2の冪乗に拡張する
    dat=vector<T>(2*n-1,T());
    for(long i=0;i<n_;i++)update(i,d[i]);
  }

  void update(long k,T a){ //k番目をaに変更
    k+=n-1; //(k=2*n-1)-n+kの意味
    dat[k]=a;
    while(k>0){ 
      k=(k-1)/2;
      dat[k]=add(dat[2*k+1],dat[2*k+2]);
    }
  }
  //区間[a,b)での最小値を返す. 外から呼ぶときはquery(a,b,0,0,n)みたいになる
  //注意 外から呼ぶにしてもNは2のべき
  T query(long a,long b){
    return query(a,b,0,0,n);
  }
  private:
  T query(long a,long b,long k,long l,long r){
    if(r<=a || b<=l) return T(); //ここでINT_MAXを使用していることに注意
    if(a<=l && r<=b)return dat[k];
    return add(query(a,b,2*k+1,l,(l+r)/2),query(a,b,2*k+2,(l+r)/2,r));
  }
};
int main(){
  long N;cin>>N;string S;cin>>S;
  long Q;cin>>Q;vector<long>K(Q);for(long i=0;i<Q;i++)cin>>K[i];

  vector<C_DMC>A(N);for(int i=0;i<N;i++)A[i]=C_DMC(S[i]);
  SegTree<C_DMC> st(A);

  for(long q=0;q<Q;q++){
    long ans=0;
    for(long s=0;s<N;s++){
      ans+=st.query(s,s+K[q]).DMC-st.query(s+1,min(s+K[q],N)).DMC;
    }
    cout<<ans<<endl;
  }
}

