typedef unsigned long long		u64;

u64 Solve(const string & s, int n, int k)
{
	deque<pair<int,int>> que;
	const char* pS = &s[0];
	u64 ans = 0;

	for (int index = 0; index < n; ++index)
	{
		char ch = pS[index];

		while (que.size() > 0 && index - que.begin()->first >= k)
		{
			que.pop_front();
		}

		if (ch == 'D')
		{
			que.push_back(pair<int, int>(index, 0));
		}
		else if (ch == 'M')
		{
			for (auto & v : que)
			{
				++v.second;
			}
		}
		else if (ch == 'C')
		{
			for (auto v : que)
			{
				ans += v.second;
			}
		}
	}

	return ans;
}

