int N, A[2000005], M[2000005], C[2000005];
string s;

void init(){

  for(int i=0;i<N;i++){
    if( s[i] == 'M' ) M[i] = 1;
    if( s[i] == 'C' ) C[i] = 1;
  }

  for(int i=1;i<N;i++){
    M[i] += M[i-1];
    C[i] += C[i-1];
  }

  int sum = 0;

  for(int i=N-1;i>=0;i--){

    if( s[i] == 'C' ) sum++;

    if( s[i] == 'M' ) A[i] = sum;

  }

  for(int i=N-2;i>=0;i--) A[i] += A[i+1];

}

int getM(int l, int r){

  if( l >= N ) return 0;

  if( r >= N ) r = N-1;

  int res = M[r];

  if( l ) res -= M[l-1];

  return res;
}

int getC(int l, int r){

  if( l >= N ) return 0;

  if( r >= N ) r = N-1;

  int res = C[r];

  if( l ) res -= C[l-1];

  return res;
}

