    int sum = 0;

    for(int i=0;i<N;i++){

      if( s[i] == 'D'){

	int cal = A[i] - A[i+k];

	cal -= getM( i, i + k - 1 ) * getC( i + k, N - 1 );

	sum += cal;

      }

    }

    cout<<sum<<endl;

  }

  return 0;
}

