LL dp[3][1000005];

void solve(int x){
   LL bm = 0;
   for(int i=0;i<s.size();i++){
      if(i>0){
         for(int j=0;j<3;j++) dp[j][i] = dp[j][i-1];
      }
      else{
         for(int j=0;j<3;j++) dp[j][i] = 0LL;
      }
      if(i>=x){
         if(s[i-x] == 'M') bm--;
         else if(s[i-x] == 'D') dp[1][i]-=bm, dp[0][i]--;
      }
      if(s[i] == 'C') dp[2][i]+=dp[1][i];
      else if(s[i] == 'M') dp[1][i]+=dp[0][i], bm++;
      else if(s[i] == 'D') dp[0][i]++;
   }
   printf("%lld\n",dp[2][s.size()-1]);
   return;
}

