  rep(i,n){
    if(s[i] == 'C') cnt[i+1] = cnt[i] + 1;
    else cnt[i+1] = cnt[i];
  }

  vector<long> sv(n, 0);
  {
    int cur = 0;
    rep(i,n){
      if(s[i]=='M') cur++;
