int64_t solve()
{
	int k;
	scanf("%d", &k);

	int64_t ans{}, count{}, sum{};
	for (int i{N - 1}; i >= 0; i--)
	{
		if (i + k < N && S[i + k] == 'C')
		{
			count--;
			sum -= Mtable[i + 1] - Mtable[i + k];
		}
		if (S[i] == 'D')
			ans += sum;
		else if (S[i] == 'M')
			sum += count;
		else if (S[i] == 'C')
			count++;
	}
	return ans;
}

