inline int solution(istream &cin, ostream &cout) {
  int N;
  string S;
  int Q;
  cin >> N >> S >> Q;
  vector<int> K(Q);
  for (int i = 0; i < Q; ++i) cin >> K[i];
  for (auto k : K) {
    int64_t step1 = 0, step2 = 0, step3 = 0;
    int64_t m_count = 0;
    for (int i = 0; i < N; ++i) {
      if (i - k >= 0) {
        switch (S[i - k]) {
          case 'D':
            step2 -= m_count;
            --step1;
            break;
          case 'M':
            --m_count;
            break;
        }
      }
      switch (S[i]) {
        case 'D':
          step1++;
          break;
        case 'M':
          m_count++;
          step2 += step1;
          break;
        case 'C':
          step3 += step2;
          break;
      }
    }
    cout << step3 << endl;
  }
  return 0;
}

