                while(r<D.size()&&D[r]<C[i]) ss+=sm[D[r]],++r;
                ans+=(r-l)*sm[C[i]]-ss;
            }
            out<<ans<<endl;
        }
    }
};

int main() {
    CKDMC solver;
    std::istream& in(std::cin);
    std::ostream& out(std::cout);
    solver.solve(in, out);
    return 0;
}

