    long long n = (long long)s.size();

    long long d = 0;
    long long m = 0;
    long long dm = 0;
    long long dmc = 0;
    long long l = 0;
    for(long long r = 0; r < n; r++){

        if(r - l == k){
            if(s[l] == 'D'){
                d--;
                dm -= m;
            }else if(s[l] == 'M'){
                m--;
            }

            l++;
        }

        if(s[r] == 'D'){
            d++;
        }else if(s[r] == 'M'){
            dm += d;
            m++;
        }else if(s[r] == 'C'){
            dmc += dm;
        }




    }


    return dmc;
}

