	scanf("%d",&Q);
	for(int i = 0 ; i < Q ; i++){
		scanf("%d",&k[i]);
	}

	for(int testcase = 0 ; testcase < Q ; testcase ++){
		int K = k[testcase];
		int r = 0;
		long long cnt_m = 0;
		long long cnt_c = 0;
		long long cnt_mc = 0;
		long long ret = 0;
		for(int loc = 0 ; loc < N ; loc ++){
