			else if(S[loc] == 'M'){
				cnt_m --;
				cnt_mc -= cnt_c;
			}
			else if(S[loc] == 'C'){
				cnt_c --;
			}
			//cout << loc << " " << cnt_m << " " << cnt_c << " " << cnt_mc << " " << ret << endl;
		}
