#define SIZE_BUF (30)

using namespace std;

int main(int argc, char *argv[]) {
  // read inputs
  char S[MAX_N + 2], buf[SIZE_BUF];
  int N, Q;
  int ks[MAX_Q];
  scanf("%d", &N);
  fgets(buf, SIZE_BUF, stdin);
  fgets(S, MAX_N + 2, stdin);
  scanf("%d", &Q);
  for (int i = 0; i < Q; i++)
    scanf("%d", &ks[i]);

  // count number of ms up to each index
  int acc_num_ms[MAX_N + 1];
  acc_num_ms[0] = 0;
  for (int i = 1; i <= N; i++)
    acc_num_ms[i] = acc_num_ms[i - 1] + (S[i - 1] == 'M' ? 1 : 0);

  // solve for each k
  for (int q = 0; q < Q; q++) {
    const int k = ks[q];
    int num_ds = 0, num_dm_pairs = 0;
    long ans = 0;
    // look through each character
    for (int i = 0; i < N; i++) {
      // check for out of range ds and remove if them
      // only one element becomes invalid at a time
      if (i >= k && S[i - k] == 'D') {
        num_dm_pairs -= acc_num_ms[i] - acc_num_ms[i - k + 1];
        num_ds--;
      }

      // check the current character and act accordingly
      if (S[i] == 'D') {
        // add to list of 'D's
        num_ds++;
      } else if (S[i] == 'M') {
        // update num_dm_pairs
        num_dm_pairs += num_ds;
      } else if (S[i] == 'C') {
        // increment number of triplets
        ans += num_dm_pairs;
      }
    }
    printf("%ld\n", ans);
  }

  return 0;
}

