void solver() {
  int N = input();

  string s = "_" + input< string >();

  vector< int64 > rd(N + 1), rm(N + 1);
  range(i, 1, N + 1) {
    rd[i] = rd[i - 1] + (s[i] == 'D');
    rm[i] = rm[i - 1] + (s[i] == 'M');
  }

  auto f = [&](int k) {
    int64 res = 0;

    int64 cnt = 0;
    range(i, 1, N + 1) {
      if (i - k >= 0 && s[i - k] == 'D') {
        cnt -= (rm[i] - rm[i - k]);
      }

      if (s[i] == 'C') res += cnt;

      if (s[i] == 'M') {
        cnt += (rd[i] - rd[max(0, i - k)]);
      }
    }

    return res;
  };

  int q = input();
  while (q--) cout << f(input()) << endl;
}

