			c[++lc] = i;
		if (s[i] == 'M')
			sum[i + 1] = sum[i] + 1;
		else
			sum[i + 1] = sum[i];
	}
	csum[0] = 0;
	for (int i = 1; i <= lc; i++)
	{
		csum[i] = csum[i - 1] + 1ll * sum[c[i]];
	}
