void findTriplets(vector<int>* pos, vector<int>& qs) {
  vector<int> counts;
  vector<ll> prefixSum (1, 0);
  int idxB = 0;
  int lenB = pos[1].size();
  ll sum = 0;
  for(int i=0; i<pos[2].size(); i++) {
    while(pos[2][i] > pos[1][idxB] && idxB < lenB) {
      idxB++;
    }
    counts.push_back(idxB);
    sum += idxB;
    prefixSum.push_back(sum);
  }
  for(auto q : qs) {
    ll ans = 0;
    for(auto k : pos[0]) {
      int low = lower_bound(pos[2].begin(), pos[2].end(), k) - pos[2].begin();
      int high = lower_bound(pos[2].begin(), pos[2].end(), k+q) - pos[2].begin();
      int offset = lower_bound(pos[1].begin(), pos[1].end(), k) - pos[1].begin();
      ans += prefixSum[high] - prefixSum[low] - (offset * (high-low));
    }
    cout << ans << endl;
  }
  return;
}

