    if(s[i] == 'D') {
      pos[0].push_back(i);
    } else if (s[i] == 'M') {
      pos[1].push_back(i);
    } else if (s[i] == 'C') {
      pos[2].push_back(i);
    }
  }
  findTriplets(pos, q);
  return 0;
}

