using namespace std;
LL d[1000001];
LL m[1000001];
LL c[1000001];
LL tree[500001];
LL f(int a,int b,int c,int d)   {
    if(a > b || c > d)  {
        return 0;
    }
    LL temp =  (m[b] - m[a - 1]) * (::c[d] - ::c[c - 1]);
    // cout << "merge : " << a << " " << b << " " << c << " " << d << " " << temp << endl;
    return temp;
}
void build(int node,int i,int j)    {
    if(i > j)   {
        return;
    }
    if(i == j)  {
        tree[node] = 0;
        return;
    }
    int mid = (i + j) / 2;
    build(2 * node , i , mid);
    build(2 * node + 1 , mid + 1 , j);
    tree[node] = tree[2 * node] + tree[2 * node + 1] + f(i , mid , mid + 1 , j);
}

LL query(int node,int i,int j,int l,int r)  {
    if(i > j || j < l || i > r) {
        return 0;
    }
    if(i >= l && j <= r)    {
        return tree[node];
    }
    int mid = (i  + j) / 2;
    return query(2 * node , i , mid , l , r) + query(2 * node + 1 , mid + 1 , j , l , r) + f(max(i , l) , min(mid , r) , max(mid + 1 , l) , min(j ,r));
}

