#define REP(i, n) for (int i = 0; (i) < (int)(n); ++ (i))
using ll = long long;
using namespace std;

ll solve(int n, string const & s, int k) {
    ll cnt_dmc = 0;
    int cnt_m = 0;
    int cnt_c = 0;
    ll cnt_mc = 0;
    auto push = [&](int i) {
        if (s[i] == 'M') {
            cnt_m += 1;
        } else if (s[i] == 'C') {
            cnt_c += 1;
            cnt_mc += cnt_m;
        }
    };
    auto pop = [&](int i) {
        if (s[i] == 'D') {
            cnt_dmc += cnt_mc;
        } else if (s[i] == 'M') {
            cnt_m -= 1;
            cnt_mc -= cnt_c;
        } else if (s[i] == 'C') {
            cnt_c -= 1;
        }
    };
    REP (i, k) {
        push(i);
    }
    REP (i, n) {
        pop(i);
        if (i + k < n) push(i + k);
    }
    return cnt_dmc;
}

int main() {
    int n; cin >> n;
    string s; cin >> s;
    int q; cin >> q;
    while (q --) {
        int k; cin >> k;
        cout << solve(n, s, k) << endl;
    }
    return 0;
}

