auto solve() {
    int N;
    cin >> N;

    int SIZE = N * 2 + 10;

    vll sumC(SIZE, 0);
    vll sumM(SIZE, 0);
    vll sumBef(SIZE, 0);


    string S;
    cin >> S;
    S.reserve(N);

    REP(i, N) {
        sumC[i + 1] = sumC[i] + (int) (S[i] == 'C');
        sumM[i + 1] = sumM[i] + (int) (S[i] == 'M');
        sumBef[i + 1] = sumBef[i];
        if (S[i] == 'C')
            sumBef[i + 1] += sumM[i + 1];
    }
    FOR(i, N + 1, SIZE) {
        sumC[i] = sumC[i - 1];
        sumM[i] = sumM[i - 1];
        sumBef[i] = sumBef[i - 1];
    }

    int Q;
    cin >> Q;
    while (Q--) {
        int k;
        cin >> k;

        ll res = 0;
        REP(i, N + 1) {
            if (S[i] == 'D') {
                ll diffC = sumC[i + k] - sumC[i];
                ll diffBef = sumBef[i + k] - sumBef[i];
                res += diffBef - diffC * sumM[i + 1];
            }
        }
        cout << res << endl;
    }

}

