int n,q,f[N],g[N];
char s[N];
LL res,ans;
void solve()
{
	int k=read();
	ans=0;
	LL pr=0,d=0,c=0,m=0;
	for(int i=0;i<k;i++){
		if(s[i]=='D'){
			d++;
		}	
		if(s[i]=='M'){
			m++; pr+=d;
		}
		if(s[i]=='C'){
