long long solve() {
  long long now = 0, ans = 0;
  for(long long i = 0; i < n; ++i) {
    if(i >= k && s[i - k] == 'D') {
      if(i != 0) now -= cnt[i - 1][1];
      now += cnt[i - k][1];
    }
    if(s[i] == 'M') {
      if(i != 0) now += cnt[i - 1][0];
      if(i >= k) now -= cnt[i - k][0];
    }
    if(s[i] == 'C') ans += now;
  }
  return ans;
}

