const int N = 1e6 + 1;

int n;

char s[N];

ll cp[2*N];

ll pp[N];

ll dp[N];

ll solve (int k) {
  memset (dp, 0, sizeof dp);
  memset (cp, 0, sizeof cp);
  memset (pp, 0, sizeof pp);

  for (int i = 1; i <= 2*n; i++)
    cp[i] = cp[i - 1] + (s[i] == 'C');

  for (int i = 1; i <= n; i++)
    pp[i] = pp[i - 1] + (s[i] == 'D') * 1ll * cp[i + k - 1];

  for (int i = 1; i <= n; i++)
    dp[i] = dp[i - 1] + (s[i] == 'D');

  ll ans = 0;
  for (int i = 1; i <= n; i++) {
    if (s[i] == 'M') {
      int l = max (0, i - k + 1);
      ll x = pp[i] - pp[l];
      x -= (dp[i] - dp[l]) * cp[i-1];
      ans += x;
    }
  }
  return ans;
}

