        cntM[i] = (i > 0 ? cntM[i - 1] : 0) + (S[i] == 'M');
    }
    REPR(i, N - 1) {
        cntC[i] = (i < N - 1 ? cntC[i + 1] : 0) + (S[i] == 'C');
    }

    vector<int> ScntC(N);
    REP(i, N) {
        if (S[i] != 'M') continue;
        ScntC[i] = cntC[i];
    }
    REP(i, N - 1) {
        ScntC[i + 1] += ScntC[i];
    }

    // [a, c]
    auto f = [&](int a, int c) {
        int R = c < N - 1 ? cntC[c + 1] : 0;
        int cM = cntM[c] - (a > 0 ? cntM[a - 1] : 0);
        int ans = ScntC[c] - (a > 0 ? ScntC[a - 1] : 0) - R * cM;
        return ans;
    };

    REP(q, Q) {
        int ans = 0;
        REP(i, N - 2) {
            if (S[i] != 'D') continue;
            ans += f(i, min(N - 1, i + k[q] - 1));
        }
        cout << ans << endl;
    }
    return (0^_^0);
}

