long long solve(int k) {
    long long ret = 0;
    long long eff_D = 0;
    long long eff_M = 0;
    long long eff_DM = 0;

    for (int i = 0; i < N; i++) {
        if (S[i] == 'D') {
            eff_D++;
        } else if (S[i] == 'M') {
            eff_M++;
            eff_DM += eff_D;
        } else if (S[i] == 'C') {
            ret += eff_DM;
        }

        if (0 <= i - k + 1) {
            if (S[i-k+1] == 'D') {
                eff_D--;
                eff_DM -= eff_M;
            }
        }

        if (0 <= i - k) {
            if (S[i-k] == 'D') {
                //eff_DM -= eff_M;
            } else if (S[i-k] == 'M') {
                eff_M--;
            }
        }
        //std::cout << "check:" << i << " " << eff_D << " " << eff_M << " " << eff_DM << " " << ret << std::endl;
    }

    return ret;
}

