template<class OP>
class SegmentTree {
  public:
    using T = typename OP::T;
    OP op;
    int n;
    vector<T> data, pool;
    // 適切に改造すると，可換でなくてももうちょっとできる...
    SegmentTree(int n_) {
        n = 1; while(n < n_) n *= 2;
        data.resize(2 * n - 1, op.update_unit());
        pool.resize(2 * n - 1, op.query_unit());
    }
    SegmentTree(const vector<T> &vec) {
        n = 1; while(n < vec.size()) n *= 2;
        data.resize(2 * n - 1, op.update_unit());
        pool.resize(2 * n - 1, op.query_unit());
        rep(i, vec.size()) data[n + i - 1] = vec[i];
        for(int i = n - 2; i >= 0; i--) {
            data[i] = op.query(data[left_child(i)], data[right_child(i)]);
        }
    }
    // [a, b)
    T query(int a, int b) {
        assert(0 <= a and a < b and b <= n);
        return query(a, b, 0, 0, n);
    }
    // a[i] = f(a[i], v) for i in [a, b)
    void update(int a, int b, T v) {
        assert(0 <= a and a < b and b <= n);
        update(a, b, 0, 0, n, v);
    }
  private:
    // [a, b) 更新区間, i 今いるNode, [l, r) はNode[i]の担当区間
    void update(int a, int b, int i, int l, int r, T v) {
        if(out_of_range(a, b, l, r)) return;
        if(within_range(a, b, l, r)) {
            pool[i] = op.update(pool[i], v);
            data[i] = op.update(data[i], v);
            return;
        }
        // 遅延伝搬させる
        int m = (l + r) / 2;
        // ためていたものを流す
        update(l, m, left_child(i), l, m, pool[i]);
        update(m, r, right_child(i), m, r, pool[i]);
        pool[i] = op.update_unit(); // 流したのでクリア
        // 新しい値を流す
        update(a, b, left_child(i), l, m, v);
        update(a, b, right_child(i), m, r, v);
        data[i] = op.query(data[left_child(i)], data[right_child(i)]);
    }
    // index(a) の値を求める, 今node[i],
    T query(int a, int b, int i, int l, int r) {
        if(out_of_range(a, b, l, r) or (int)data.size() <= i) return op.query_unit();
        if(within_range(a, b, l, r)) return data[i] * (r - l);
        int m = (l + r) / 2;
        T vl = query(a, b, left_child(i), l, m);
        T vr = query(a, b, right_child(i), m, r);
        return op.update(op.query(vl, vr), pool[i]);
    }
    bool out_of_range(int a, int b, int l, int r) { return r <= a or b <= l; }
    bool within_range(int a, int b, int l, int r) { return a <= l and r <= b; }
    int left_child(int i) { return i * 2 + 1; }
    int right_child(int i) { return i * 2 + 2; }
    int parent(int i) { return (i - 1) / 2; }
};

struct RSQOnSum {
    using T = ll;
    T update(const T &a, const T &b) { return a + b; }
    T query(const T &a, const T &b)  { return a + b; }
    static T update_unit() { return 0; }
    static T query_unit()  { return 0; }
};

struct RSQRAQ {
  int n;
  vector<ll> dat, lazy;

  RSQRAQ(){}
  RSQRAQ(int n_) {
    n = 1; while(n < n_) n *= 2;
    dat.assign(n*2, 0);
    lazy.assign(n*2, 0);
  }

  void eval(int len, int k) {
    if(lazy[k] == 0) return;
    if(k*2+1 < n*2-1) {
      lazy[2*k+1] += lazy[k];
      lazy[2*k+2] += lazy[k];
    }
    dat[k] += lazy[k]*len;
    lazy[k] = 0;
  }

  // [a, b)
  ll update(int a, int b, ll x, int k, int l, int r) {
    eval(r-l, k);
    if(b <= l || r <= a) return dat[k];
    if(a <= l && r <= b) {
      lazy[k] += x;
      return dat[k] + lazy[k]*(r-l);
    }
    return dat[k] = update(a, b, x, 2*k+1, l, (l+r)/2) + update(a, b, x, 2*k+2, (l+r)/2, r);
  }
  ll update(int a, int b, ll x) { return update(a, b, x, 0, 0, n); }

  // [a, b)
  ll query(int a, int b, int k, int l, int r) {
    eval(r-l, k);
    if(b <= l || r <= a) return 0;
    if(a <= l && r <= b) return dat[k];
    ll vl = query(a, b, 2*k+1, l, (l+r)/2);
    ll vr = query(a, b, 2*k+2, (l+r)/2, r);
    return vl + vr;
  }
  ll query(int a, int b) { return query(a, b, 0, 0, n); }
};

class Solver {
  public:

    ll solve2(int N, const string S, int K) {
        vector<int> pos_d, pos_m, pos_c;
        rep(i, S.size()) {
            if(S[i] == 'D') pos_d.push_back(i);
            if(S[i] == 'M') pos_m.push_back(i);
            if(S[i] == 'C') pos_c.push_back(i);
        }
        map<int, int> rpos_d, rpos_m, rpos_c;
        rep(i, pos_d.size()) rpos_d[pos_d[i]] = i;
        rep(i, pos_m.size()) rpos_m[pos_m[i]] = i;
        rep(i, pos_c.size()) rpos_c[pos_c[i]] = i;

        // SegmentTree<RSQOnSum> seg(pos_c.size() + 1);
        RSQRAQ seg(pos_c.size() + 1);

        for(int i : pos_m) {
            int j = upper_bound(all(pos_c), i) - begin(pos_c);
            if(j < pos_c.size() + 1)
                seg.update(j, pos_c.size() + 1, 1);
        }
        // cerr << "! ";
        // rep(i, pos_c.size()) cerr << seg.query(0, i + 1) << " ";
        // cerr << endl;

        ll ans = 0;
        rep(i, S.size()) {
            if(S[i] == 'M') {
                int j = upper_bound(all(pos_c), i) - begin(pos_c);
                if(j < pos_c.size() + 1)
                    seg.update(j, pos_c.size() + 1, -1);
            }
            if(S[i] == 'D') {
                int j = upper_bound(all(pos_c), i) - begin(pos_c);
                int k = upper_bound(all(pos_c), i + K - 1) - begin(pos_c);
                if(j < pos_c.size() + 1 and j < k) ans += seg.query(j, k);
                // cerr << "I'm D " << i << " j,k " << j << " " << k << endl;
                // repeat(l, j, k) cerr << "\t" << seg.query(j, j+1) << " ";
                // cerr << " : " << seg.query(j, k);
                // cerr << endl;
            }
        }
        return ans;
    }

    bool solve() {
        int N; cin >> N;
        string S; cin >> S;
        int Q; cin >> Q;
        rep(q, Q) {
            int K; cin >> K;
            cout << solve2(N, S, K) << endl;
        }

        return 0;
    }
};

int main() {
    cin.tie(0);
    ios::sync_with_stdio(false);
    Solver s;
    s.solve();
    return 0;
}

