    if(s[p]=='M')
    {
        DM+=D;
        cnt_M++;
    }
}

inline void del(int p)
{
    if(s[p]=='D')
    {
        D--;
        DM-=cnt_M;
    }
    if(s[p]=='M')
    {
        cnt_M--;
    }
