  cin >> N >> S >> Q;
  vector<int> k(Q);
  for(int i=0;i<Q;i++){
	cin >> k[i];
  }

  vector<int> D;
  vector<int> M;
  vector<int> C;
  for(int i=0;i<S.size();i++){
	if(S[i]=='D'){
	  D.push_back(i);
	}else if(S[i]=='M'){
	  M.push_back(i);
	}else if(S[i]=='C'){
	  C.push_back(i);
	}
  }
  vector<int> k_DMC;
  for(int i=0;i<D.size();i++){
	for(int j=C.size()-1;j>=0;j--){
	  if(C[j]<D[i]){break;}
	  for(int l=0;l<M.size();l++){
		if(C[j]>M[l] && M[l]>D[i]){
		  k_DMC.push_back(C[j]-D[i]);
		}else if(C[j]<=M[l]){
		  break;
		}
	  }
	}
  }


  sort(k_DMC.begin(),k_DMC.end());
  for(int i=0;i<k.size();i++){
	int c=0;
	for(int j=0;j<k_DMC.size();j++){
	  if(k_DMC[j]<k[i]){
		c++;
	  }else{
		break;
	  }
	}
	cout << c << endl;
  }

  return 0;
}

