  using FPS = FormalPowerSeries<long long>;
  int N;
  cin >> N;
  string S;
  cin >> S;
  FPS D(N + 1), C(N + 1), L(N + 1), R(N + 1);
  for (int i = 0; i < N; i++) {
    D[i + 1] = S[i] == 'D';
    C[i + 1] = S[N - 1 - i] == 'C';
    L[i + 1] = S[i] == 'M';
    R[i + 1] = S[N - 1 - i] == 'M';
    L[i + 1] += L[i];
    R[i + 1] += R[i];
  }
