  debug(B);
  for (int i = 0; i <= N; i++) {
    L[i] *= D[i];
    R[i] *= C[i];
  }
  auto A = D * C * B - L * C - R * D;
  long long dp[3];
  dp[0] = dp[1] = dp[2] = 0;
  for (int i = 0; i < N; i++) {
    if (S[i] == 'D') dp[0]++;
    if (S[i] == 'M') dp[1] += dp[0];
    if (S[i] == 'C') dp[2] += dp[1];
  }
  long long ans[N + 1];
  for (int k = N; k >= 0; k--) {
    ans[k] = -A[N - k];
    if (k < N) ans[k] += ans[k + 1];
  }
  for (int k = 0; k <= N; k++) ans[k] += dp[2];
  int Q;
  cin >> Q;
  while (Q--) {
