ll cnt_D,cnt_M,cnt_DM,ans; 
void solve(){
	cnt_D=cnt_M=cnt_DM=ans=0;
	rep(i,1,K){
		if(s[i]=='D'){
			cnt_D++;
		}else if(s[i]=='M'){
			cnt_DM+=cnt_D;
			cnt_M++;
		}else if(s[i]=='C'){
			ans+=cnt_DM;
		}
	}
	rep(i,2,n-K+1){
		int l=i,r=i+K-1;
		if(s[l-1]=='D'){
			cnt_DM-=cnt_M;
			cnt_D--;
		}else if(s[l-1]=='M'){
			cnt_M--;
		}

		if(s[r]=='M'){
			cnt_DM+=cnt_D;
			cnt_M++;
		}else if(s[r]=='C'){
			ans+=cnt_DM;
		}else if(s[r]=='D'){
			cnt_D++;
		}
	}
	printf("%llu\n",ans);
} 
