        int res = 0;

        vector<vi> dp(N + 1, vi(3, 0));
        FOR(i, 1, N + 1) {
            REP(j, 3)dp[i][j] = dp[i - 1][j];

            auto get_ind = [&](int t) {
                if (t == 'D') {
                    return 0;
                } else if (t == 'M') {
                    return 1;
                } else if (t == 'C') {
                    return 2;
                }
                return -1;
            };


            { //del
                if (i - 1 - e >= 0) {
                    int ind = get_ind(S[i - 1 - e]);
                    if (ind == 0 || ind == 1) {
                        dp[i][ind]--;
                    }
                    if (ind == 0) {
                        dp[i][2] -= dp[i][1];
                    }
                }
            }


            { //add
                int ind = get_ind(S[i - 1]);
                if (ind == 2) {
                    res += dp[i][2];
                } else if (ind == 0 || ind == 1) {
                    dp[i][ind]++;
                }

                if (ind == 1) {
