		scanf("%d", &k[i]);
	FT cnt(n+10), alpha(n+10);
	for (int i = 0; i < n; i++) {
		if (str[i] == 'C') {
			alpha.update(i, 1);
			cnt.update(i, numOfm);
		} else if (str[i] == 'M') {
			numOfm++;
		}
	}
	for (int idx = 0; idx < q; idx++) {
		ll res = 0;
