			if (str[i] == 'M') numOfm++;
			if (str[i] == 'D') {
				int ran = min(n, i+k[idx]);
				ll numOfc = alpha.query(ran)-alpha.query(i);
				ll sumOfc = cnt.query(ran)-cnt.query(i);
				res += (sumOfc - (numOfm * numOfc));
			}
		}
		printf("%lld\n", res);
	}
}

