/**
 * Built using CHelper plug-in
 * Actual solution is at the top
 *
 * @author mikit
 */
public class Main {
    public static void main(String[] args) {
        InputStream inputStream = System.in;
        OutputStream outputStream = System.out;
        LightScanner in = new LightScanner(inputStream);
        PrintWriter out = new PrintWriter(outputStream);
        CKDMC solver = new CKDMC();
        solver.solve(1, in, out);
        out.close();
    }

    static class CKDMC {
        static int[] mc;
        static int[] cc;
        static String s;

        public void solve(int testNumber, LightScanner in, PrintWriter out) {
            int n = in.ints();
            mc = new int[n + 1];
            cc = new int[n + 1];
            s = in.string();
            for (int i = 0; i < n; i++) {
                mc[i + 1] = mc[i] + (s.charAt(i) == 'M' ? 1 : 0);
                cc[i + 1] = cc[i] + (s.charAt(i) == 'C' ? 1 : 0);
            }

            //System.out.println(Arrays.toString(mc));


            int q = in.ints();
            for (int i = 0; i < q; i++) {
                int k = in.ints();
                long ans = 0;
                long s = 0;
                for (int l = -k; l < n; l++) {
                    int r = l + k;
                    switch (charat(l)) {
                        case 'D':
                            ans += s;
                            break;
                        case 'M':
                            s -= cs(l, r);
                            break;
                    }
                    if (charat(r) == 'C') {
                        s += ms(l, r);
                    }
                }
                out.println(ans);
            }
        }

        private char charat(int i) {
            if (i < 0 || s.length() <= i) {
                return '-';
            } else {
                return s.charAt(i);
            }
        }

        private int ms(int l, int r) {
            return mc[Math.min(mc.length - 1, r + 1)] - mc[Math.max(0, l)];
        }

        private int cs(int l, int r) {
            return cc[Math.min(mc.length - 1, r + 1)] - mc[Math.max(0, l)];
        }

    }

    static class LightScanner {
        private BufferedReader reader = null;
        private StringTokenizer tokenizer = null;

        public LightScanner(InputStream in) {
            reader = new BufferedReader(new InputStreamReader(in));
        }

        public String string() {
            if (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    tokenizer = new StringTokenizer(reader.readLine());
                } catch (IOException e) {
                    throw new UncheckedIOException(e);
                }
            }
            return tokenizer.nextToken();
        }

        public int ints() {
            return Integer.parseInt(string());
        }

    }
}

