    public void solve() {
        int N = in.nextInt();
        String S = in.next();
        int Q = in.nextInt();
        int[] k = in.nextIntArray(Q);

        for (int kk : k) {
            out.println(calc(S, kk));
        }
        out.close();
    }

    private long calc(String s, int kk) {
        int n = s.length();
        Deque<Integer> dIndex = new ArrayDeque<>();
        int mCnt = 0;
        long charge = 0;
        long res = 0;
        for (int idx = 0; idx < n; idx++) {
            while (!dIndex.isEmpty() && idx - dIndex.peekLast() >= kk) {
                int leftDIdx = dIndex.pollLast();
                charge -= mCnt;
                if (dIndex.isEmpty()) {
                    mCnt = 0;
                } else {
                    for (int i = leftDIdx; i < dIndex.peekLast(); i++) {
                        if (s.charAt(i) == 'M') {
                            mCnt--;
                        }
                    }
                }
            }

            if (s.charAt(idx) == 'D') {
                dIndex.push(idx);
            } else if (s.charAt(idx) == 'M') {
                mCnt++;
                charge += dIndex.size();
            } else if (s.charAt(idx) == 'C') {
                res += charge;
            }
        }
        return res;
    }

