public class Main {
    static char[] s;
    static long[] mCum;
    static long[] cCum;
    static long[] cum;
    static int n;
    static int q;
    static int[] k;

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        n = sc.nextInt();
        s = sc.next().toCharArray();
        q = sc.nextInt();
        k = new int[q];
        for (int i = 0; i < q; i++) {
            k[i] = sc.nextInt();
        }
        mCum = new long[n + 1];
        for (int i = 0; i < n; i++) {
            mCum[i + 1] = mCum[i] + (s[i] == 'M' ? 1 : 0);
        }
        cCum = new long[n+1];
        for (int i = 0; i < n; i++) {
            cCum[i+1] = cCum[i] + (s[i] == 'C' ? 1 : 0);
        }
        cum = new long[n+1];
        for (int i = 0; i < n; i++) {
            cum[i+1] = cum[i] + (s[i] == 'C' ? mCum[i] : 0);
        }

        List<Integer> left = new ArrayList<>();
