        int q = in.nextInt();
        int[] k = in.nextIntArray(q);
        int[] d = new int[n + 1];
        int[] c = new int[n + 1];
        for (int i = n - 1; i >= 0; i--) {
            if (s[i] == 'D') {
                d[i]++;
            }
            d[i] += d[i + 1];
        }
        for (int i = 0; i < n; i++) {
