            c[i + 1] += c[i];
        }
        for (int i = 0; i < q; i++) {
            out.println(f(k[i]));
        }
    }

    long f(int k) {
        long d = 0;
        long dm = 0;
        long m = 0;
        long ans = 0;
        for (int i = 0; i < n; i++) {
            if (s[i] == 'D') {
                d++;
            }
            if (s[i] == 'M') {
                dm += d;
                m++;
            }
            if (s[i] == 'C') {
                ans += dm;
            }
            if (i - k >= 0 && s[i - k] == 'D') {
                d--;
                dm -= m;
            }
            if (i - k >= 0 && s[i - k] == 'M') {
                m--;
            }
        }
        return ans;
    }

