        }
        for (int i = 1; i <= n; i++) {
            d[i] += d[i - 1];
        }
        long[] m = new long[n + 1];
        for (int i = 1; i <= n; i++) {
            if (s[i - 1] == 'M') {
                m[i]++;
            }
        }
        for (int i = 1; i <= n; i++) {
            m[i] += m[i - 1];
        }
        long[] dm = new long[n + 1];
        for (int i = 1; i <= n; i++) {
            if (s[i - 1] == 'M') {
                dm[i] = d[i - 1];
            }
        }
        for (int i = 1; i <= n; i++) {
            dm[i] += dm[i - 1];
        }
        int q = fsc.nextInt();
        StringBuilder sb = new StringBuilder();
        while (q-- > 0) {
            int k = fsc.nextInt();
            long a = 0;
            for (int i = 0; i < n; i++) {
                if (s[i] == 'C') {
                    a += dm[i] - dm[max(0, i - k + 1)] - (m[i] - m[max(0, i - k + 1)]) * d[max(0, i - k + 1)];
                }
            }
            sb.append(a).append('\n');
        }
        System.out.print(sb);
    }
}


class FastScanner {
    private final InputStream in = System.in;
    private final byte[] buffer = new byte[1024];
    private int ptr = 0;
    private int buflen = 0;

    private boolean hasNextByte() {
        if (ptr < buflen) {
            return true;
        } else {
            ptr = 0;
            try {
                buflen = in.read(buffer);
            } catch (IOException e) {
                e.printStackTrace();
            }
            if (buflen <= 0) {
                return false;
            }
        }
        return true;
    }

    private int readByte() {
        if (hasNextByte()) {
            return buffer[ptr++];
        } else {
            return -1;
        }
    }

    private static boolean isPrintableChar(int c) {
        return 33 <= c && c <= 126;
    }

    public boolean hasNext() {
        while (hasNextByte() && !isPrintableChar(buffer[ptr])) {
            ptr++;
        }
        return hasNextByte();
    }

    public String next() {
        if (!hasNext()) {
            throw new NoSuchElementException();
        }
        StringBuilder sb = new StringBuilder();
        int b = readByte();
        while (isPrintableChar(b)) {
            sb.appendCodePoint(b);
            b = readByte();
        }
        return sb.toString();
    }

    public long nextLong() {
        if (!hasNext()) {
            throw new NoSuchElementException();
        }
        long n = 0;
        boolean minus = false;
        int b = readByte();
        if (b == '-') {
            minus = true;
            b = readByte();
        }
        if (b < '0' || '9' < b) {
            throw new NumberFormatException();
        }
        while (true) {
            if ('0' <= b && b <= '9') {
                n *= 10;
                n += b - '0';
            } else if (b == -1 || !isPrintableChar(b)) {
                return minus ? -n : n;
            } else {
                throw new NumberFormatException();
            }
            b = readByte();
        }
    }

    public int nextInt() {
        long nl = nextLong();
        if (nl < Integer.MIN_VALUE || nl > Integer.MAX_VALUE) {
            throw new NumberFormatException();
        }
        return (int) nl;
    }

    public double nextDouble() {
        return Double.parseDouble(next());
    }
}

