		int Q = sc.nextInt();
		int[] k = new int[Q];
		sc.fill(k);

		Map<Integer, Pair> map = new HashMap<>();
		List<Integer> list = new ArrayList<>();
		Integer[] cache = null;
		for (int i = 0; i < S.length; i++) {
			switch (S[i]) {
			case 'D':
				list.add(i);
				cache = null;
				break;
			case 'M':
				if (cache == null) {
					cache = list.toArray(new Integer[list.size()]);
				}
				Pair p = new Pair();
				p.d = cache;
				map.put(i, p);
				break;
			}
		}

		list.clear();
		cache = null;
		for (int i = S.length - 1; i >= 0; i--) {
			switch (S[i]) {
			case 'C':
				list.add(i);
				cache = null;
				break;
			case 'M':
				if (cache == null) {
					cache = list.toArray(new Integer[list.size()]);
				}
				Pair p = map.get(i);
				p.c = cache;
				break;
			}
		}

		StringBuilder sb = new StringBuilder();
		for (int i = 0; i < k.length; i++) {
			long sum = 0;

			Map<Pair, Long> ansCache = new HashMap<>();
			for (Pair p : map.values()) {
				Long ans = ansCache.get(p);
				if (ans == null) {
					long dmc = 0;
					for (int d : p.d) {
						int length = p.c.length;
						for (int c : p.c) {
							if (c - d < k[i]) {
								dmc += length;
								break;
							}
							length--;
						}
					}
					ansCache.put(p, dmc);
					ans = dmc;
				}

				sum += ans;
			}

			sb.append(sum).append(System.lineSeparator());
		}

		System.out.print(sb.toString());
	}

