	public static void main(String args[]) {

		Scanner sc=new Scanner(System.in);
		int n=sc.nextInt();
		String s=sc.next();
		int q=sc.nextInt();
		int k[]=new int[q];


		for(int i=0;i<q;++i) {
			k[i]=sc.nextInt();
			int countd=0, countm=0,next=0, ans=0;
			for (int m=0;m<n;++m) {

				if(m-k[i]>=0) {
				if(s.charAt(m-k[i])=='D') {--countd; next=next-countm;}
				else if(s.charAt(m-k[i])=='M')--countm; 
				}

				if(s.charAt(m)=='D')++countd;
				else if(s.charAt(m)=='M') {++countm; next=next+countd;} 
				else if(s.charAt(m)=='C')ans=ans+next;
			}
			System.out.println(ans);
		}

	}
}

import java.io.*;
import java.util.*;

class Solver {
  final int n;
  final char[] cs;
  final int q;
  final int[] ks;

  Solver(int n, char[] cs, int q, int[] ks) {
    this.n = n;
    this.cs = cs;
    this.q = q;
    this.ks = ks;
  }

  private long solve(int k) {
    long countD = 0;
    long countM = 0;
    long countDM = 0;
    long countDMC = 0;
    for (int i = 0; i < n; i++) {
      switch(cs[i]) {
        case 'D':
          countD++;
          break;
        case 'M':
          countM++;
          countDM += countD;
          break;
        case 'C':
          countDMC += countDM;
          break;
      }
      if (i >= k-1) {
        switch(cs[i - k + 1]) {
          case 'D':
            countD--;
            countDM -= countM;
            break;
          case 'M':
            countM--;
            break;
        }
      }
    }
    return countDMC;
  }

  public long[] solve() {
    long[] answers = new long[q];
    for (int i = 0; i < q; i++) {
      answers[i] = solve(ks[i]);
    }
    return answers;
  }
}

public class Main {
  private static void execute(ContestReader reader, PrintWriter out) {
    int n = reader.nextInt();
    String s = reader.next();
    int q = reader.nextInt();
    int[] ks = reader.nextIntArray(q);
    long[] answers = new Solver(n, s.toCharArray(), q, ks).solve();
    for (long answer : answers) {
      out.println(answer);
    }
  }

  public static void main(String[] args) {
    ContestReader reader = new ContestReader(System.in);
    PrintWriter out = new PrintWriter(System.out);
    execute(reader, out);
    out.flush();
  }
}

