import java.util.Arrays;

class SegmentTree {
  private final long[][] unit;
  private final long[][][] tree;
  private final int size;
  private final int d;

  public SegmentTree(int size, int d) {
    size = 1 << (32 - Integer.numberOfLeadingZeros(size));

    this.tree = new long[size * 2][d][d];
    for (int i = 0; i < size * 2; i++) {
      for (int j = 0; j < d; j++) {
        this.tree[i][j][j] = 1;
      }
    }

    this.unit = new long[d][d];
    for (int i = 0; i < d; i++) {
      unit[i][i] = 1;
    }
    this.size = size;
    this.d = d;
  }

  public void update(int i, long[][] n) {
    int k = i + size - 1;

    for (int s = 0; s < d; s++) {
      for (int t = 0; t < d; t++) {
        tree[k][s][t] = n[s][t];
      }
    }

    while (k > 0) {
      k = (k - 1) / 2;
      long[][] a = tree[2 * k + 1];
      long[][] b = tree[2 * k + 2];
      calc(a, b, tree[k]);
    }
  }

  public void calc(long[][] a, long[][] b, long[][] c) {
    for (long[] v : c)
      Arrays.fill(v, 0);

    for (int i = 0; i < d; i++) {
      for (int k = 0; k < d; k++) {
        for (int j = 0; j < d; j++) {
          c[i][j] += b[i][k] * a[k][j];
        }
      }
    }
  }

  private long[][] query(int a, int b, int k, int l, int r) {
    if (b <= l || r <= a) {
      return unit;
    }
    if (a <= l && r <= b) {
      return tree[k];
    } else {
      long[][] ql = query(a, b, 2 * k + 1, l, (l + r) / 2);
      long[][] qr = query(a, b, 2 * k + 2, (l + r) / 2, r);

      long[][] ret = new long[d][d];
      calc(ql, qr, ret);
      return ret;
    }
  }

  public long[][] query(int a, int b) {
    return query(a, b, 0, 0, size);
  }
}



