public class Main {
	public static void main(String[] args) {
		new Main().run();
	}

	void run() {
		Scanner sc = new Scanner();
		PrintWriter pw = new PrintWriter(System.out);
		int N = sc.nextInt();
		char[] cs = sc.next().toCharArray();
		int Q = sc.nextInt();
		int[] K = new int[Q];
		for (int i = 0; i < Q; ++i) {
			K[i] = sc.nextInt();
		}
		for (int i = 0; i < Q; ++i) {
			pw.println(solve(cs, K[i]));
		}
		pw.close();
	}

	long solve(char[] cs, int K) {
		int n = cs.length;
		int d = 0, m = 0, c = 0, dm = 0, mc = 0, dmc = 0;
		for (int i = 0; i < K; ++i) {
			if (cs[i] == 'D') {
				++d;
			} else if (cs[i] == 'M') {
				++m;
				dm += d;
			} else if (cs[i] == 'C') {
				++c;
				mc += m;
				dmc += dm;
			} else {
				continue;
			}
		}
		long ret = 0;
		for (int i = 0; i < n; ++i) {
			if (cs[i] == 'D') {
				ret += mc;
				dmc -= mc;
				dm -= m;
				--d;
			} else if (cs[i] == 'M') {
				mc -= c;
				--m;
			} else if (cs[i] == 'C') {
				--c;
			}
			int tail = i + K;
			if (i + K >= n)
				continue;
			if (cs[tail] == 'D') {
				++d;
			} else if (cs[tail] == 'M') {
				++m;
				dm += d;
			} else if (cs[tail] == 'C') {
				++c;
				mc += m;
				dmc += dm;
			}
		}
		return ret;
	}

	static class Scanner {
		private final InputStream in = System.in;
		private final byte[] buffer = new byte[1024];
		private int ptr = 0;
		private int buflen = 0;

		private boolean hasNextByte() {
			if (ptr < buflen) {
				return true;
			} else {
				ptr = 0;
				try {
					buflen = in.read(buffer);
				} catch (IOException e) {
					e.printStackTrace();
				}
				if (buflen <= 0) {
					return false;
				}
			}
			return true;
		}

		private int readByte() {
			if (hasNextByte())
				return buffer[ptr++];
			else
				return -1;
		}

		private boolean isPrintableChar(int c) {
			return 33 <= c && c <= 126;
		}

		private void skipUnprintable() {
			while (hasNextByte() && !isPrintableChar(buffer[ptr]))
				ptr++;
		}

		public boolean hasNext() {
			skipUnprintable();
			return hasNextByte();
		}

		public String next() {
			if (!hasNext())
				throw new NoSuchElementException();
			StringBuilder sb = new StringBuilder();
			int b = readByte();
			while (isPrintableChar(b)) {
				sb.appendCodePoint(b);
				b = readByte();
			}
			return sb.toString();
		}

		public long nextLong() {
			if (!hasNext())
				throw new NoSuchElementException();
			long n = 0;
			boolean minus = false;
			int b = readByte();
			if (b == '-') {
				minus = true;
				b = readByte();
			}
			if (b < '0' || '9' < b) {
				throw new NumberFormatException();
			}
			while (true) {
				if ('0' <= b && b <= '9') {
					n *= 10;
					n += b - '0';
				} else if (b == -1 || !isPrintableChar(b)) {
					return minus ? -n : n;
				} else {
					throw new NumberFormatException();
				}
				b = readByte();
			}
		}

		public int nextInt() {
			return (int) nextLong();
		}
	}

	public static void tr(Object... objects) {
		System.out.println(Arrays.deepToString(objects));
	}
}

import java.io.*;
import java.util.StringTokenizer;

public class Main {

    static int N;
    static String S;
    static int Q;
    static int[] K;

    public static void main(String[] args) {
        FastScanner sc = new FastScanner(System.in);
        N = sc.nextInt();
        S = sc.next();
        Q = sc.nextInt();
        K = sc.nextIntArray(Q);

        long[] ans = solve();
        PrintWriter pw = new PrintWriter(System.out);
        for (long i : ans) {
            pw.println(i);
        }
        pw.flush();
    }

    static long[] solve() {
        long[] ans = new long[Q];
        for (int i = 0; i < Q; i++) {
            ans[i] = calc(K[i]);
        }
        return ans;
    }

    static long calc(int k) {
        int d = 0;
        int m = 0;
        long dm = 0;
        long ret = 0;
        for (int i = 0; i < N; i++) {
            char in = S.charAt(i);
            if( in == 'D' ) {
                d++;

            } else if( in == 'M' ) {
                m++;
                dm += d;

            } else if( in == 'C' ) {
                ret += dm;
            }

            if( i >= k-1 ) {
                char out = S.charAt(i-k+1);
                if( out == 'D' ) {
                    d--;
                    dm -= m;

                } else if( out == 'M' ) {
                    m--;
                }
            }

            // System.out.println(i + " " + d + " " + m + " " + dm + " " + ret);
        }
        return ret;
    }

    @SuppressWarnings("unused")
    static class FastScanner {
        private BufferedReader reader;
        private StringTokenizer tokenizer;

        FastScanner(InputStream in) {
            reader = new BufferedReader(new InputStreamReader(in));
            tokenizer = null;
        }

        String next() {
            if (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    tokenizer = new StringTokenizer(reader.readLine());
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return tokenizer.nextToken();
        }

        String nextLine() {
            if (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    return reader.readLine();
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return tokenizer.nextToken("\n");
        }

        long nextLong() {
            return Long.parseLong(next());
        }

        int nextInt() {
            return Integer.parseInt(next());
        }

        int[] nextIntArray(int n) {
            int[] a = new int[n];
            for (int i = 0; i < n; i++)
                a[i] = nextInt();
            return a;
        }

        long[] nextLongArray(int n) {
            long[] a = new long[n];
            for (int i = 0; i < n; i++)
                a[i] = nextLong();
            return a;
        }
    }
}

