        int[] d = new int[n + 1];
        for (int i = 1; i <= n; i++) {
            if (s[i - 1] == 'D') {
                d[i]++;
            }
        }
        for (int i = 1; i <= n; i++) {
            d[i] += d[i - 1];
        }
        int[] m = new int[n + 1];
        for (int i = 1; i <= n; i++) {
            if (s[i - 1] == 'M') {
                m[i]++;
            }
        }
        for (int i = 1; i <= n; i++) {
            m[i] += m[i - 1];
        }
        int[] dm = new int[n + 1];
        for (int i = 1; i <= n; i++) {
            if (s[i - 1] == 'M') {
