				}
			}

			for (var i = 0; i < n; i++)
			{
				if (s[i] != 'M') { continue; }

				for (var j = 0; j < numD; j++)
				{
					if (i < indexD[j]) { continue; }

					for (var k = 0; k < numC; k++)
					{
						if (i > indexC[k]) { continue; }

						dc[j, k].NumM++;
					}
				}
			}

			foreach (var k in ks)
			{
				var result = 0;
				foreach (var cell in dc)
				{
					if (cell.Distance >= k) { continue; }

					result += cell.NumM;
				}

				Console.WriteLine(result);
			}
		}
	}

	class MatrixDC
	{
		public int Distance { get; set; }
		public int NumM { get; set; }
	}
}

