static class CodeJam
{
    class Solver
    {
        private int N;
        private string S;

        public Solver(int N, string S)
        {
            this.N = N;
            this.S = S;
        }

        public long Solve(int k)
        {
            long C = 0;
            var D = new long[N];
            var M = new long[N];
            var DM = new long[N];
            for (int i = 0; i < N; ++i)
            {
                if (i > 0)
                {
                    D[i] = D[i - 1];
                    M[i] = M[i - 1];
                    DM[i] = DM[i - 1];
                }
                if (i >= k)
                {
                    switch (S[i - k])
                    {
                    case 'D':
                        --D[i];
                        DM[i] -= M[i];
                        break;
                    case 'M':
                        --M[i];
                        break;
                    }
                }
                switch (S[i])
                {
                case 'D':
                    ++D[i];
                    break;
                case 'M':
                    ++M[i];
                    DM[i] += D[i];
                    break;
                case 'C':
                    C += DM[i];
                    break;
                }
            }
            return C;
        }
    }

    static void Main(string[] args)
    {
        int N = int.Parse(Console.ReadLine());
        string S = Console.ReadLine();
        var solver = new Solver(N, S);
        int Q = int.Parse(Console.ReadLine());
        int[] K = Array.ConvertAll(Console.ReadLine().Split(), int.Parse);
        foreach (int k in K)
        {
            Console.WriteLine(solver.Solve(k));
        }
    }
}

