                var cList = new List<int>();
                for (int i = 0; i < s.Length; i++)
                {
                    if (i != 0)
                        mCounts[i] = mCounts[i - 1];
                    switch (s[i])
                    {
                        case 'D':
                            dList.Add(i);
                            break;
                        case 'M':
                            mCounts[i]++;
                            break;
                        case 'C':
                            cList.Add(i);
                            break;
                    }
                }
                dIndexes = dList.ToArray();
                cIndexes = cList.ToArray();
            }

            var cStart = 0;
            var kDMC = new int[N + 1];
            foreach (var dIndex in dIndexes)
            {
                while (cStart < cIndexes.Length && cIndexes[cStart] < dIndex) cStart++;
                for (int i = cStart; i < cIndexes.Length; i++)
                {
                    kDMC[cIndexes[i] - dIndex] += mCounts[cIndexes[i]] - mCounts[dIndex];
                }
            }

            for (int i = 1; i < kDMC.Length; i++)
                kDMC[i] += kDMC[i - 1];

            return AllLines(k.Select(i => kDMC[i - 1]));
        }

    }
}

