    internal class Solution
    {
        public int N, Q;
        public string S;
        public int[] K;
        public long MOD = 1000000007;

        public void Run()
        {
            N = Input.ReadInt();
            S = Console.ReadLine();
            Q = Input.ReadInt();
            K = Input.ReadIntArray();

            for (int q = 0; q < Q; q++)
            {
                long r = 0;
                int k = K[q];

                long d = 0;
                long dm = 0;
                long m = 0;

                for (int i = 0; i < N; i++)
                {
                    {
                        if (S[i] == 'D')
                        {
                            d++;
                        }

                        if (S[i] == 'M')
                        {
                            m++;
                            dm += d;
                        }

                        if (S[i] == 'C')
                        {
                            r += dm;
                        }
                    }

                    if (i >= k - 1)
                    {
                        if (S[i - k + 1] == 'D')
                        {
                            d--;
                            dm -= m;
                        }

                        if (S[i - k + 1] == 'M')
                        {
                            m--;
                        }
                    }
                }
                Console.WriteLine(r);
            }
        }
    }

