				sb.Append(item);
				sb.Append(" ");
			}
			Console.WriteLine(sb.ToString());
		}
	}

	public class Solver
	{
		readonly IReader _reader;
		readonly IWriter _writer;

		public Solver(IReader reader = null, IWriter writer = null) {
			if (reader == null) {
				_reader = new ConsoleReader();
			} else {
				_reader = reader;
			}

			if (writer == null) {
				_writer = new ConsoleWriter();
			} else {
				_writer = writer;
			}
		}

		public void Run() {
			//// 整数の入力
			//int a = int.Parse(Console.ReadLine());
			//// スペース区切りの整数の入力
			//string[] input = Console.ReadLine().Split(' ');
			//int b = int.Parse(input[0]);
			//int c = int.Parse(input[1]);
			//// 文字列の入力
			//string s = Console.ReadLine();
			////出力
			//Console.WriteLine((a + b + c) + " " + s);

			var N = _reader.ReadInt();
			//Console.WriteLine(N);

			// DMCを数値化
			var S = _reader.ReadLine();
			byte[] s_ary = new byte[S.Length];
			for (int i = 0; i < S.Length; i++) {
				var c = S[i];
				switch (c) {
					case 'D': s_ary[i] = 1; break;
					case 'M': s_ary[i] = 2; break;
					case 'C': s_ary[i] = 3; break;
				}
			}
			//s_ary.Dump();
			_reader.ReadInt();

			IEnumerable<int> k_ary = _reader.ReadLine().Split(' ').Select<string, int>((s) => {
				return int.Parse(s);
			});
			//k_ary.Dump();

			foreach (var k in k_ary) {
				int sect_len = k - 1;
				ulong d_num = 0;
				ulong m_num = 0;
				ulong dm_num = 0;
				ulong ans = 0;

				// 右端のindexをインクリメントしていく
				for (int r = 0; r < N; r++) {
					// 追加される文字の処理
					var c = s_ary[r];
					if (c == 3) // C
						ans += dm_num;
					else if (c == 1) // D
						++d_num;
					else if (c == 2) {// M
						dm_num += d_num;
						++m_num;
					}

					// 左端から区間外に飛び出す文字の処理
					if (0 <= r - sect_len) {
						var lc = s_ary[r - sect_len];
						if (lc == 1) {// D
							dm_num -= m_num;
							--d_num;
						} else if (lc == 2) {// 
							--m_num;
						}
					}
				}
				_writer.WriteLine(ans);
			}
}
	}

