class Program
{
    public static bool chmin<T>(ref T num, T val) where T : IComparable<T>
    { if (num.CompareTo(val) == 1) { num =val; return true; } return false; }
    public static bool chmax<T>(ref T num, T val) where T : IComparable<T>
    { if (num.CompareTo(val) == -1) { num = val; return true; } return false; }
    public static void swap<T>(ref T v1, ref T v2)
    { var t = v2; v2 = v1; v1 = t; }
    static void Main(string[] args)
    {
        var sw = new StreamWriter(Console.OpenStandardOutput()) { AutoFlush = false };
        Console.SetOut(sw);
        new Program().Solve();
        Console.Out.Flush();
    }
    void Solve()
    {
        var num = Input.num;
        var str = ReadLine();
        var q = Input.num;
        while (q-- > 0)
        {
            var k = Input.Next<int>();
            long d = 0,m=0, ct = 0, res = 0;
            for (var i = 0; i < num; i++)
            {
                if (i >= k)
                {
                    if (str[i - k] == 'D') { d--; ct -= m; }
                    else if (str[i - k] == 'M') m--;
                }
                if (str[i] == 'D') d++;
                else if (str[i] == 'M') { m++; ct += d; }
                else if (str[i] == 'C')
                    res += ct;
            }
            WriteLine(res);
        }
    }
}

