    class Program
    {
        static void Main(string[] args)
        {
            var N = ReadInt();
            var S = Read();
            var Q = ReadInt();
            var k = ReadArrayInt();
            var D = new long[N + 1];
            var M = new long[N + 1];
            var DM = new long[N + 1];
            for (int i = 0; i < N; i++)
            {
                if (S[i] == 'D')
                {
                    D[i + 1] = D[i] + 1;
                    M[i + 1] = M[i];
                    DM[i + 1] = DM[i];
                }
                else if (S[i] == 'M')
                {
                    D[i + 1] = D[i];
                    M[i + 1] = M[i] + 1;
                    DM[i + 1] = DM[i] + D[i];
                }
                else
                {
                    D[i + 1] = D[i];
                    M[i + 1] = M[i];
                    DM[i + 1] = DM[i];
                }
            }
            foreach (var kk in k)
            {
                var ans = 0L;
                for (int i = 0; i < N; i++)
                {
                    if (S[i] == 'C')
                    {
                        ans += DM[i];
                        if (i >= kk - 1)
                        {
                            ans -= D[i - kk + 1] * (M[i] - M[i - kk + 1]);
                            ans -= DM[i - kk + 1];
                        }
                    }
                }
                Console.WriteLine(ans);
            }

            Console.WriteLine();
            Console.ReadLine();
        }

        static string Read() { return Console.ReadLine(); }
        static int ReadInt() { return int.Parse(Read()); }
        static long ReadLong() { return long.Parse(Read()); }
