package main

import (
	"bufio"
	"fmt"
	"os"
	"strconv"
	"strings"
)

func main() {
	io := newIo()
	defer io.Flush()
	N := io.NextInt()
	S := io.Next()
	Q := io.NextInt()
	K := make([]int, Q)
	for q := range K {
		K[q] = io.NextInt()
	}

	var dList []int
	sumM := make([]int, N+1)
	sumC := make([]int, N+1)
	sumMC := make([]int, N+1)
	sumM[0] = 0
	sumC[0] = 0
	sumMC[0] = 0

	for i, s := range S {
		sumC[i+1] = sumC[i]
		sumMC[i+1] = sumMC[i]

		if s == 'D' {
			dList = append(dList, i)
		}
		if s == 'M' {
			sumM[i+1] = sumM[i] + 1
		} else {
			sumM[i+1] = sumM[i]
		}
		if s == 'C' {
			sumC[i+1] = sumC[i] + 1
			sumMC[i+1] = sumMC[i] + sumM[i]
		} else {
			sumC[i+1] = sumC[i]
			sumMC[i+1] = sumMC[i]
		}
	}
	for _, k := range K {
		result := 0
		for _, d := range dList {
			to := d + k
			if to > N {
				to = N
			}
			result += (sumMC[to] - sumMC[d]) - ((sumC[to] - sumC[d]) * sumM[d])
