  long[] cs = new long[N+1];
  foreach(i; 0..N) {
    ds[i+1] += ds[i];
    ms[i+1] += ms[i];
    cs[i+1] += cs[i];
    if (str[i] == 'D') ds[i+1]++;
    if (str[i] == 'M') ms[i+1]++;
    if (str[i] == 'C') cs[i+1]++;
  }

  foreach(k; ks) {
    long s = 0;
    long[] xs = new long[N+1];
    foreach(i; 0..N) {
      xs[i+1] += xs[i];
      if (str[i] == 'C') {
        xs[i+1] += ds[max(0, i-k+1)];
      }
    }

    foreach(i; 0..N) {
      if (str[i] == 'M') {
        s += (cs[min(N-1, i+k-1) + 1] - cs[i]) * ds[i+1] - (xs[min(N-1, i+k-1) + 1] - xs[i]);
      }
    }
    s.writeln;
  }
}

