long solve(int n, string s, int k) {
    auto mcs = new long[](n + 1);

    long cntm, cntc;
    long mc;

    foreach (i ; 0 .. k - 1) {
        if (s[i] == 'M') {
            cntm++;
        }
        else if (s[i] == 'C') {
            cntc++;
            mc += cntm;
        }
    }

    mcs[0] = mc;

    foreach (i ; k - 1 .. n) {
        if (s[i - (k - 1)] == 'M') {
            mc -= cntc;
            cntm--;
        }
        else if (s[i - (k - 1)] == 'C') {
            cntc--;
        }

        if (s[i] == 'M') {
