        }

        mcs[i - (k - 1) + 1] = mc;
    }

    debug {
        writeln(mcs);
    }

    foreach (i ; n - (k - 1) + 1 .. n + 1) {
        if (s[i-1] == 'M') {
            mc -= cntc;
            cntm--;
        }
        else if (s[i-1] == 'C') {
