  return R

proc height*(A: Matrix): Natural {.inline.} =
  A.len()

proc width*(A: Matrix): Natural {.inline.} =
  A[0].len()

proc `+`*(A: Matrix, B: Matrix): Matrix =
  assert height(A) == height(B)
  assert width(A) == width(B)
  let (N, M) = (height(A), width(A))
  var C = initMatrix(N, M)
  for i in 0 .. N - 1:
    for j in 0 .. M - 1:
      C[i][j] = A[i][j] + B[i][j]
  return C

proc `-`*(A: Matrix, B: Matrix): Matrix =
  assert height(A) == height(B)
  assert width(A) == width(B)
  let (N, M) = (height(A), width(A))
  var C = initMatrix(N, M)
  for i in 0 .. N - 1:
    for j in 0 .. M - 1:
      C[i][j] = A[i][j] - B[i][j]
  return C

proc `*`*(A: Matrix, B: Matrix): Matrix =
  assert width(A) == height(B)
  let (N, P, M) = (height(A), width(A), width(B))
  var R = initMatrix(N, M)
  for i in 0 .. N - 1:
    for j in 0 .. M - 1:
      for k in 0 .. P - 1:
        R[i][j] += A[i][k] * B[k][j]
  return R

proc `^`*(A: Matrix, k: Natural): Matrix =
  assert height(A) == width(A)
  let N = height(A)
  var (A, k, R) = (A, k, initIdentityMatrix(N, 1))
  while k > 0:
    if bool(k and 1):
      R = R * A
    A = A * A
    k = k shr 1
  return R

proc `$`*(A: Matrix): string =
  let N = height(A)
  result = ""
  for i in 0 .. N - 1:
    result = result & $A[i]
    if i < N - 1:
      result.add("\n")

