type
  MergeOperator*[T] = proc(a: T, b: T): T
  SegmentTree*[T] = object
    node: seq[T]
    identityElement: T
    internalNodeCount: Natural
    merge: MergeOperator[T]

proc initSegmentTree*[T](n: Natural, identityElement: T, merge: MergeOperator[T]): SegmentTree[T] =
  var n = nextPowerOfTwo(n)
  result.node = newSeqWith(2 * n, identityElement)
  result.identityElement = identityElement
  result.internalNodeCount = n - 1
  result.merge = merge

proc build*[T](self: var SegmentTree[T], data: openarray[T]) =
  for i in 1 .. data.high:
    self.node[self.internalNodeCount + i] = data[i]
  for i in countdown(self.internalNodeCount, 1):
    self.node[i] = self.merge(self.node[2 * i], self.node[2 * i + 1])

proc update*[T](self: var SegmentTree[T], x: Natural, value: T) =
  var i = x + self.internalNodeCount
  self.node[i] = value
  while i > 1:
    i = i shr 1
    self.node[i] = self.merge(self.node[2 * i], self.node[2 * i + 1])

proc fold*[T](self: var SegmentTree[T], l: Natural, r: Natural): T =
  var l = l + self.internalNodeCount
  var r = r + self.internalNodeCount + 1
  var leftResult = self.identityElement
  var rightResult = self.identityElement
  while l < r:
    if (l and 1) == 1:
      leftResult = self.merge(leftResult, self.node[l])
      inc l
    if (r and 1) == 1:
      dec r
      rightResult = self.merge(self.node[r], rightResult)
    l = l shr 1
    r = r shr 1
  result = self.merge(leftResult, rightResult)

