proc buildCumTab(a: seq[int]): seq[int] =
  let n = a.len()
  var c = newSeq[int](n + 1)
  for i in 1..n:
    c[i] = c[i - 1] + a[i - 1]
  return c

# [s, t)
proc lookupCumTab(c: seq[int]; s, t: int): int = c[t] - c[s]

proc main() =
  let n = readInt1()
  let s = readLine()
  let q = readInt1()
  let qq = readSeq().map(parseInt)

  let ddd = s.map(it => (if it == 'D': 1 else: 0))
  let mmm = s.map(it => (if it == 'M': 1 else: 0))
  let ccc = s.map(it => (if it == 'C': 1 else: 0))
  let dCum = ddd.buildCumTab()
  let mCum = mmm.buildCumTab()
  let cCum = ccc.buildCumTab()

  var nextM = newSeq[int](n + 1)
  nextM[n] = n
  for i in countdown(n - 1, 0):
    nextM[i] = nextM[i + 1]
    if s[i] == 'M':
      nextM[i] = i

  var total = 0
  for i in 0..<n:
    if s[i] != 'M':
      continue
    total += dCum.lookupCumTab(0, i) * cCum.lookupCumTab(i, n)

  var dp = newSeq[int](n + 1)
  dp[n] = 0
  for i in countdown(n - 1, 0):
    dp[i] = dp[i + 1]
    if s[i] == 'M':
      dp[i] += cCum.lookupCumTab(i, n)

  for k in qq:
    var bad = 0
    for i in 0..<n:
      if s[i] != 'D':
        continue
      if i + k >= n:
        continue
      bad += dp[i + k] + mCum.lookupCumTab(i, i + k) * cCum.lookupCumTab(i + k, n)
    let ans = total - bad
    echo ans

main()

