import collections

class VR:
    def __init__(self):
        self.ranges = []
    def add(self, rng):
        self.ranges.append(rng)
    def count(self, n):
        ret = 0
        for l, r in self.ranges:
            ret += (l <= n and n < r)
        return ret

def f(k):
