    pd = pm = 0
    qd = collections.deque()
    for i, s in enumerate(S):
        cd = pd
        cm = pm
        if len(qd) and qd[0][1] <= i:
            e = qd.popleft()
            cd -= e[2]
            cm -= e[2] * evr.count(e[0])

        if s == 'D':
            cd += 1
            qd.append((i, i+k, 1))
        elif s == 'M':
            cm += cd
            evr.add((max(0, i - k), i))
        elif s == 'C':
            ret += cm
        pd = cd
        pm = cm

    return ret

