def shakutori(N,S,k):
    out=0
    cntM=[0]*N
    for i in range(N):
        if S[i]=='M':
            cntM[i]+=1+cntM[i-1]
        else:
            cntM[i]=cntM[i-1]
    #print(cntM)
    for a in range(N):
        if S[a]=='D':
            for c in range(a+1, a+k):
                if c<N and S[c]=='C':
                    out+=cntM[c]-cntM[a]
    return out

