def dmc(s, k):
  if s.find("M") >= s.find("C"):
    return [0,0]
  elif k > len(s):
    return dmc(s, len(s))
  elif k == 3:
    if s[0:3] == "DMC":
      return [1, 1]
    else:
      return [0, s[0:2].count("M")]
  elif s[k-1] == "C":
    return [dmc(s, k-1)[0] + dmc(s, k-1)[1], dmc(s, k-1)[1]]
  elif s[k-1] == "M":
    return [dmc(s, k-1)[0], dmc(s, k-1)[1] +1]
  else:
    return dmc(s, k-1)

