D = 0
for c in S:
    if c == 'D':
        D += 1

data0 = [0]*(D+1)
data1 = [0]*(D+1)
def _add(data, k, x):
    while k <= D:
        data[k] += x
        k += k & -k
def add(l, r, x):
    _add(data0, l, -x*(l-1))
    _add(data0, r, x*(r-1))
    _add(data1, l, x)
    _add(data1, r, -x)

def _get(data, k):
    s = 0
    while k:
        s += data[k]
        k -= k & -k
    return s
def query(l, r):
    return _get(data1, r-1) * (r-1) + _get(data0, r-1) - _get(data1, l-1) * (l-1) - _get(data0, l-1)

def solve(k):
    global data0, data1
    data0 = [0]*(D+1)
    data1 = [0]*(D+1)

    que = deque()
    res = 0
    l = r = 1
    for i, c in enumerate(S):
        while que and i-que[0] >= k:
            que.popleft()
            l += 1

        if c == 'D':
            r += 1
            que.append(i)
        elif c == 'M':
            add(l, r, 1)
        elif c == 'C':
            res += query(l, r)
    return res

