    q = int(input())
    k = list(map(int, input().split()))

    ans = [0] * q
    for i in range(q):
        d = 0
        m = 0
        m_total = 0
        m_delta = deque()
        for j, x in enumerate(s):
            if j-k[i] >= 0:
                if s[j-k[i]] == 'D':
                    d -= 1
                    m_first = m_delta.popleft()
                    m -= m_total - m_first
            if x == 'D':
                d += 1
                m_delta.append(m_total)
            elif x == 'M':
                m += d
                m_total += 1
            elif x == 'C':
                ans[i] += m

    for x in ans:
        print(x)


