  num_m = [0] * (N+1)
  num_dm = [0] * (N+1)
  res = 0
  for i, s in enumerate(S, 1):
    num_d[i] += num_d[i-1]
    num_m[i] += num_m[i-1]
    num_dm[i] += num_dm[i-1]
