use std::collections::VecDeque;

fn main() {
    input!{
        n: usize,
        s: chars,
        q: usize,
        ks: [usize; q],
    }

    for &k in ks.iter() {
        let mut ds = VecDeque::new();
        let mut ms = VecDeque::new();
        let mut ans = 0;
        let mut cur = 0;

        for i in 0..n {
            while ds.len() > 0 && i - ds.front().unwrap() >= k {
                ds.pop_front();
                cur -= ms.len();
            }
            while ms.len() > 0 && i - ms.front().unwrap() >= k {
                ms.pop_front();
            }

            if s[i] == 'D' {
                ds.push_back(i);
            } else if s[i] == 'M' {
                ms.push_back(i);
                cur += ds.len();
            } else if s[i] == 'C' {
                ans += cur;
            }
        }

        println!("{}", ans);
    }
}

