fn solve() {
    let n = get!(usize);
    let s = get!(String).chars().collect::<Vec<_>>();
    let q = get!(usize);
    let kl = get!([usize]);

    let mut msums = vec![0; n + 1];
    let mut csums = vec![0; n + 1];
    let mut mcsums = vec![0; n + 1];
    let mut dlist = Vec::new();
    for i in 0..n {
        msums[i + 1] = msums[i];
        csums[i + 1] = csums[i];
        mcsums[i + 1] = mcsums[i];
        match s[i] {
            'D' => {
                dlist.push(i);
            }
            'M' => {
                msums[i + 1] += 1;
            }
            'C' => {
                csums[i + 1] += 1;
                mcsums[i + 1] += msums[i + 1];
            }
            _ => (),
        }
    }

    for k in kl {
        let mut count = 0usize;
        for &i in &dlist {
            let i = i + 1;
            let tmp = mcsums[min!(i + k - 1, n)]
                - mcsums[i]
                - (csums[min!(i + k - 1, n)] - csums[i]) * msums[i];
            count += tmp;
        }
        println!("{}", count);
    }
}

