    for i in 0..n {
        msums[i + 1] = msums[i];
        csums[i + 1] = csums[i];
        mcsums[i + 1] = mcsums[i];
        match s[i] {
            'D' => {
                dlist.push(i);
            }
            'M' => {
                msums[i + 1] += 1;
            }
            'C' => {
                csums[i + 1] += 1;
                mcsums[i + 1] += msums[i + 1];
            }
            _ => (),
        }
    }

