fn main() {
    let N = read!(usize);
    let S = rl().chars().collect::<Vec<_>>();
    let _Q = read!(usize);
    let K = read![[usize]];

    for k in K {
        debug!(k);

        let mut total = 0_i64;

        // いまの区間に含まれる D の個数
        let mut d_count = 0_i64;

        // いまの区間に含まれる M の個数
        let mut m_count = 0_i64;

        // いまの区間に含まれる DM ペアの個数
        let mut dm_count = 0_i64;

        let mut l = 0;
        for r in 0..N {
            if r - l >= k {
                // 次の区間幅を k に抑えるため、区間先頭を除外する。
                if S[l] == 'D' {
                    d_count -= 1;
                    dm_count -= m_count;
                }
                if S[l] == 'M' {
                    m_count -= 1;
                }
                l += 1;
            }

            if S[r] == 'D' {
                d_count += 1;
            }
            if S[r] == 'M' {
                // 区間の末尾に M が出現することで、区間内の DM ペアの個数は D の個数だけ増える。
                m_count += 1;
                dm_count += d_count;
                debug!((r, S[r], d_count, m_count, dm_count));
            }
            if S[r] == 'C' {
                // 区間内の DM ペアの個数だけ DMC が見つかったので数える。
                total += dm_count;
                debug!((r, S[r], dm_count, total));
            }
        }

        println!("{}", total);
    }
}

