fn solve<R: std::io::BufRead, W: std::io::Write>(io: &mut IO<R, W>) {
    let n: usize = io.readln();
    let cs: Vec<char> = io.readln();
    let _q: usize = io.readln();
    let ks: Vec<usize> = io.readln();

    for k in ks {
        let mut freq: [usize; 4] = [0; 4];
        let mut res = 0;
        for i in 0..k {
            match cs[i] {
                'D' => {
                    freq[0b10] += 1;
                }
                'M' => {
                    freq[0b11] += freq[0b10];
                    freq[0b01] += 1;
                }
                'C' => {
                    res += freq[0b11];
                }
                _ => {}
            }
        }
        for i in k..n {
            match cs[i - k] {
                'D' => {
                    freq[0b10] -= 1;
                    freq[0b11] -= freq[0b01];
                }
                'M' => {
                    freq[0b01] -= 1;
                }
                _ => {}
            }
            match cs[i] {
                'D' => {
                    freq[0b10] += 1;
                }
                'M' => {
                    freq[0b11] += freq[0b10];
                    freq[0b01] += 1;
                }
                'C' => {
                    res += freq[0b11];
                }
                _ => {}
            }
        }
        io.writeln(res);
    }
}

