        let mut v = top.1;
        let mut l = top.0 * -1;
        if l > d[v]{
            continue;
        }
        for i in 0..g[v].len(){
            let nl = l + g[v][i].1;
            let n = g[v][i].0;
            if d[n] > nl{
                prev[n] = v;
                d[n] = nl;
                h.push((nl*-1, n));
            }
        }
    }
    (prev, d)
}
fn dijkstra2(X:usize, Y:usize, g:&Vec<Vec<char>>, xx:i64)->Vec<Vec<i64>>{
    let mut d = vec![vec![INF;g[0].len()];g.len()];
    d[X][Y] = 0;
    let mut h = BinaryHeap::new();
    h.push((0, X as i64, Y as i64));
    let dx = vec![0,0,-1, 1];
    let dy = vec![1, -1, 0, 0];
    while(h.len() != 0){
        let mut top = h.pop().unwrap();
        let mut x = top.1;
        let mut y = top.2;
        let mut l = top.0 * -1;
        if l > d[x as usize][y as usize]{
            continue;
        }
        for i in 0..4{
            let mut nx = dx[i]+x;
            let mut ny = dy[i]+y;
            if 0<=nx && nx<g.len() as i64 && 0<=ny && ny<g[0].len() as i64{
                let mut nx = nx as usize;
                let mut ny = ny as usize;
                let nl = l + if g[nx][ny] == '#'{xx}else{1};
                if d[nx][ny]>nl{
                    d[nx][ny] = nl;
                    h.push((nl*-1, nx as i64, ny as i64));
                }
            }

        }
    }
    d
}
