macro_rules! parse {
    ($it: ident) => {
        $it.next().unwrap().parse().unwrap()
    };
    ($it: ident,2) => {
        (parse!($it), parse!($it))
    };
    ($it: ident,3) => {
        (parse!($it), parse!($it), parse!($it))
    };
    ($it: ident,4) => {
        (parse!($it), parse!($it), parse!($it), parse!($it))
    };
    ($it: ident, $n: expr) => {
        (&mut $it).take($n).map(|e| e.parse().unwrap()).collect();
    };
}

fn bsearch<T: Ord>(v: &Vec<T>, x: &T) -> usize {
    if v.len() == 0 || v[0] <= *x {
        0
    } else {
        let mut l = 0;
        let mut r = v.len();
        while r - l > 1 {
            let m = (r + l) / 2;
            if v[m] >= *x {
                r = m
            } else {
                l = m
            }
        }
        r
    }
}

fn solve(s: &str) {
    let mut it = s.split_whitespace();
    let n: usize = parse!(it);
    let s = it.next().unwrap();
    let indices = |target| {
        s.chars()
            .enumerate()
            .filter(|&(i, c)| c == target)
            .map(|(i, c)| i)
            .collect::<Vec<usize>>()
    };
    let a = indices('D');
    let b = indices('M');
    let c = indices('C');
    let c2b = c
        .iter()
        .map(|x| b.binary_search(x).unwrap_err())
        .scan(0, |s, x| {
            *s += x;
            Some(*s)
        })
        .collect::<Vec<_>>();
    let q = parse!(it);
    for _ in 0..q {
        let k: usize = parse!(it);
        let mut ret = 0;
        for ai in a.iter() {
            let l = bsearch(&c, ai);
            let r = bsearch(&c, &(ai + k));
            let j = bsearch(&b, &ai);
            if l >= c.len() || r == 0 || j >= b.len() {
                continue;
            }
            ret += c2b[r - 1] - (r - l) * j - if l > 0 { c2b[l - 1] } else { 0 };
        }
        println!("{}", ret);
    }
}

