pub fn main() {
    let i = stdin();
    let mut o = Vec::new();
    run(i.lock(), &mut o);
    stdout().write_all(&o).unwrap();
}

fn run<R: BufRead, W: Write>(i: R, o: &mut W) {
    let mut i = CpReader::new(i);
    let n = i.read::<usize>();

    #[derive(Copy, Clone, Debug)]
    struct Point {
        idx: usize,
        d: usize,
        m: usize,
        c: usize,
        value: char,
    }
    let mut ps = Vec::new();
    {
        let s = i.read_line().as_bytes();
        let mut p = Point {
            idx: 0,
            d: 0,
            m: 0,
            c: 0,
            value: '_',
        };
        for i in 0..n {
            p.value = s[i] as char;
            p.idx = i;
            let mut is_dmc = true;
            match p.value {
                'D' => p.d += 1,
                'M' => p.m += 1,
                'C' => p.c += 1,
                _ => is_dmc = false,
            }
            if is_dmc {
                ps.push(p);
            }
        }
    }

    let q = i.read::<usize>();
    let k = i.read_vec::<usize>(q);
    for k in k {
        let mut result = 0;
        let mut di_start = 0;
        for mi in 0..ps.len() {
            let mp = ps[mi];
            if mp.value == 'M' {
                let mut ci = mi + 1;
                while di_start < ps.len() && ps[di_start].idx + k < mi {
                    di_start += 1;
                }
                for di in di_start..mi {
                    let dp = ps[di];
                    if dp.value == 'D' {
                        while ci < ps.len() && ps[ci].idx < dp.idx + k {
                            ci += 1;
                        }
                        let cp = ps[ci - 1];
                        let c_count = cp.c - mp.c;
                        result += c_count;
                    }
                }
            }
        }
        writeln!(o, "{}", result).unwrap();
    }
}

