fn solve<R: std::io::BufRead, W: std::io::Write>(io: &mut IO<R, W>) {
    let n: usize = io.readln();
    let cs: Vec<char> = io.readln();
    let _q: usize = io.readln();
    let ks: Vec<usize> = io.readln();

    for k in ks {
        let mut freq: [usize; 8] = [0; 8];
        let mut res = 0;
        for i in 0..k {
            match cs[i] {
                'D' => {
                    freq[0b100] += 1;
                }
                'M' => {
                    freq[0b110] += freq[0b100];
                    freq[0b010] += 1;
                }
                'C' => {
                    res += freq[0b110];
                    freq[0b111] += freq[0b110];
                    freq[0b011] += freq[0b010];
                    freq[0b001] += 1;
                }
                _ => {}
            }
        }
        for i in k..n {
            match cs[i - k] {
                'D' => {
                    freq[0b100] -= 1;
                    freq[0b110] -= freq[0b010];
                    freq[0b111] -= freq[0b011];
                }
                'M' => {
                    freq[0b010] -= 1;
                    freq[0b011] -= freq[0b001];
                }
                'C' => {
                    freq[0b001] -= 1;
                }
                _ => {}
            }
            match cs[i] {
                'D' => {
                    freq[0b100] += 1;
                }
                'M' => {
                    freq[0b110] += freq[0b100];
                    freq[0b010] += 1;
                }
                'C' => {
                    res += freq[0b110];
                    freq[0b111] += freq[0b110];
                    freq[0b011] += freq[0b010];
                    freq[0b001] += 1;
                }
                _ => {}
            }
        }
        io.writeln(res);
    }
}

