    let mut m_count = BIT::<i64>::new(2*n);
    for i in 0..n {
        if s[i] == 'M' {
            m_count.add(i, 1);
        }
    }
    let mut mc_count = BIT::<i64>::new(2*n);
    let mut m_total = 0;
    for i in 0..n {
        if s[i] == 'M' {
            m_total += 1;
        }
        if s[i] == 'C' {
            mc_count.add(i, m_total);
        }
    }
    for i in 0..n {
    }
    let mut res = vec![0; nq];
    for left in 0..n {
        for (i, &q) in qs.iter().enumerate() {
            assert!(left + q < 2 * n);
            if s[left] == 'D' {
                res[i] += mc_count.range_sum(left, left + q - 1);
