    };
    ($it: ident,4) => {
        (parse!($it), parse!($it), parse!($it), parse!($it))
    };
    ($it: ident, $n: expr) => {
        (&mut $it).take($n).map(|e| e.parse().unwrap()).collect();
    };
}

fn solve(s: &str) {
    let mut it = s.split_whitespace();
    let n: usize = parse!(it);
    let s = it.next().unwrap();
    let indices = |target| {
        s.chars()
            .enumerate()
            .filter(|&(i, c)| c == target)
            .map(|(i, c)| i)
            .collect::<Vec<usize>>()
    };
    let a = indices('D');
    let b = indices('M');
    let c = indices('C');
    let c2b = c
        .iter()
        .map(|x| b.binary_search(x).unwrap_err())
        .scan(0, |s, x| {
            *s += x;
            Some(*s)
        })
        .collect::<Vec<_>>();
    let q = parse!(it);
    let aicl = a
        .iter()
        .map(|ai| c.binary_search(ai).unwrap_err())
        .collect::<Vec<_>>();
    let cr = (0..(n + 1))
        .map(|x| c.binary_search(&x).unwrap_or_else(|x| x))
        .collect::<Vec<_>>();
    let aibj = a
        .iter()
        .map(|ai| b.binary_search(ai).unwrap_err())
        .collect::<Vec<_>>();
    for _ in 0..q {
        let k: usize = parse!(it);
        let mut ret = 0;
        for (i, ai) in a.iter().enumerate() {
            let l = aicl[i];
            let r = if ai + k > n { c.len() } else { cr[ai + k] };
            let j = aibj[i];
            if l >= c.len() || r == 0 || j >= b.len() {
                continue;
            }
            ret += c2b[r - 1] - (r - l) * j - if l > 0 { c2b[l - 1] } else { 0 };
        }
        println!("{}", ret);
    }
}

