        _ => panic!("")
    }
}

fn f(i: usize, c: char, di: usize, mi: usize, s: &Vec<char>, k: usize, n: usize) -> usize {
    if i == n {
        return 0;
    }
    let mut ans = 0;
    if s[i] == c {
        if c == 'C' {
            ans += if i - di < k { 1 } else { 0 }
        } else {
            let di = if c == 'D' { i } else { di };
            let mi = if c == 'M' { i } else { mi };
            let nc = n_c(c);
            ans += f(i+1, nc, di, mi, s, k, n);
        }
    }
    ans += f(i+1, c, di, mi, s, k, n);
    ans
}

