pub fn solve(s: &str, k: usize) -> usize {
    let s = s.as_bytes();
    let mut d = 0;
    let mut m = 0;
    let mut dm = 0;

    let mut result = 0;
    let mut j = 0;

    for i in 0..s.len() {
        if i - j == k {
            match s[j] {
                b'D' => {
                    d -= 1;
                    dm -= m;
                }
                b'M' => {
                    m -= 1;
                }
                _ => {}
            }
            j += 1;
        }
        match s[i] {
            b'D' => {
                d += 1;
            }
            b'M' => {
                m += 1;
                dm += d;
            }
            b'C' => {
                result += dm;
            }
            _ => {}
        }
    }
    result
}

