fn main() {
    let mut buf = String::new();
    std::io::stdin().read_to_string(&mut buf).unwrap();
    let mut buf_it = buf.split_whitespace();

    let N = buf_it.next().unwrap().parse::<usize>().unwrap();
    let S:Vec<_> = buf_it.next().unwrap().chars().collect();
    let Q = buf_it.next().unwrap().parse::<usize>().unwrap();

    let K:Vec<_> = (0..Q).map(|_|
        buf_it.next().unwrap().parse::<usize>().unwrap()
    ).collect();

    let mut D:Vec<i64> = (0..N+1).map(|_| 0).collect();
    let mut cntM:Vec<i64> = (0..N+1).map(|_| 0).collect();
    let mut sumM:Vec<i64> = (0..N+1).map(|_| 0).collect();
    let mut ans:Vec<i64> = (0..Q).map(|_| 0).collect();
    for (i,&s) in S.iter().enumerate(){
        D[i+1] = D[i];
        cntM[i+1] = cntM[i];
        sumM[i+1] = sumM[i];
        match s {
            'D' => { D[i+1] += 1;},
            'M' => {
                cntM[i+1] += 1;
                sumM[i+1] += D[i];
            },
            'C' => {
                for (j,&k) in K.iter().enumerate(){
                    let ik = max(0,(i as isize) - (k as isize) +1) as usize;
                    let rstD = D[ik];
                    ans[j] += (sumM[i]-sumM[ik]) - rstD * (cntM[i]-cntM[ik]);
                }
            },
            _ => {},
        }
    }

    for &out in &ans{
        println!("{}",out);
    }

}

use std::io::*;
use std::str::FromStr;

fn main() {
    let n: usize = read();
    let s: Vec<char> = read::<String>().chars().collect();
    let q: usize = read();
    let k: Vec<usize> = (0..q).map(|_| read::<usize>()).collect();

    for i in 0..q {
        let k = k[i];
        let mut d = 0;
        let mut m = 0;
        let mut dm = 0;
        let mut ans = 0;
        for j in 0..n {
            match s[j] {
                'D' => d += 1,
                'M' => {
                    m += 1;
                    dm += d;
                }
                'C' => ans += dm,
                _ => {}
            }
            if j >= k - 1 {
                let l = j + 1 - k;
                match s[l] {
                    'D' => {
                        d -= 1;
                        dm -= m
                    }
                    'M' => m -= 1,
                    _ => {}
                }
            }
        }
        println!("{}", ans);
    }
}

fn read<T: FromStr>() -> T {
    let stdin = stdin();
    let stdin = stdin.lock();
    let token: String = stdin
        .bytes()
        .map(|c| c.expect("failed to read char") as char)
        .skip_while(|c| c.is_whitespace())
        .take_while(|c| !c.is_whitespace())
        .collect();
    token.parse().ok().expect("failed to parse token")
}

use std::fs;
use std::io::{stdin, Read};

macro_rules! parse {
    ($it: ident) => {
        $it.next().unwrap().parse().unwrap()
    };
    ($it: ident,2) => {
        (parse!($it), parse!($it))
    };
    ($it: ident,3) => {
        (parse!($it), parse!($it), parse!($it))
    };
    ($it: ident,4) => {
        (parse!($it), parse!($it), parse!($it), parse!($it))
    };
    ($it: ident, $n: expr) => {
        (&mut $it).take($n).map(|e| e.parse().unwrap()).collect();
    };
}

fn solve(s: &str) {
    let mut it = s.split_whitespace();
    let n: usize = parse!(it);
    let s = it.next().unwrap();
    let indices = |target| {
        s.chars()
            .enumerate()
            .filter(|&(i, c)| c == target)
            .map(|(i, c)| i)
            .collect::<Vec<usize>>()
    };
    let a = indices('D');
    let b = indices('M');
    let c = indices('C');
    let c2b = c
        .iter()
        .map(|x| b.binary_search(x).unwrap_err())
        .scan(0, |s, x| {
            *s += x;
            Some(*s)
        })
        .collect::<Vec<_>>();
    let q = parse!(it);
    for _ in 0..q {
        let k: usize = parse!(it);
        let mut ret = 0;
        for ai in a.iter() {
            let l = c.binary_search(&ai).unwrap_err();
            let r = c.binary_search(&(ai + k)).unwrap_or_else(|x| x);
            let j = b.binary_search(&ai).unwrap_err();
            if l >= c.len() || r == 0 || j >= b.len() {
                continue;
            }
            ret += c2b[r - 1] - (r - l) * j - if l > 0 { c2b[l - 1] } else { 0 };
        }
        println!("{}", ret);
    }
}

