use std::cmp;

fn main() {
    read!(n = usize);
    read!(s = String);
    read!();

    let m_count_sums: Vec<usize> = s.chars().lscan(0, |&acc, c| acc + if c == 'M' { 1 } else { 0 }).collect();
    let c_count_sums: Vec<usize> = s.chars().lscan(0, |&acc, c| acc + if c == 'C' { 1 } else { 0 }).collect();
    let mc_count_sums: Vec<usize> = s.chars().zip(&m_count_sums[1..])
        .lscan(0, |&acc, (c, &m_count)| acc + if c == 'C' { m_count } else { 0 })
        .collect();
    let d_indices: Vec<usize> = s.chars().enumerate()
        .filter(|&(_, c)| c == 'D')
        .map(|(i, _)| i)
        .collect();

    for k in read::<Vec<usize>>() {
        let ans: usize = d_indices.iter().map(|&i| {
            mc_count_sums[cmp::min(i+k, n)]
                - mc_count_sums[i]
                - m_count_sums[i] * (c_count_sums[cmp::min(i+k, n)] - c_count_sums[i])
        }).sum();
        echo!(ans);
    }
}

