#[derive(Debug, Copy, Clone)]
struct DM {
    d: i32,
    m: i32,
    dm: i32
}

use std::ops;
impl ops::Add<DM> for DM {
    type Output = DM;
    fn add(self, rhs: DM) -> DM {
        DM {
            d: self.d + rhs.d,
            m: self.m + rhs.m,
            dm: self.dm + rhs.dm + self.d * rhs.m
        }
    }
}

impl DM {
    fn from_char(c: char) -> DM {
        match c {
            'D' => DM { d: 1, m: 0, dm: 0 },
            'M' => DM { d: 0, m: 1, dm: 0 },
            _ => DM { d: 0, m: 0, dm: 0 },
        }
    }

    fn inverse(self) -> DM {
        DM {
            d: -self.d,
            m: -self.m,
            dm: -self.dm + self.d * self.m
        }
    }

    fn e() -> DM {
        DM { d: 0, m: 0, dm: 0 }
    }
}

fn main() {
    let mut sc = Scanner::new();
    let n: usize = sc.cin();
    let s: String = sc.cin();
    let cs: Vec<_> = s.chars().collect();

    let mut memo = vec![];
    {
        let mut ac = DM::e();
        memo.push(ac);
        for &c in cs.iter() {
            let x = DM::from_char(c);
            ac = ac + x;
            memo.push(ac);
        }
    }

    let q: usize = sc.cin();
    for _ in 0..q {
        let k: usize = sc.cin();
        let mut ans = 0;
        for c in 2..n {
            if cs[c] == 'C' {
                if c >= k {
                    let y = memo[c+1-k].inverse() + memo[c];
                    // trace!(c, c+1-k, y);
                    ans += y.dm;
                } else {
                    let y = memo[c];
                    // trace!(c, y);
                    ans += y.dm;
                }
            }
        }
        put!(ans);
    }
}

