fn run<R: BufRead, W: Write>(i: R, o: &mut W) {
    let mut i = CpReader::new(i);
    let _n = i.read::<usize>();
    let s = i.read_line().to_string();
    let q = i.read::<usize>();
    let k = i.read_vec::<usize>(q);
    for k in k {
        writeln!(o, "{}", solve(&s, k)).unwrap();
    }
}
pub fn solve(s: &str, k: usize) -> usize {
    let s = s.as_bytes();
    let mut d = 0;
    let mut m = 0;
    let mut dm = 0;

    let mut result = 0;

    for i in 0..s.len() {
        match s[i] {
            b'D' => {
                d += 1;
            }
            b'M' => {
                m += 1;
                dm += d;
            }
            b'C' => {
                result += dm;
            }
            _ => {}
        }
        if i >= k - 1 {
            match s[i - (k - 1)] {
                b'D' => {
                    d -= 1;
                    dm -= m;
                }
                b'M' => {
                    m -= 1;
                }
                _ => {}
            }
        }
    }
    result
}

