macro_rules! parse {
    ($it: ident) => {
        $it.next().unwrap().parse().unwrap()
    };
    ($it: ident,2) => {
        (parse!($it), parse!($it))
    };
    ($it: ident,3) => {
        (parse!($it), parse!($it), parse!($it))
    };
    ($it: ident,4) => {
        (parse!($it), parse!($it), parse!($it), parse!($it))
    };
    ($it: ident, $n: expr) => {
        (&mut $it).take($n).map(|e| e.parse().unwrap()).collect();
    };
}

fn solve(s: &str) {
    let mut it = s.split_whitespace();
    let n: usize = parse!(it);
    let s = it.next().unwrap();
    let indices = |target| {
        s.chars()
            .enumerate()
            .filter(|&(i, c)| c == target)
            .map(|(i, c)| i)
            .collect::<Vec<usize>>()
    };
    let a = indices('D');
    let b = indices('M');
    let c = indices('C');
    let b2c = b
        .iter()
        .map(|x| c.binary_search(x).unwrap_err())
        .map(|i| if i >= c.len() { None } else { Some(i) })
        .collect::<Vec<_>>();

    let q = parse!(it);
    for _ in 0..q {
        let k: usize = parse!(it);
        let mut ret = 0;
        for start in a.iter() {
            let end = c.binary_search(&(start + k)).unwrap_or_else(|x| x);
            let bi = b.binary_search(&start).unwrap_err();
            if bi >= b.len() {
                continue;
            }
            if let Some(cstart) = b2c[bi] {
                ret += if end > cstart { end - cstart } else { 0 };
            }
        }
        println!("{}", ret);
    }
}

