    let n = read::<usize>();
    let s = read::<String>().chars().collect::<Vec<_>>();
    let q = read::<usize>();
    let ks = read_vec::<usize>();

    let mut accum_m = vec![0; n];
    if s[0] == 'M' {
        accum_m[0] = 1;
    }
    for i in 1..n {
        accum_m[i] = accum_m[i - 1];
        if s[i] == 'M' {
            accum_m[i] += 1;
        }
    }
    let mut accum_mc = vec![0i64; n];
    for i in 1..n {
        accum_mc[i] = accum_mc[i - 1];
        if s[i] == 'C' {
            accum_mc[i] += accum_m[i];
        }
    }

    let mut d_poses = vec![];
    let mut c_poses = vec![];
    for i in 0..n {
        if s[i] == 'C' {
            c_poses.push(i);
        } else if s[i] == 'D' {
            d_poses.push(i);
        }
    }

    for k in ks {
        let mut ans = 0i64;
        for &d_pos in d_poses.iter() {
            let most_right_c_pos = min(n - 1, d_pos + k - 1);
            let most_left_c_idx = c_poses.lower_bound(&d_pos);
            let most_right_c_idx = c_poses.upper_bound(&(d_pos + k - 1));
            let already_consumed = (most_right_c_idx - most_left_c_idx) as i64 * accum_m[d_pos];
            ans += accum_mc[most_right_c_pos] - accum_mc[d_pos] - already_consumed;
        }
        println!("{}", ans);
    }
