    let mut buf_it = buf.split_whitespace();

    let N = buf_it.next().unwrap().parse::<usize>().unwrap();
    let S:Vec<_> = buf_it.next().unwrap().chars().collect();
    let Q = buf_it.next().unwrap().parse::<usize>().unwrap();

    let K:Vec<_> = (0..Q).map(|_|
        buf_it.next().unwrap().parse::<usize>().unwrap()
    ).collect();

    let mut D:Vec<_> = (0..N+1).map(|_| 0).collect();
    let mut cntM = SegmentTree::new(N+1,f,0);
    let mut sumM = SegmentTree::new(N+1,f,0);
    let mut ans:Vec<_> = (0..Q).map(|_| 0).collect();
    for (i,&s) in S.iter().enumerate(){
        D[i+1] = D[i];
        match s{
            'D' => {D[i+1]+=1;},
            'M' => {
                cntM.set(i+1,1);
                sumM.set(i+1,D[i]);
            },
            'C' => {
                for (j,&k) in K.iter().enumerate(){
                    let ik = max(0,i as isize - k as isize +1) as usize;
                    let rstD = D[ik];
                    ans[j] += sumM.get(ik+1,i+1) - rstD * cntM.get(ik+1,i+1);
                }
            },
            _ => {},
        }
    }

    for &out in &ans{
        println!("{}",out);
    }

}

fn f(x:isize,y:isize)->isize{
    x+y
}

struct SegmentTree<N>{
    n: usize,
    T: Vec<N>,
    func: fn(N,N) -> N,
    identity: N,
}

impl<N:Copy> SegmentTree<N> {
    fn new(n:usize,func:fn(N,N) -> N,identity:N) -> SegmentTree<N>{
        let mut T = SegmentTree { n:n,T:Vec::new(),func:func,identity:identity};
        T.init();
        T
    }
    fn init(&mut self){
        self.n = 1<<format!("{:b}",self.n-1).len();
        self.T = (0..(2*self.n-1)).map(|_| self.identity).collect();
    }
    fn set(&mut self,index:usize,value:N){
        let i = index + self.n - 1;
        self.T[i] = value;
        self._update_parent((i-1)/2);
    }
    fn _update_parent(&mut self,i:usize){
        self.T[i] = (self.func)(self.T[i*2+1],self.T[i*2+2]);
        if i>0 { self._update_parent((i-1)/2)}
    }
    fn get(&self,l:usize,r:usize) -> N{
    self._get(l,r,0,0,self.n)
    }
    fn _get(&self,l:usize,r:usize,i:usize,a:usize,b:usize) -> N{
        if l<=a && b<=r {
            self.T[i]
        } else if b<=l || r<=a {
            self.identity
        } else{
            (self.func)(self._get(l,r,2*i+1,a,(a+b)/2),
                        self._get(l,r,2*i+2,(a+b)/2,b))
        }
    }
}

