use std::cmp::min;
use std::str::FromStr;
use std::collections::HashMap;
use std::collections::HashSet;
use std::collections::BinaryHeap;

fn main() {
    let mut buf = String::new();
    std::io::stdin().read_to_string(&mut buf).unwrap();
    let mut buf_it = buf.split_whitespace();

    let N = buf_it.next().unwrap().parse::<usize>().unwrap();
    let S:Vec<_> = buf_it.next().unwrap().chars().collect();
    let Q = buf_it.next().unwrap().parse::<usize>().unwrap();

    let K:Vec<_> = (0..Q).map(|_|
        buf_it.next().unwrap().parse::<usize>().unwrap()
    ).collect();

    let mut A = HashSet::new();
    for (i,&s) in S.iter().enumerate(){
        if s == 'D'{
            A.insert(i as isize);
        }
    }

    for &k in &K{
        let k = k as isize;
        let mut ans = 0;
        let mut B = HashMap::new();
        let mut cntA = 0;
        let mut rstA = 0;
        let mut cntB = 0;
        let mut sumB = 0;
        for i in 0..N{
            let i = i as isize;
            if A.contains(&i){
                cntA += 1;
            }
            if A.contains(&(i-k)){
                rstA += 1;
            }
            if B.contains_key(&(i-k)){
                cntB -= 1;
                sumB -= *B.get(&(i-k)).unwrap();
            }
            if S[i as usize] == 'M'{
                cntB += 1;
                sumB += cntA;
                B.insert(i,cntA);
            }

            if S[i as usize] == 'C'{
                ans += sumB - rstA * cntB;
            }
        }
        println!("{}",ans);
    }


}
